-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('046468d0-e474-518d-997f-efaca1685aa6'::uuid, 'c9872525-9070-5eeb-9367-7ce941ac4fd5'::uuid, 'Dans quel pays l’allemand est-il l’une des quatre langues nationales ?', 'mcq', '["En Autriche","En Suisse","Au Liechtenstein","En Allemagne"]'::jsonb, 1, 'La Suisse a quatre langues nationales : l’allemand, le français, l’italien et le romanche.', 1),
    ('a8332aff-eb42-5a11-97df-65f1f344832d'::uuid, 'c9872525-9070-5eeb-9367-7ce941ac4fd5'::uuid, 'Quelle est la capitale de l’Autriche ?', 'mcq', '["Salzbourg","Innsbruck","Vienne","Graz"]'::jsonb, 2, 'Vienne, en allemand *Wien*, est la capitale de l’Autriche.', 2),
    ('bb968229-d652-56aa-a93e-c6007d45a525'::uuid, 'c9872525-9070-5eeb-9367-7ce941ac4fd5'::uuid, 'Comment appelle-t-on l’allemand standard, celui de l’école et des journaux ?', 'mcq', '["Le Plattdeutsch","Le Schwiizerdütsch","Le Hochdeutsch","Le Dialekt"]'::jsonb, 2, 'Le *Hochdeutsch* est l’allemand commun à tous ; les dialectes varient d’une région à l’autre.', 3),
    ('2fb0148d-9cc6-5df3-949b-eeaed6ec8416'::uuid, 'c9872525-9070-5eeb-9367-7ce941ac4fd5'::uuid, '« Grüß Gott » est une salutation typique…', 'mcq', '["de l’Autriche et du sud de l’Allemagne","de Berlin","du nord de l’Allemagne","de la Suisse romande"]'::jsonb, 0, 'On dit *Grüß Gott* en Bavière et en Autriche, régions de tradition catholique.', 4),
    ('a649bca7-d999-5745-b433-2cb173554a74'::uuid, 'c9872525-9070-5eeb-9367-7ce941ac4fd5'::uuid, 'En Suisse alémanique, on dit bonjour avec…', 'mcq', '["Moin","Servus","Grüezi","Hallöchen"]'::jsonb, 2, '*Grüezi* est le bonjour suisse ; *Moin* est celui du nord de l’Allemagne.', 5),
    ('6068fa52-3536-5a23-99e9-24133cab63ba'::uuid, 'c9872525-9070-5eeb-9367-7ce941ac4fd5'::uuid, 'Parler un dialecte, c’est mal parler allemand.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Un dialecte est une variante régionale de la langue, avec sa grammaire et sa fierté ; ce n’est pas une faute.', 6),
    ('7fe7f597-59e1-5f4b-b326-787ad6f57861'::uuid, 'c9872525-9070-5eeb-9367-7ce941ac4fd5'::uuid, 'Que signifie « die Muttersprache » ?', 'mcq', '["La langue étrangère","La langue maternelle","La langue de la mère patrie","Le dialecte"]'::jsonb, 1, '*Mutter* = mère, *Sprache* = langue : la langue qu’on a apprise en premier.', 7),
    ('31cdd185-4760-5a4b-bbfe-a3f501c348b5'::uuid, 'c9872525-9070-5eeb-9367-7ce941ac4fd5'::uuid, 'Un Autrichien appelle la tomate…', 'mcq', '["der Paradeiser","die Semmel","das Brötli","der Erdapfel"]'::jsonb, 0, 'En Autriche, la tomate est *der Paradeiser* ; *die Semmel* y désigne le petit pain.', 8),
    ('308751b1-c23b-574d-b4bd-f56119862936'::uuid, 'c9872525-9070-5eeb-9367-7ce941ac4fd5'::uuid, 'Qu’est-ce que le « Jugendwort des Jahres » ?', 'mcq', '["Un prix littéraire pour la jeunesse","Le mot jeune de l’année, élu par vote","Un dictionnaire scolaire","Un concours d’orthographe"]'::jsonb, 1, 'Chaque année, un vote désigne le mot le plus représentatif de la langue des jeunes.', 9),
    ('729e3cd5-1faa-565c-9518-5364e66117e8'::uuid, 'c9872525-9070-5eeb-9367-7ce941ac4fd5'::uuid, 'Comment dit-on « bilingue » en allemand ?', 'mcq', '["zweisprachig","doppelsprachig","bisprachlich","zweisprecher"]'::jsonb, 0, '*zwei* = deux, *sprachig* = qui parle une langue : *zweisprachig*.', 10),
    ('85e4892f-36cc-52a8-bccf-59b10c9452be'::uuid, 'c9872525-9070-5eeb-9367-7ce941ac4fd5'::uuid, 'L’allemand est la langue maternelle la plus parlée de l’Union européenne.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec l’Allemagne, l’Autriche, une partie de la Suisse, du Luxembourg et de la Belgique, c’est la première langue maternelle de l’UE.', 11),
    ('b4493ec1-11ef-597f-9dd0-8b7863c47b54'::uuid, 'c9872525-9070-5eeb-9367-7ce941ac4fd5'::uuid, 'Quelle phrase sert à demander de répéter ?', 'mcq', '["Wie sagt man das?","Kannst du das bitte wiederholen?","Ich spreche ein bisschen Deutsch.","Was ist das?"]'::jsonb, 1, '*wiederholen* = répéter. Une phrase clé pour toute conversation.', 12),
    ('1aad3801-317a-5b1e-bbcd-b85ee35397ce'::uuid, '2dc76119-c750-57a9-859c-0e20e8c1efc0'::uuid, 'En Allemagne, quelle est la meilleure note ?', 'mcq', '["6","1","20","10"]'::jsonb, 1, 'Les notes vont de 1 (*sehr gut*) à 6 (*ungenügend*) : 1 est la meilleure.', 1),
    ('5b79f624-5290-54b4-bfa5-524d724fcab4'::uuid, '2dc76119-c750-57a9-859c-0e20e8c1efc0'::uuid, 'Comment s’appelle le bac allemand ?', 'mcq', '["das Zeugnis","die Ausbildung","das Abitur","die Klassenarbeit"]'::jsonb, 2, 'L’*Abitur*, ou *Abi*, clôt les études au *Gymnasium*.', 2),
    ('7dedea3d-004e-504f-9cd6-36ef93b65844'::uuid, '2dc76119-c750-57a9-859c-0e20e8c1efc0'::uuid, 'Qu’est-ce que la « Schultüte » ?', 'mcq', '["Le cartable","Le cornet de bonbons du premier jour d’école","La cantine","Le bulletin de fin d’année"]'::jsonb, 1, 'Le jour de la rentrée en *Grundschule*, l’enfant reçoit ce grand cornet décoré.', 3),
    ('3c0e2036-b4b6-5a88-82f8-7d1fe3e7b0d3'::uuid, '2dc76119-c750-57a9-859c-0e20e8c1efc0'::uuid, 'À quel âge environ les élèves allemands sont-ils orientés après la Grundschule ?', 'mcq', '["6 ans","10 ans","15 ans","18 ans"]'::jsonb, 1, 'La *Grundschule* dure en général quatre ans ; l’orientation se fait vers 10 ans.', 4),
    ('62ddc2df-81c0-5e19-be32-bc665aefe74e'::uuid, '2dc76119-c750-57a9-859c-0e20e8c1efc0'::uuid, 'Qui organise l’école en Allemagne ?', 'mcq', '["L’État fédéral seul","Les Länder","Les communes","L’Union européenne"]'::jsonb, 1, 'L’éducation est une compétence des 16 Länder : les systèmes et les vacances varient.', 5),
    ('9e743ce6-e7a6-5e5f-9f27-f40ccf7a4644'::uuid, '2dc76119-c750-57a9-859c-0e20e8c1efc0'::uuid, 'Que signifie « der Stundenplan » ?', 'mcq', '["L’emploi du temps","La récréation","Le bulletin","La salle de classe"]'::jsonb, 0, '*die Stunde* = l’heure, *der Plan* = le plan : l’emploi du temps.', 6),
    ('f66f0727-c05a-5fd5-ae4a-0d40e4c45675'::uuid, '2dc76119-c750-57a9-859c-0e20e8c1efc0'::uuid, 'Une « Ganztagsschule » est une école…', 'mcq', '["du soir","à la journée entière, avec l’après-midi","réservée aux adultes","privée"]'::jsonb, 1, '*ganzer Tag* = la journée entière : cours et activités jusqu’en fin d’après-midi.', 7),
    ('2a023d11-dd62-5771-95bd-26bfca5b860a'::uuid, '2dc76119-c750-57a9-859c-0e20e8c1efc0'::uuid, 'Le système dual allemand associe…', 'mcq', '["deux langues à l’école","l’entreprise et l’école professionnelle","le collège et le lycée","la ville et la campagne"]'::jsonb, 1, 'L’*Ausbildung* alterne travail en entreprise et cours en école professionnelle.', 8),
    ('27b97c39-7b4b-535f-8297-a462ed7501ba'::uuid, '2dc76119-c750-57a9-859c-0e20e8c1efc0'::uuid, '« Ich habe eine Fünf » est une bonne nouvelle.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Un 5 (*mangelhaft*) est une note insuffisante.', 9),
    ('6d913548-ffe0-5933-a157-264238678a27'::uuid, '2dc76119-c750-57a9-859c-0e20e8c1efc0'::uuid, 'Comment dit-on « les devoirs » ?', 'mcq', '["die Hausaufgaben","die Hausarbeiten","die Schularbeit","die Aufgabenhäuser"]'::jsonb, 0, '*das Haus* + *die Aufgabe* : les tâches à faire à la maison.', 10),
    ('9afc3357-db1d-580c-b85e-16832969f879'::uuid, '2dc76119-c750-57a9-859c-0e20e8c1efc0'::uuid, 'Que veut dire « sitzen bleiben » à l’école ?', 'mcq', '["Rester assis","Redoubler","Être collé","Sécher les cours"]'::jsonb, 1, 'Mot à mot « rester assis » : on reste dans la même classe l’année suivante.', 11),
    ('cf36390e-e8fb-5f75-b58c-bb2d48104f8a'::uuid, '2dc76119-c750-57a9-859c-0e20e8c1efc0'::uuid, 'Qu’est-ce qu’un « Verein » ?', 'mcq', '["Une matière","Un club ou une association","Une école","Un examen"]'::jsonb, 1, 'Le *Verein* (club, association) tient une grande place dans la vie allemande.', 12),
    ('1ecd213f-4790-53a5-acc8-43264ca58474'::uuid, 'da731a53-4415-5ee1-8d91-ab7cb030cfff'::uuid, 'Vers quel pays la plupart des émigrants allemands du XIXe siècle sont-ils partis ?', 'mcq', '["Le Brésil","Les États-Unis","La France","L’Australie"]'::jsonb, 1, 'Des millions d’Allemands ont traversé l’Atlantique vers les États-Unis au XIXe siècle.', 1),
    ('e452de97-14ab-527f-a975-84ad58f6d087'::uuid, 'da731a53-4415-5ee1-8d91-ab7cb030cfff'::uuid, 'Qui étaient les « Gastarbeiter » ?', 'mcq', '["Des touristes","Des travailleurs étrangers recrutés dans les années 1950–1970","Des soldats","Des étudiants en échange"]'::jsonb, 1, 'On les a recrutés pour le miracle économique ; le mot « invité » supposait un départ qui n’a souvent pas eu lieu.', 2),
    ('8843d09f-4174-5ae5-b695-abfcc030a667'::uuid, 'da731a53-4415-5ee1-8d91-ab7cb030cfff'::uuid, 'Que signifie « auswandern » ?', 'mcq', '["Voyager","Immigrer","Émigrer","Randonner"]'::jsonb, 2, '*aus* = hors de : on quitte son pays. *einwandern* = immigrer (*ein* = dans).', 3),
    ('6f6ab8f4-92ff-5808-8916-d204e7936817'::uuid, 'da731a53-4415-5ee1-8d91-ab7cb030cfff'::uuid, 'Que veut dire « das Heimweh » ?', 'mcq', '["Le mal du pays","La maison de vacances","Le mal de mer","La patrie"]'::jsonb, 0, '*Heim* = chez soi, *Weh* = la douleur : la nostalgie de son pays.', 4),
    ('d94815f4-4956-53d3-839f-054ff2e1c563'::uuid, 'da731a53-4415-5ee1-8d91-ab7cb030cfff'::uuid, 'Quelle phrase est correcte pour « Je vais en Suisse » ?', 'mcq', '["Ich fahre nach Schweiz.","Ich fahre in die Schweiz.","Ich fahre zu Schweiz.","Ich fahre in der Schweiz."]'::jsonb, 1, 'Un pays avec article (*die Schweiz*) se construit avec *in* + accusatif pour la direction.', 5),
    ('b4fd69e9-77ef-5045-9f60-9bdc4939ad3c'::uuid, 'da731a53-4415-5ee1-8d91-ab7cb030cfff'::uuid, 'Qu’est-ce qu’une « Jugendherberge » ?', 'mcq', '["Une auberge de jeunesse","Un camp de réfugiés","Une école","Un train de nuit"]'::jsonb, 0, 'L’auberge de jeunesse est née en Allemagne, en 1909.', 6),
    ('9a3df681-e8b0-513a-ab5f-a5e80ac485d8'::uuid, 'da731a53-4415-5ee1-8d91-ab7cb030cfff'::uuid, 'Quelle phrase d’Angela Merkel est restée associée à l’accueil des réfugiés en 2015 ?', 'mcq', '["Ich bin ein Berliner","Wir schaffen das","Wir sind das Volk","Mehr Demokratie wagen"]'::jsonb, 1, '« Nous y arriverons » : la chancelière défendait l’accueil de plus d’un million de réfugiés.', 7),
    ('30b1fd10-d16c-559f-9b63-92bdb7d3b105'::uuid, 'da731a53-4415-5ee1-8d91-ab7cb030cfff'::uuid, 'En Allemagne, environ une personne sur quatre a une histoire migratoire.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle ou au moins l’un de ses parents est né avec une nationalité étrangère.', 8),
    ('501c5fdb-ae9e-50c7-bd3b-e9e393e32621'::uuid, 'da731a53-4415-5ee1-8d91-ab7cb030cfff'::uuid, 'Que signifie « der Flüchtling » ?', 'mcq', '["Le voyageur","Le réfugié","Le fugitif recherché par la police","Le touriste"]'::jsonb, 1, '*flüchten* = fuir : le réfugié fuit une guerre ou une persécution.', 9),
    ('cf8cdc59-61f5-5103-bea0-ee363de36ed0'::uuid, 'da731a53-4415-5ee1-8d91-ab7cb030cfff'::uuid, '« Ich fahre ___ Berlin. » Quel mot complète la phrase ?', 'mcq', '["in","zu","nach","auf"]'::jsonb, 2, 'Devant une ville ou un pays sans article, la direction se dit avec *nach*.', 10),
    ('c5d86bba-12bd-5667-b9a6-8161685032fa'::uuid, 'da731a53-4415-5ee1-8d91-ab7cb030cfff'::uuid, 'Dans quelle ville le Döner en sandwich a-t-il été popularisé ?', 'mcq', '["À Istanbul","À Berlin","À Vienne","À Munich"]'::jsonb, 1, 'Le sandwich au pain et à la viande grillée a été popularisé à Berlin par des immigrés turcs.', 11),
    ('44ecbd09-59a2-53b2-bb8f-997ff67206b0'::uuid, 'da731a53-4415-5ee1-8d91-ab7cb030cfff'::uuid, 'Que signifie « die Heimat » ?', 'mcq', '["La maison louée","Le pays natal, le chez-soi","L’étranger","La frontière"]'::jsonb, 1, '*Heimat* désigne le lieu où l’on se sent chez soi ; un mot chargé d’émotion en allemand.', 12),
    ('56d0526a-ed2e-5e1f-9cdd-5cc3a8a51368'::uuid, 'b49bd2e2-5410-58b3-bf4f-3033848cd127'::uuid, 'Qui a signé le traité de l’Élysée en 1963 ?', 'mcq', '["Mitterrand et Kohl","De Gaulle et Adenauer","Macron et Merkel","Pompidou et Brandt"]'::jsonb, 1, 'Le général de Gaulle et le chancelier Adenauer scellent la réconciliation le 22 janvier 1963.', 1),
    ('a9f5dc75-b5e8-5903-8ba0-6517a08e8236'::uuid, 'b49bd2e2-5410-58b3-bf4f-3033848cd127'::uuid, 'Que signifie le sigle OFAJ ?', 'mcq', '["Office franco-allemand pour la Jeunesse","Organisation fédérale des associations de jeunes","Office de formation des adultes et des jeunes","Orchestre franco-allemand des jeunes"]'::jsonb, 0, 'Créé en 1963, il finance les échanges entre jeunes des deux pays.', 2),
    ('f3090842-a3fe-54da-a7b5-6d52c56e3c7c'::uuid, 'b49bd2e2-5410-58b3-bf4f-3033848cd127'::uuid, 'Quelle date est la Journée franco-allemande ?', 'mcq', '["Le 3 octobre","Le 9 novembre","Le 22 janvier","Le 14 juillet"]'::jsonb, 2, 'C’est l’anniversaire du traité de l’Élysée.', 3),
    ('2e3a4153-1679-53a8-82f3-737d591e99ed'::uuid, 'b49bd2e2-5410-58b3-bf4f-3033848cd127'::uuid, 'Quelle chaîne de télévision est franco-allemande ?', 'mcq', '["ZDF","Arte","TV5","RTL"]'::jsonb, 1, 'Arte, créée en 1992, diffuse ses programmes dans les deux langues.', 4),
    ('8f22c89f-1ffa-555b-8927-3e5ac8afe370'::uuid, 'b49bd2e2-5410-58b3-bf4f-3033848cd127'::uuid, 'Que signifie « der Austausch » ?', 'mcq', '["L’échange","La sortie","Le voyage de classe","La frontière"]'::jsonb, 0, 'On part en *Austausch* pour vivre chez un correspondant.', 5),
    ('a12964d4-b582-5a06-9556-cbffb6a0f771'::uuid, 'b49bd2e2-5410-58b3-bf4f-3033848cd127'::uuid, 'En 1984, Mitterrand et Kohl se sont tenu la main à…', 'mcq', '["Berlin","Verdun","Strasbourg","Bonn"]'::jsonb, 1, 'Sur le lieu de la bataille de 1916, ce geste a symbolisé la réconciliation.', 6),
    ('aba0a53c-36f9-5979-8b29-4419c8731694'::uuid, 'b49bd2e2-5410-58b3-bf4f-3033848cd127'::uuid, 'Quel traité a renouvelé celui de l’Élysée en 2019 ?', 'mcq', '["Le traité de Rome","Le traité de Maastricht","Le traité d’Aix-la-Chapelle","Le traité de Versailles"]'::jsonb, 2, 'Signé à Aix-la-Chapelle (*Aachen*), il approfondit la coopération.', 7),
    ('7f734698-17e8-551d-9c51-b5c502e60bdc'::uuid, 'b49bd2e2-5410-58b3-bf4f-3033848cd127'::uuid, 'En Allemagne, le « Pfand » est…', 'mcq', '["une consigne sur les bouteilles","un plat du soir","une salutation","un jour férié"]'::jsonb, 0, 'On paie quelques centimes de plus et on les récupère en rapportant la bouteille.', 8),
    ('5838f6c4-3532-58dc-b4ca-741ec60a7654'::uuid, 'b49bd2e2-5410-58b3-bf4f-3033848cd127'::uuid, 'Entre Allemands qui se rencontrent, la bise est la règle.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On se serre plutôt la main ; entre amis proches, on se prend parfois dans les bras.', 9),
    ('4d6309cb-fa43-5cc3-b26a-537b7f13284e'::uuid, 'b49bd2e2-5410-58b3-bf4f-3033848cd127'::uuid, 'Comment dit-on « la famille d’accueil » ?', 'mcq', '["die Gastfamilie","die Gästehaus","die Hausfamilie","die Nachbarfamilie"]'::jsonb, 0, '*der Gast* = l’invité : la famille qui reçoit l’invité.', 10),
    ('577d54a2-941b-505c-a781-5b54dca55153'::uuid, 'b49bd2e2-5410-58b3-bf4f-3033848cd127'::uuid, '« Das ist anders als bei uns » signifie…', 'mcq', '["C’est comme chez nous","C’est différent de chez nous","C’est mieux chez nous","Ce n’est pas chez nous"]'::jsonb, 1, '*anders als* = différent de ; *bei uns* = chez nous.', 11),
    ('c1c3e8f2-da6b-5648-ad99-6c2eb0fb2d01'::uuid, 'b49bd2e2-5410-58b3-bf4f-3033848cd127'::uuid, 'Quelle est la devise de l’Union européenne en allemand ?', 'mcq', '["Einigkeit und Recht und Freiheit","In Vielfalt geeint","Wir sind ein Volk","Freiheit für alle"]'::jsonb, 1, '« Unie dans la diversité ». *Einigkeit und Recht und Freiheit* est le début de l’hymne allemand.', 12),
    ('0d1b405c-f84a-5436-97e2-167812180a73'::uuid, 'b019d065-4db1-5894-9125-d309262b3ba1'::uuid, 'Comment dit-on 47 en allemand ?', 'mcq', '["vierzigsieben","siebenundvierzig","vierundsiebzig","siebenvierzig"]'::jsonb, 1, 'L’unité d’abord, puis *und*, puis la dizaine : *sieben-und-vierzig*.', 1),
    ('1877bf7e-4f62-5de3-981c-3e3539b0b13d'::uuid, 'b019d065-4db1-5894-9125-d309262b3ba1'::uuid, '« halb neun » correspond à…', 'mcq', '["8 h 30","9 h 30","9 h 00","8 h 50"]'::jsonb, 0, '*halb neun* = la demie qui mène à neuf heures, donc 8 h 30.', 2),
    ('65473328-d03b-54f6-828f-9157cc0948cc'::uuid, 'b019d065-4db1-5894-9125-d309262b3ba1'::uuid, 'Quelle est l’orthographe correcte de 16 ?', 'mcq', '["sechszehn","sechzehn","sechsehn","sechzen"]'::jsonb, 1, 'Le *s* de *sechs* tombe devant *-zehn* et *-zig* : *sechzehn*, *sechzig*.', 3),
    ('70e948b4-1680-5e22-9c4a-7e089ecaef26'::uuid, 'b019d065-4db1-5894-9125-d309262b3ba1'::uuid, '« Viertel vor drei » correspond à…', 'mcq', '["3 h 15","2 h 45","2 h 15","3 h 45"]'::jsonb, 1, '*Viertel vor* = moins le quart : un quart d’heure avant trois heures.', 4),
    ('2bea79e8-e303-5d5a-8cbc-72d724be0264'::uuid, 'b019d065-4db1-5894-9125-d309262b3ba1'::uuid, 'Quelle question sert à demander l’heure ?', 'mcq', '["Wie alt bist du?","Wie spät ist es?","Wann ist es?","Wie lange ist es?"]'::jsonb, 1, '*Wie spät ist es?* (ou *Wie viel Uhr ist es?*) : quelle heure est-il ?', 5),
    ('8003eba0-51f2-58f7-b533-f34b3af36425'::uuid, 'b019d065-4db1-5894-9125-d309262b3ba1'::uuid, '« Ich komme ___ halb acht. » Quel mot complète la phrase ?', 'mcq', '["am","im","um","in"]'::jsonb, 2, 'L’heure précise se construit avec *um*.', 6),
    ('680c6896-9f5f-5e73-a17c-7f81808c2876'::uuid, 'b019d065-4db1-5894-9125-d309262b3ba1'::uuid, 'Comment écrit-on 30 ?', 'mcq', '["dreizig","dreißig","dreissig","dreizich"]'::jsonb, 1, '30 est la seule dizaine en *-ßig* : *dreißig*.', 7),
    ('d8cc9806-e9c5-55bd-8da2-0229430de62c'::uuid, 'b019d065-4db1-5894-9125-d309262b3ba1'::uuid, 'Quel est l’ordinal de 3 ?', 'mcq', '["der dreite","der dritte","der dreiste","der drite"]'::jsonb, 1, '*erste* et *dritte* sont irréguliers ; *siebte* aussi perd une syllabe.', 8),
    ('e52b96a6-6cf1-5084-9e0a-d04b91a7a86f'::uuid, 'b019d065-4db1-5894-9125-d309262b3ba1'::uuid, '« Ich habe am 14. Mai Geburtstag » se lit…', 'mcq', '["am vierzehn Mai","am vierzehnte Mai","am vierzehnten Mai","am vierzehnsten Mai"]'::jsonb, 2, 'Après *am* (datif), l’ordinal prend la terminaison *-en*.', 9),
    ('24356650-9d18-5ee0-9d98-87648fadc67d'::uuid, 'b019d065-4db1-5894-9125-d309262b3ba1'::uuid, 'En allemand, un ordinal écrit en chiffres se reconnaît au point qui le suit.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*der 3. Oktober* se lit *der dritte Oktober* : le point marque l’ordinal.', 10),
    ('5ac10d38-14bb-5b11-ba94-40c1be9cf414'::uuid, 'b019d065-4db1-5894-9125-d309262b3ba1'::uuid, '« zwanzig Uhr zehn » correspond à…', 'mcq', '["20 h 10","10 h 20","8 h 10 du matin","20 h 50"]'::jsonb, 0, 'L’heure officielle se dit sur 24 heures, heure puis minutes.', 11),
    ('7d853c0f-dcee-5ca4-9d60-04e70af6c398'::uuid, 'b019d065-4db1-5894-9125-d309262b3ba1'::uuid, 'Quel est l’ordinal de 20 ?', 'mcq', '["der zwanzigte","der zwanzigste","der zwanzigen","der zwanzigerste"]'::jsonb, 1, 'À partir de 20, l’ordinal se forme avec *-ste*.', 12),
    ('0db22b36-216b-5560-87c6-3532534b803d'::uuid, '8ece8ab7-f11b-54f0-b379-cefb28cc92f6'::uuid, 'Dans un mot composé, quel élément donne le genre ?', 'mcq', '["Le premier","Le dernier","Le plus long","Celui du milieu"]'::jsonb, 1, 'Le dernier élément est le mot de base : il porte le genre et le sens principal.', 1),
    ('eba040e7-0c54-555e-a193-fe79d6693e28'::uuid, '8ece8ab7-f11b-54f0-b379-cefb28cc92f6'::uuid, 'Quel est le genre de « Haustür » (das Haus + die Tür) ?', 'mcq', '["der","die","das","Il dépend du contexte"]'::jsonb, 1, 'Le genre vient de *die Tür* : *die Haustür*.', 2),
    ('6c28ac9b-fab8-587b-8f19-f5a8b9fc121c'::uuid, '8ece8ab7-f11b-54f0-b379-cefb28cc92f6'::uuid, 'Que signifie « der Handschuh » ?', 'mcq', '["La chaussure","Le gant","La chaussette","La main"]'::jsonb, 1, 'Mot à mot « chaussure de main » : le gant.', 3),
    ('5957e246-5b95-54ae-9de8-acf86860c6e3'::uuid, '8ece8ab7-f11b-54f0-b379-cefb28cc92f6'::uuid, '« der Apfelbaum » désigne…', 'mcq', '["une pomme","un pommier","une tarte aux pommes","une branche"]'::jsonb, 1, 'Le mot de base est *Baum* (arbre) : un arbre à pommes, un pommier.', 4),
    ('2fcb8133-bfa8-58ea-868d-df6132da6f6a'::uuid, '8ece8ab7-f11b-54f0-b379-cefb28cc92f6'::uuid, 'Quelle lettre de liaison trouve-t-on dans « Geburtstag » ?', 'mcq', '["-n-","-s-","-er-","-en-"]'::jsonb, 1, '*Geburt* + *s* + *Tag* : l’anniversaire.', 5),
    ('a0aee94f-136a-5949-85ca-a7cef4e2104a'::uuid, '8ece8ab7-f11b-54f0-b379-cefb28cc92f6'::uuid, '« das Schwimmbad » est formé de…', 'mcq', '["deux noms","un verbe et un nom","un adjectif et un nom","une préposition et un nom"]'::jsonb, 1, 'Le radical de *schwimmen* + *das Bad* : la piscine.', 6),
    ('29131cf9-bd00-5680-ae8b-12c92723683a'::uuid, '8ece8ab7-f11b-54f0-b379-cefb28cc92f6'::uuid, 'Quel est le genre de « Schulhof » ?', 'mcq', '["der","die","das","Aucun"]'::jsonb, 0, '*die Schule* + *der Hof* : c’est *der Hof* qui décide.', 7),
    ('3a3db706-be4b-5411-9252-f4d80c34decb'::uuid, '8ece8ab7-f11b-54f0-b379-cefb28cc92f6'::uuid, 'Que signifie « die Großstadt » ?', 'mcq', '["La grande ville","La vieille ville","La capitale","Le grand magasin"]'::jsonb, 0, '*groß* (grand) + *die Stadt* (la ville).', 8),
    ('84fa975e-7ff4-5c39-84d5-2888b3191e5c'::uuid, '8ece8ab7-f11b-54f0-b379-cefb28cc92f6'::uuid, 'On lit un mot composé allemand de droite à gauche pour en trouver le sens principal.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'On repère d’abord le mot de base, à droite, puis ce qui le précise.', 9),
    ('ee4c2e38-8024-52a0-b92a-3b881994c24d'::uuid, '8ece8ab7-f11b-54f0-b379-cefb28cc92f6'::uuid, 'Quel est le mot de base de « Fußballweltmeisterschaft » ?', 'mcq', '["Fußball","Welt","Meisterschaft","Ball"]'::jsonb, 2, '*die Meisterschaft* (le championnat) : le mot est donc féminin.', 10),
    ('aab366ac-8584-5ea9-8802-ffc43489f645'::uuid, '8ece8ab7-f11b-54f0-b379-cefb28cc92f6'::uuid, 'Comment dit-on « le dictionnaire » ?', 'mcq', '["das Buchwort","das Wörterbuch","der Wortbuch","die Wörterbücherei"]'::jsonb, 1, 'Un livre (*Buch*) de mots (*Wörter*) : *das Wörterbuch*.', 11),
    ('fa1f726b-a188-53b2-b363-e52398db0b37'::uuid, '8ece8ab7-f11b-54f0-b379-cefb28cc92f6'::uuid, '« die Straßenbahn » signifie…', 'mcq', '["la rue piétonne","le tramway","l’autoroute","la gare routière"]'::jsonb, 1, 'Un train (*Bahn*) qui roule dans la rue (*Straße*) : le tramway.', 12),
    ('1c14c3b9-f99b-5079-b8e6-84d4b3133df5'::uuid, '529cebfd-7ad1-5f8f-a777-51553c2b70cf'::uuid, 'Que signifie « zuerst » ?', 'mcq', '["Finalement","D’abord","Soudain","Ensuite"]'::jsonb, 1, '*zuerst* ou *zunächst* ouvrent un récit : d’abord.', 1),
    ('b8f6b6ef-4d3f-57e1-80e0-ed8dd1142004'::uuid, '529cebfd-7ad1-5f8f-a777-51553c2b70cf'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["Dann ich gehe ins Kino.","Dann gehe ich ins Kino.","Dann ich ins Kino gehe.","Gehe dann ich ins Kino."]'::jsonb, 1, 'Le connecteur occupe la 1re place, le verbe reste 2e, le sujet passe derrière.', 2),
    ('f97dc083-5754-5a8c-89ff-bf8f5d01f468'::uuid, '529cebfd-7ad1-5f8f-a777-51553c2b70cf'::uuid, 'Que signifie « plötzlich » ?', 'mcq', '["Lentement","Soudain","Plus tard","Au début"]'::jsonb, 1, '*plötzlich* introduit un événement inattendu.', 3),
    ('99a4b8c7-91d5-595a-b42f-167b962612eb'::uuid, '529cebfd-7ad1-5f8f-a777-51553c2b70cf'::uuid, '« und » provoque l’inversion du sujet et du verbe.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*und* est en position zéro : *Ich esse und ich trinke*. Seuls les adverbes comme *dann* occupent la 1re place.', 4),
    ('f151bb1e-5a05-5f11-9974-2971fea5072b'::uuid, '529cebfd-7ad1-5f8f-a777-51553c2b70cf'::uuid, '« ___ bin ich nach Hause gegangen. » Quel mot signifiant « finalement » complète la phrase ?', 'mcq', '["Zuerst","Plötzlich","Schließlich","Später"]'::jsonb, 2, '*schließlich* = finalement, pour finir.', 5),
    ('e9f3e94e-95bb-5b3c-a89c-7fe6b1258c49'::uuid, '529cebfd-7ad1-5f8f-a777-51553c2b70cf'::uuid, 'Quelle est la bonne suite : « Danach … »', 'mcq', '["… wir haben gegessen.","… haben wir gegessen.","… gegessen wir haben.","… wir gegessen haben."]'::jsonb, 1, 'Après *danach*, l’auxiliaire en 2e position, puis le sujet, puis le participe à la fin.', 6),
    ('ed5bd651-2c17-5ce3-8a9d-7b54399bb4e8'::uuid, '529cebfd-7ad1-5f8f-a777-51553c2b70cf'::uuid, 'À l’oral, on raconte le plus souvent un week-end…', 'mcq', '["au prétérit","au parfait","au futur","au présent seulement"]'::jsonb, 1, 'Le parfait est le temps du récit oral et des messages.', 7),
    ('016b2239-1d79-5293-bff2-f457c8c0be8f'::uuid, '529cebfd-7ad1-5f8f-a777-51553c2b70cf'::uuid, 'Que signifie « am Ende » ?', 'mcq', '["Au début","À la fin","Au milieu","En avance"]'::jsonb, 1, '*das Ende* = la fin.', 8),
    ('09ea89ac-daba-5900-96dc-82aa172a90b6'::uuid, '529cebfd-7ad1-5f8f-a777-51553c2b70cf'::uuid, 'Quel mot envoie le verbe conjugué à la fin de la proposition ?', 'mcq', '["danach","dann","nachdem","später"]'::jsonb, 2, '*nachdem* est une conjonction de subordination ; *danach* est un adverbe.', 9),
    ('8f1950bf-1148-510b-9b9e-11f62ec18f99'::uuid, '529cebfd-7ad1-5f8f-a777-51553c2b70cf'::uuid, '« Zuerst habe ich Fußball ___. » Quel participe complète la phrase ?', 'mcq', '["spielen","gespielt","spielt","gespielen"]'::jsonb, 1, 'Le parfait de *spielen* : *habe … gespielt*, le participe en fin de phrase.', 10),
    ('707bc4c6-08d0-59c9-ae64-cdda95f61a2e'::uuid, '529cebfd-7ad1-5f8f-a777-51553c2b70cf'::uuid, 'Dans « Dann fahren wir in die Stadt », quel élément est en 2e position ?', 'mcq', '["Dann","fahren","wir","in die Stadt"]'::jsonb, 1, 'Le verbe conjugué est toujours le 2e élément de la phrase déclarative.', 11),
    ('bcdbfb98-02b4-500c-96a7-62133ff838e2'::uuid, '529cebfd-7ad1-5f8f-a777-51553c2b70cf'::uuid, 'Que signifie « später » ?', 'mcq', '["Plus tôt","Plus tard","Jamais","Souvent"]'::jsonb, 1, '*spät* = tard ; *später* = plus tard.', 12),
    ('3ab0843f-a89f-5d12-a244-3740ed511bcc'::uuid, '33806634-a720-5e94-92b6-d6d84ed7473a'::uuid, 'Comment commencer un message à ton ami Paul ?', 'mcq', '["Liebe Paul,","Lieber Paul,","Lieben Paul,","Liebes Paul,"]'::jsonb, 1, 'Pour un garçon, l’adjectif prend *-er* : *Lieber Paul*.', 1),
    ('34109e57-3730-59c5-9520-fa8d060b6581'::uuid, '33806634-a720-5e94-92b6-d6d84ed7473a'::uuid, 'Quelle formule termine une lettre polie à un adulte inconnu ?', 'mcq', '["Viele Grüße","Bis bald!","Mit freundlichen Grüßen","Tschüss"]'::jsonb, 2, '*Mit freundlichen Grüßen* est la formule standard du courrier poli.', 2),
    ('cf85af63-3522-5fbb-aa9f-8e3a37b7c887'::uuid, '33806634-a720-5e94-92b6-d6d84ed7473a'::uuid, 'Après « Liebe Lena, », la première ligne du message commence…', 'mcq', '["par une majuscule","par une minuscule, sauf nom ou Sie","par un tiret","par la date"]'::jsonb, 1, 'L’appel se termine par une virgule, la phrase suivante continue donc en minuscule.', 3),
    ('eb0a64f6-f30d-5dd4-9dcf-225224e23690'::uuid, '33806634-a720-5e94-92b6-d6d84ed7473a'::uuid, 'Comment écrire à une femme inconnue, Mme Weber ?', 'mcq', '["Liebe Frau Weber,","Sehr geehrter Frau Weber,","Sehr geehrte Frau Weber,","Hallo Frau Weber,"]'::jsonb, 2, '*Sehr geehrte* pour une femme, *Sehr geehrter* pour un homme.', 4),
    ('46a86ed5-a2f4-5600-b92b-0f8467fb2f90'::uuid, '33806634-a720-5e94-92b6-d6d84ed7473a'::uuid, 'Dans un message poli, on écrit « ihnen » en minuscule quand on s’adresse à la personne.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le vouvoiement prend la majuscule : *Sie*, *Ihnen*, *Ihr*.', 5),
    ('314326d5-fab3-537f-95a3-13db0c41ad92'::uuid, '33806634-a720-5e94-92b6-d6d84ed7473a'::uuid, 'Que signifie « Ich freue mich auf deinen Besuch » ?', 'mcq', '["Je te remercie pour ta visite","Je me réjouis de ta visite","Je regrette ta visite","Je t’attends à la gare"]'::jsonb, 1, '*sich freuen auf* = se réjouir de quelque chose à venir.', 6),
    ('0835c7a9-1e2d-5ca6-b309-8136892ccee7'::uuid, '33806634-a720-5e94-92b6-d6d84ed7473a'::uuid, 'Comment dit-on « Malheureusement, je ne peux pas venir » ?', 'mcq', '["Leider kann ich nicht kommen.","Leider ich kann nicht kommen.","Gerne kann ich nicht kommen.","Leider komme ich kann nicht."]'::jsonb, 0, '*leider* en 1re position : verbe en 2e, sujet derrière.', 7),
    ('d93f0ecd-3429-56d5-946e-96cc3d079dce'::uuid, '33806634-a720-5e94-92b6-d6d84ed7473a'::uuid, '« ___ Dank für deine Nachricht! » Quel mot complète la phrase ?', 'mcq', '["Viel","Vielen","Viele","Vieles"]'::jsonb, 1, 'On dit *Vielen Dank* : merci beaucoup.', 8),
    ('933df323-a371-5295-ab1e-8b486dcd36cb'::uuid, '33806634-a720-5e94-92b6-d6d84ed7473a'::uuid, 'Où place-t-on la date dans une lettre ?', 'mcq', '["En haut, avec le lieu","Sous la signature","Après l’appel","On ne la met jamais"]'::jsonb, 0, 'En haut : *Paris, den 5. März 2026*.', 9),
    ('c95e13b4-407f-5673-8876-27cdaad7f2c3'::uuid, '33806634-a720-5e94-92b6-d6d84ed7473a'::uuid, '« Mir geht es gut » répond à…', 'mcq', '["Wo wohnst du?","Wie geht es dir?","Wie heißt du?","Was machst du?"]'::jsonb, 1, 'À « Comment vas-tu ? », on répond « Je vais bien ».', 10),
    ('ac7bc38d-23e8-58aa-b81c-85782bdb2293'::uuid, '33806634-a720-5e94-92b6-d6d84ed7473a'::uuid, 'Quel signe suit l’appel « Hallo Max » ?', 'mcq', '["Un point","Deux points","Une virgule","Un point d’exclamation obligatoire"]'::jsonb, 2, 'En allemand, l’appel est normalement suivi d’une virgule.', 11),
    ('1336c9ff-4523-5386-8371-a03c4f99bb81'::uuid, '33806634-a720-5e94-92b6-d6d84ed7473a'::uuid, 'Que signifie « Schreib mir bald! » ?', 'mcq', '["Écris-moi vite !","Je t’écris bientôt","Écris-lui vite !","Écrivez-moi !"]'::jsonb, 0, 'Impératif de *schreiben* à la 2e personne : *schreib*.', 12),
    ('8f68af6e-698e-5d13-836f-0cd88721a1d7'::uuid, '8ea523a6-f453-51d3-8d12-1ad03165be48'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["Meiner Meinung nach das ist gefährlich.","Meiner Meinung nach ist das gefährlich.","Meiner Meinung nach das gefährlich ist.","Meiner Meinung ist nach das gefährlich."]'::jsonb, 1, '*Meiner Meinung nach* occupe la 1re place : verbe en 2e, sujet derrière.', 1),
    ('a4929409-f6d2-55b1-ae18-67c65441e3cc'::uuid, '8ea523a6-f453-51d3-8d12-1ad03165be48'::uuid, 'Après « Ich finde, dass … », le verbe conjugué se place…', 'mcq', '["en 2e position","en 1re position","à la fin","juste après dass"]'::jsonb, 2, '*dass* introduit une subordonnée : verbe conjugué à la fin.', 2),
    ('ba9f8e1c-eb62-5ec7-afe1-35958a6e6294'::uuid, '8ea523a6-f453-51d3-8d12-1ad03165be48'::uuid, 'Comment dit-on « Je ne suis pas d’accord » ?', 'mcq', '["Ich bin nicht einverstanden.","Ich habe nicht recht.","Das stimmt.","Ich bin nicht deiner."]'::jsonb, 0, '*einverstanden sein* = être d’accord.', 3),
    ('ce20191b-50f2-516e-a975-b2ea4f11735d'::uuid, '8ea523a6-f453-51d3-8d12-1ad03165be48'::uuid, 'Quelle différence entre « weil » et « denn » ?', 'mcq', '["Aucune, les deux envoient le verbe à la fin","weil envoie le verbe à la fin, denn garde l’ordre normal","denn envoie le verbe à la fin, weil garde l’ordre normal","weil s’emploie seulement à l’écrit"]'::jsonb, 1, '*weil* est subordonnant ; *denn* est coordonnant, en position zéro.', 4),
    ('51fc1049-1f1a-5033-8436-6e881383fa36'::uuid, '8ea523a6-f453-51d3-8d12-1ad03165be48'::uuid, 'Que signifie « Da hast du recht » ?', 'mcq', '["Là, tu as raison","Là, tu as tort","Tu as le droit","Tu es là"]'::jsonb, 0, '*recht haben* = avoir raison.', 5),
    ('3884e5da-71e4-5e3f-9ec0-41ab76b202f3'::uuid, '8ea523a6-f453-51d3-8d12-1ad03165be48'::uuid, '« Einerseits … andererseits » permet de…', 'mcq', '["raconter dans l’ordre","peser le pour et le contre","poser une question","exprimer un souhait"]'::jsonb, 1, 'D’un côté… de l’autre : on met deux arguments en balance.', 6),
    ('5c219a70-b02a-574a-a003-9545de4289a1'::uuid, '8ea523a6-f453-51d3-8d12-1ad03165be48'::uuid, '« Ich mag Sport, weil er gesund ___. » Quel mot complète la phrase ?', 'mcq', '["ist","sein","bin","sind"]'::jsonb, 0, 'Après *weil*, le verbe conjugué *ist* se place à la fin.', 7),
    ('e27158c8-0cb8-5bca-ab64-3836ac658ac9'::uuid, '8ea523a6-f453-51d3-8d12-1ad03165be48'::uuid, 'Après « Ich finde, », on peut aussi continuer avec une principale sans dass.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Ich finde, das Buch ist spannend* est correct : sans *dass*, le verbe reste 2e.', 8),
    ('5032248b-a96b-52b1-a1b1-6c76f1ced897'::uuid, '8ea523a6-f453-51d3-8d12-1ad03165be48'::uuid, 'Que signifie « der Nachteil » ?', 'mcq', '["L’avantage","L’inconvénient","La nuit","La conclusion"]'::jsonb, 1, '*der Vorteil* = l’avantage, *der Nachteil* = l’inconvénient.', 9),
    ('a32e5e93-013a-57bb-a8ce-2439b0bd8b91'::uuid, '8ea523a6-f453-51d3-8d12-1ad03165be48'::uuid, 'Quel adjectif est négatif ?', 'mcq', '["spannend","nützlich","langweilig","lustig"]'::jsonb, 2, '*langweilig* = ennuyeux.', 10),
    ('76c6199e-6b05-5c67-8b37-da860cedd713'::uuid, '8ea523a6-f453-51d3-8d12-1ad03165be48'::uuid, '« Ich sehe das anders » signifie…', 'mcq', '["Je vois mal","Je vois ça autrement","Je vois la même chose","Je regarde ailleurs"]'::jsonb, 1, 'Une manière polie d’exprimer son désaccord.', 11),
    ('63f17d9a-7cfb-5014-b3da-c6b0f63f37a7'::uuid, '8ea523a6-f453-51d3-8d12-1ad03165be48'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["Für mich Sport ist wichtig.","Für mich ist Sport wichtig.","Für mich ist wichtig Sport ist.","Sport für mich wichtig ist."]'::jsonb, 1, '*Für mich* en tête : inversion, le verbe *ist* en 2e position.', 12),
