    ('51f2a2c4-8224-53f9-b4d3-770ce0e368f8'::uuid, '8a4d93ba-093c-5c00-b531-31cadff209f2'::uuid, 'Comment dire « Elle pourra conduire l’an prochain » ?', 'mcq', '["She will can drive next year.","She will be able to drive next year.","She can will drive next year.","She could drive next year."]'::jsonb, 1, 'Deux modaux ne se suivent jamais : will be able to.', 1),
    ('06660581-39d9-59f3-8c37-345607a98f69'::uuid, '8a4d93ba-093c-5c00-b531-31cadff209f2'::uuid, 'Pour une réussite PONCTUELLE dans le passé, on emploie de préférence…', 'mcq', '["could","can","was able to / managed to","must"]'::jsonb, 2, 'Could exprime une capacité générale.', 2),
    ('445794c7-ddfe-591e-a153-abb1d3faa1d3'::uuid, '8a4d93ba-093c-5c00-b531-31cadff209f2'::uuid, '« You don’t have to come » signifie…', 'mcq', '["Ce n’est pas la peine de venir","Tu ne dois pas venir","Tu ne peux pas venir","Tu ne veux pas venir"]'::jsonb, 0, 'Absence d’obligation.', 3),
    ('72aa84ac-a253-5fd9-9a99-0469fd8680cb'::uuid, '8a4d93ba-093c-5c00-b531-31cadff209f2'::uuid, '« You mustn’t come » exprime…', 'mcq', '["Une absence d’obligation","Un conseil","Une interdiction","Une capacité"]'::jsonb, 2, 'Mustn’t = il est interdit de.', 4),
    ('2842cd23-f731-586d-b6dd-f600fcf8dc17'::uuid, '8a4d93ba-093c-5c00-b531-31cadff209f2'::uuid, 'Quel est le passé de « I must leave early » ?', 'mcq', '["I had to leave early.","I musted leave early.","I must have leave early.","I did must leave early."]'::jsonb, 0, 'Must n’a pas de passé : on emploie had to.', 5),
    ('7d8fe97e-0ccc-5949-a458-1d740973c337'::uuid, '8a4d93ba-093c-5c00-b531-31cadff209f2'::uuid, '« At ten, she could swim » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Capacité générale dans le passé : could.', 6),
    ('e3388b3a-67b6-50e4-b22e-cf4a6c9580eb'::uuid, '8a4d93ba-093c-5c00-b531-31cadff209f2'::uuid, 'Complète : « We weren’t ___ to use our phones in class. »', 'mcq', '["able","must","can","allowed"]'::jsonb, 3, 'Be allowed to = avoir la permission.', 7),
    ('cb7433da-3535-5635-8f7d-2e41a7376eb7'::uuid, '8a4d93ba-093c-5c00-b531-31cadff209f2'::uuid, '« I have to wear a uniform » : d’où vient l’obligation ?', 'mcq', '["De celui qui parle","D’une règle extérieure","D’un conseil","D’un souhait"]'::jsonb, 1, 'Have to : obligation imposée de l’extérieur.', 8),
    ('1a9073e1-efb2-5f7a-997b-5f1967eac78e'::uuid, '8a4d93ba-093c-5c00-b531-31cadff209f2'::uuid, 'Comment traduire « Il a réussi à s’échapper » ?', 'mcq', '["He could escape.","He managed to escape.","He can escape.","He must escape."]'::jsonb, 1, 'Réussite ponctuelle : managed to.', 9),
    ('f040acb9-c4f0-5e09-8d38-c145a3314eb0'::uuid, '8a4d93ba-093c-5c00-b531-31cadff209f2'::uuid, 'Quel sens a « You ought to apologise » ?', 'mcq', '["Tu es obligé par la loi de t’excuser","Tu t’es excusé","Tu peux t’excuser","Tu devrais t’excuser"]'::jsonb, 3, 'Ought to : conseil ou devoir moral, comme should.', 10),
    ('7852424f-8108-5082-943e-2352e8451f53'::uuid, '8a4d93ba-093c-5c00-b531-31cadff209f2'::uuid, 'Comment dire « Je n’ai pas pu dormir » (depuis un moment) ?', 'mcq', '["I haven’t been able to sleep.","I haven’t could sleep.","I didn’t can sleep.","I haven’t can slept."]'::jsonb, 0, 'Be able to se met au present perfect.', 11),
    ('96c8acdd-2eb3-55f8-bead-8785cbeedf91'::uuid, '8a4d93ba-093c-5c00-b531-31cadff209f2'::uuid, '« Shall I open the window? » sert à…', 'mcq', '["Donner un ordre","Exprimer le futur lointain","Proposer quelque chose","Interdire"]'::jsonb, 2, 'Shall à la première personne propose ou demande un avis.', 12),
    ('f5bdbf2d-a622-55c0-9199-7e18bef95b62'::uuid, '9a2e7ef5-7e20-5595-b053-fd2d64722e56'::uuid, 'Comment traduire « Je veux que tu viennes » ?', 'mcq', '["I want that you come.","I want you come.","I want you to come.","I want that you to come."]'::jsonb, 2, 'Verbe + complément + to + base verbale.', 1),
    ('75072b74-6e3f-5456-957a-2417963f46bd'::uuid, '9a2e7ef5-7e20-5595-b053-fd2d64722e56'::uuid, 'Laquelle est correcte ?', 'mcq', '["I want him to leave.","I want he leaves.","I want that he leaves.","I want him leave."]'::jsonb, 0, 'Le pronom est complément : him.', 2),
    ('2b4325b2-f61d-5d48-91f2-9286fa2649ab'::uuid, '9a2e7ef5-7e20-5595-b053-fd2d64722e56'::uuid, 'Comment dire « Il m’a demandé de ne rien dire » ?', 'mcq', '["He didn’t ask me to say anything.","He asked me to not saying anything.","He asked me not to say anything.","He asked that I not say nothing."]'::jsonb, 2, 'Not se place devant to.', 3),
    ('82c9a41a-bc25-5626-8aea-3ee31977b754'::uuid, '9a2e7ef5-7e20-5595-b053-fd2d64722e56'::uuid, 'Quel verbe se construit SANS « to » ?', 'mcq', '["make","want","expect","ask"]'::jsonb, 0, 'She made me laugh.', 4),
    ('09191bdc-eaba-5333-929f-fc0a2e059276'::uuid, '9a2e7ef5-7e20-5595-b053-fd2d64722e56'::uuid, '« I suggested him to go » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On dit I suggested that he go / should go, ou I suggested going.', 5),
    ('0be0636d-1035-5d95-a88b-22424d3a1510'::uuid, '9a2e7ef5-7e20-5595-b053-fd2d64722e56'::uuid, 'Complète : « They expect us ___ the match. »', 'mcq', '["win","winning","that we win","to win"]'::jsonb, 3, 'Expect + complément + to.', 6),
    ('5123c9bd-bb04-531a-941d-72a056dcc4ba'::uuid, '9a2e7ef5-7e20-5595-b053-fd2d64722e56'::uuid, 'Comment traduire « Elle m’a dit d’attendre » ?', 'mcq', '["She said me to wait.","She told me to wait.","She told me waiting.","She told that I wait."]'::jsonb, 1, 'Tell + complément + to ; say ne prend pas de complément de personne direct.', 7),
    ('ee285973-e5af-5c64-9d56-4d2d66964d5b'::uuid, '9a2e7ef5-7e20-5595-b053-fd2d64722e56'::uuid, '« It’s important for young people to vote » signifie…', 'mcq', '["Les jeunes ont voté","Il est important que les jeunes votent","Voter est important pour les vieux","Les jeunes veulent voter"]'::jsonb, 1, 'For + nom + to : l’action a son propre sujet.', 8),
