    ('18f25b20-87c9-590f-b4d4-eec8f90dfa85'::uuid, '9a2e7ef5-7e20-5595-b053-fd2d64722e56'::uuid, 'Quel verbe exprime l’encouragement dans cette structure ?', 'mcq', '["encourage","suggest","hope","make"]'::jsonb, 0, 'They encouraged him to apply.', 10),
    ('172f5cb7-4bae-582d-8f79-ef1d779c27ce'::uuid, '9a2e7ef5-7e20-5595-b053-fd2d64722e56'::uuid, 'Avec « help », le « to » est…', 'mcq', '["Obligatoire","Interdit","Facultatif","Placé après le verbe"]'::jsonb, 2, 'He helped me (to) carry the box.', 11),
    ('7087927d-66cb-5136-99a4-4f8faed66647'::uuid, '9a2e7ef5-7e20-5595-b053-fd2d64722e56'::uuid, 'Comment dire « J’aimerais qu’elle reste » ?', 'mcq', '["I’d like that she stays.","I’d like she stay.","I’d like her staying.","I’d like her to stay."]'::jsonb, 3, 'Would like + complément + to.', 12),
    ('8b58a8f5-1bdc-519b-834f-88633007d510'::uuid, '17b092b3-778b-59c5-a78a-ab5713f54310'::uuid, 'Quel mot signifie « aucun des deux » ?', 'mcq', '["neither","both","either","every"]'::jsonb, 0, 'Neither contient la négation.', 1),
    ('75b034b6-11d9-59fa-9866-ee22974b2d36'::uuid, '17b092b3-778b-59c5-a78a-ab5713f54310'::uuid, 'Complète : « ___ answers are correct. » (les deux)', 'mcq', '["Either","Each","Both","Every"]'::jsonb, 2, 'Both + pluriel.', 2),
    ('a9856013-36d0-5c41-b840-d55a8ec609c5'::uuid, '17b092b3-778b-59c5-a78a-ab5713f54310'::uuid, '« You can take either bus » signifie…', 'mcq', '["Tu peux prendre l’un ou l’autre bus","Tu dois prendre les deux bus","Tu ne peux prendre aucun bus","Tu prends chaque bus"]'::jsonb, 0, 'Either = n’importe lequel des deux.', 3),
    ('34161031-78fd-5b9f-a2f3-f2dd31352cc6'::uuid, '17b092b3-778b-59c5-a78a-ab5713f54310'::uuid, 'Laquelle est correcte ?', 'mcq', '["Neither of them didn’t come.","Neither of them not came.","Either of them didn’t came.","Neither of them came."]'::jsonb, 3, 'Neither porte déjà la négation.', 4),
    ('48395797-80a3-5885-a5b4-68e719785e3c'::uuid, '17b092b3-778b-59c5-a78a-ab5713f54310'::uuid, '« Every » s’emploie avec…', 'mcq', '["Deux éléments seulement","Trois éléments ou plus","Un nom pluriel","Un indénombrable"]'::jsonb, 1, 'Every vise un groupe d’au moins trois.', 5),
    ('e6748d57-49f2-5335-b9de-99601cb42b65'::uuid, '17b092b3-778b-59c5-a78a-ab5713f54310'::uuid, 'On peut dire « every of us ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On dit each of us ou every one of us.', 6),
    ('a7d108b9-c427-57f4-8803-de8a820e491f'::uuid, '17b092b3-778b-59c5-a78a-ab5713f54310'::uuid, 'Complète : « I don’t like it ___. » (moi non plus)', 'mcq', '["too","either","neither","both"]'::jsonb, 1, 'En fin de phrase négative, either = non plus.', 7),
