    ('d1c6a7ee-518e-56ae-934a-5bc2a7c3f754'::uuid, '17b092b3-778b-59c5-a78a-ab5713f54310'::uuid, 'Quel verbe suit « Every student » ?', 'mcq', '["has","have","are having","haves"]'::jsonb, 0, 'Every + singulier + verbe au singulier.', 9),
