    ('4cfb5388-8923-5909-8a90-c6e23b9bb7a7'::uuid, '17b092b3-778b-59c5-a78a-ab5713f54310'::uuid, 'Que signifie « every other day » ?', 'mcq', '["Chaque jour","Tous les autres jours","Jamais","Un jour sur deux"]'::jsonb, 3, 'Other = l’autre : un jour oui, un jour non.', 11),
    ('238aa34b-fa52-5823-8085-19bc7e0e3841'::uuid, '17b092b3-778b-59c5-a78a-ab5713f54310'::uuid, 'Où place-t-on « both » dans « They are tired » pour dire « Ils sont tous les deux fatigués » ?', 'mcq', '["Avant are","Après are","En fin de phrase","Avant They"]'::jsonb, 1, 'Après be : They are both tired.', 12),
    ('6b4a755d-6bb3-5463-8b3a-b62418e1809e'::uuid, '9f9c3589-3394-5a12-978c-34ad57628f54'::uuid, 'Comment traduire « Il a traversé la rivière à la nage » ?', 'mcq', '["He crossed the river swimming.","He traversed the river by swim.","He swam across the river.","He crossed swimming the river."]'::jsonb, 2, 'Le verbe dit la manière, la particule le déplacement.', 1),
