    ('6b5a1c55-7f13-5bd2-aacc-bd9ad2157980'::uuid, '9f9c3589-3394-5a12-978c-34ad57628f54'::uuid, 'Comment traduire « Ils sont rentrés à pied » ?', 'mcq', '["They returned by feet.","They came back walking.","They rentered on foot.","They walked back home."]'::jsonb, 3, 'Walk (manière) + back (retour).', 7),
