    ('03f62897-22b4-5935-9f16-fac6f96bf24a'::uuid, '9f9c3589-3394-5a12-978c-34ad57628f54'::uuid, 'Quelle traduction de « Le voleur s’est enfui en courant » est la plus naturelle ?', 'mcq', '["The thief escaped running.","The thief fled by running.","The thief ran away.","The thief went away by run."]'::jsonb, 2, 'Run + away.', 9),
    ('ecd1e1d8-2bd7-5a0c-94f9-4887108a61c7'::uuid, '9f9c3589-3394-5a12-978c-34ad57628f54'::uuid, 'Comment dire « Il est sorti de la tente en rampant » ?', 'mcq', '["He went out of the tent crawling.","He exited the tent by crawl.","He crawled into the tent.","He crawled out of the tent."]'::jsonb, 3, 'Crawl (manière) + out of (sortie).', 10),
    ('2e79afc3-a5d2-53d4-9408-611838a3fb72'::uuid, '9f9c3589-3394-5a12-978c-34ad57628f54'::uuid, 'Comment traduire « Le vent a ouvert la porte d’un coup » ?', 'mcq', '["The wind opened the door by blow.","The wind blew the door open.","The wind blew open by the door.","The wind made open the door."]'::jsonb, 1, 'Blow (manière) + open (résultat).', 11),
    ('be3914f1-9b15-538f-ae3d-233ae5e78234'::uuid, '9f9c3589-3394-5a12-978c-34ad57628f54'::uuid, 'Où se place l’adjectif de résultat dans « She kicked the box ___ » ?', 'mcq', '["Avant le verbe","Entre le sujet et le verbe","Après le complément","Avant le sujet"]'::jsonb, 2, 'Verbe + complément + résultat.', 12),
