    ('6027c33b-c07f-5056-8bc5-6329392c222a'::uuid, '96eba515-9765-5374-b8da-d6f0df6717c8'::uuid, 'Laquelle est correcte ?', 'mcq', '["He’s interested by art.","He’s interested for art.","He’s interested of art.","He’s interested in art."]'::jsonb, 3, 'Interested in, jamais interested by.', 2),
    ('2fc144a5-398e-509b-8566-7d1e889296c8'::uuid, '96eba515-9765-5374-b8da-d6f0df6717c8'::uuid, 'Comment dire « la raison de son départ » ?', 'mcq', '["the reason of his departure","the reason for his departure","the reason to his departure","the reason in his departure"]'::jsonb, 1, 'Reason for.', 3),
    ('15bfb719-797a-5bff-bb8f-c4670461f9cc'::uuid, '96eba515-9765-5374-b8da-d6f0df6717c8'::uuid, 'Complète : « It depends ___ the weather. »', 'mcq', '["of","on","from","at"]'::jsonb, 1, 'Depend on, jamais depend of.', 4),
    ('61defce4-0b5f-539a-805b-119339cb3879'::uuid, '96eba515-9765-5374-b8da-d6f0df6717c8'::uuid, '« Angry with » s’emploie avec…', 'mcq', '["Une chose","Un lieu","Une date","Une personne"]'::jsonb, 3, 'Angry with someone, angry about something.', 5),
    ('a0d8e015-e514-58e3-8aaa-b9944e5b725f'::uuid, '96eba515-9765-5374-b8da-d6f0df6717c8'::uuid, 'On dit « married with a doctor ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On dit married to.', 6),
    ('0180e61f-3950-5a8c-b47c-91c22b21077e'::uuid, '96eba515-9765-5374-b8da-d6f0df6717c8'::uuid, 'Quelle forme suit « tired of » ?', 'mcq', '["waiting","wait","to wait","waited"]'::jsonb, 0, 'Après une préposition, le verbe prend -ING.', 7),
    ('ca5ad519-2741-55f0-86e5-cc834973a5ab'::uuid, '96eba515-9765-5374-b8da-d6f0df6717c8'::uuid, 'Complète : « Liverpool is famous ___ the Beatles. »', 'mcq', '["of","by","for","with"]'::jsonb, 2, 'Famous for.', 8),
    ('c816044b-ffc6-59d1-b146-8e3d21ff45f2'::uuid, '96eba515-9765-5374-b8da-d6f0df6717c8'::uuid, 'Comment dire « une hausse des prix » ?', 'mcq', '["an increase of prices","an increase on prices","an increase at prices","an increase in prices"]'::jsonb, 3, 'Increase in.', 9),
