    ('a4e5cdcf-a397-5694-9a48-212bda2d1abe'::uuid, 'b4c58164-ea31-5dda-9d0d-964fcdac6837'::uuid, 'Cindy Sherman se photographie elle-même dans des rôles de femmes stéréotypées.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ses Untitled Film Stills (1977-1980) imitent des images de films pour montrer la construction des rôles.', 6),
    ('1bf1be2c-210b-5e42-b9cf-62693391a6bd'::uuid, 'b4c58164-ea31-5dda-9d0d-964fcdac6837'::uuid, 'Quel artiste a incarné Ziggy Stardust en 1972 ?', 'mcq', '["David Bowie","Elton John","Freddie Mercury","Mick Jagger"]'::jsonb, 0, 'Bowie brouille les frontières du genre et de l’identité avec ce personnage.', 7),
    ('198ad01a-9edc-572b-af70-f7714e49b43a'::uuid, 'b4c58164-ea31-5dda-9d0d-964fcdac6837'::uuid, 'Que désigne « body shaming » ?', 'mcq', '["Le culte du corps","Le fait de se muscler","Le fait de moquer le physique de quelqu’un","Un régime alimentaire"]'::jsonb, 2, 'To shame = faire honte : c’est l’inverse de la body positivity.', 8),
