    ('1c9b67b9-7b30-5497-9b6b-151f2633709b'::uuid, '76c5dc84-67df-56dc-9fd5-cf31aa31d424'::uuid, 'Combien de pays compte le Commonwealth of Nations ?', 'mcq', '["56","12","27","193"]'::jsonb, 0, 'Depuis l’adhésion du Gabon et du Togo en 2022.', 1),
    ('6ef3f61d-78d9-58bc-9ecc-b5fa09673efb'::uuid, '76c5dc84-67df-56dc-9fd5-cf31aa31d424'::uuid, 'Quand l’Inde devient-elle indépendante ?', 'mcq', '["Le 4 juillet 1776","Le 26 janvier 1950","Le 15 août 1947","Le 1er juillet 1867"]'::jsonb, 2, 'L’indépendance s’accompagne de la partition avec le Pakistan.', 2),
    ('fca33a6a-7773-5bec-8548-de32c63c76e9'::uuid, '76c5dc84-67df-56dc-9fd5-cf31aa31d424'::uuid, 'Quel est le premier pays d’Afrique subsaharienne à devenir indépendant, en 1957 ?', 'mcq', '["Le Nigeria","Le Kenya","L’Afrique du Sud","Le Ghana"]'::jsonb, 3, 'Sous la conduite de Kwame Nkrumah.', 3),
    ('a51e5d45-b86d-5253-b4aa-621387ebd891'::uuid, '76c5dc84-67df-56dc-9fd5-cf31aa31d424'::uuid, 'Qui est le chef du Commonwealth depuis 2022 ?', 'mcq', '["Le Premier ministre britannique","Charles III","Le secrétaire général de l’ONU","Le président de l’Inde"]'::jsonb, 1, 'Un rôle symbolique, sans pouvoir politique.', 4),
    ('8198b3af-b4f4-5dbf-aa41-72518838aced'::uuid, '76c5dc84-67df-56dc-9fd5-cf31aa31d424'::uuid, 'Que permet la déclaration de Londres de 1949 ?', 'mcq', '["De créer l’euro","De dissoudre l’Empire","De rester membre en devenant une république","D’interdire les Jeux"]'::jsonb, 2, 'L’Inde, républicaine, peut ainsi rester membre.', 5),
    ('e81dc696-ae94-5262-a1ea-6f343d4cb858'::uuid, '76c5dc84-67df-56dc-9fd5-cf31aa31d424'::uuid, 'Tous les membres du Commonwealth ont été des colonies britanniques.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le Mozambique, le Rwanda, le Gabon et le Togo n’en ont jamais été.', 6),
    ('6ac0979d-cebe-5231-b933-1645872d2f15'::uuid, '76c5dc84-67df-56dc-9fd5-cf31aa31d424'::uuid, '« To gain independence » signifie…', 'mcq', '["Accéder à l’indépendance","Perdre son indépendance","Refuser l’indépendance","Célébrer l’indépendance"]'::jsonb, 0, 'To gain = obtenir, gagner.', 7),
    ('694d8f6d-1f30-5c99-b096-3d67a59e3a46'::uuid, '76c5dc84-67df-56dc-9fd5-cf31aa31d424'::uuid, 'Qu’est-ce qu’un « Commonwealth realm » ?', 'mcq', '["Une ancienne colonie française","Une république du Commonwealth","Un pays qui a gardé le souverain britannique comme chef d’État","Un territoire sans gouvernement"]'::jsonb, 2, 'Le Canada, l’Australie ou la Jamaïque, par exemple.', 8),
    ('f4e0166c-23f3-5f3b-9caf-2b92a660349a'::uuid, '76c5dc84-67df-56dc-9fd5-cf31aa31d424'::uuid, 'Où se sont déroulés les premiers Jeux de l’Empire britannique, en 1930 ?', 'mcq', '["À Hamilton, au Canada","À Londres","À Sydney","À Delhi"]'::jsonb, 0, 'Ils sont devenus les Commonwealth Games.', 9),
    ('c086f80e-4c37-5050-833d-3b026a3bc541'::uuid, '76c5dc84-67df-56dc-9fd5-cf31aa31d424'::uuid, 'Que reconnaît la déclaration Balfour de 1926 ?', 'mcq', '["L’indépendance de l’Irlande","La fin de l’esclavage","La création de l’ONU","L’égalité des dominions avec le Royaume-Uni"]'::jsonb, 3, 'Le Statut de Westminster (1931) la traduit en droit.', 10),
    ('cc635592-59f9-5e43-b60e-c2ca19ce32a4'::uuid, '76c5dc84-67df-56dc-9fd5-cf31aa31d424'::uuid, 'Quel pays quitte le Commonwealth en 1961 à cause de l’apartheid ?', 'mcq', '["Le Canada","L’Afrique du Sud","L’Inde","La Nouvelle-Zélande"]'::jsonb, 1, 'Il y revient en 1994, après la fin de l’apartheid.', 11),
    ('20fb742c-88f0-5d39-aa59-3b9ff69f13e6'::uuid, '76c5dc84-67df-56dc-9fd5-cf31aa31d424'::uuid, 'Quel sigle désigne le sommet des chefs de gouvernement du Commonwealth ?', 'mcq', '["G7","CHOGM","NATO","UN"]'::jsonb, 1, 'Commonwealth Heads of Government Meeting.', 12),
    ('ae6af0e9-0e66-52db-a33d-6503c3ceb10e'::uuid, '6b5c0485-5c0c-5a96-97de-4e9301505c6e'::uuid, 'Qui a écrit Things Fall Apart (1958) ?', 'mcq', '["Wole Soyinka","Ngugi wa Thiong’o","Chinua Achebe","Nelson Mandela"]'::jsonb, 2, 'Le roman nigérian le plus lu au monde.', 1),
    ('9fd5abcf-6a2e-501b-a7af-75088983629e'::uuid, '6b5c0485-5c0c-5a96-97de-4e9301505c6e'::uuid, 'De quoi parle Midnight’s Children de Salman Rushdie ?', 'mcq', '["D’un conte de Noël","De la guerre du Biafra","D’une école anglaise","D’enfants nés à minuit le jour de l’indépendance de l’Inde"]'::jsonb, 3, 'Leur destin se mêle à celui de l’Inde indépendante.', 2),
    ('3e306fa9-7f72-54cb-b511-7e645dbbfa1d'::uuid, '6b5c0485-5c0c-5a96-97de-4e9301505c6e'::uuid, 'Quel jour célèbre-t-on le Commonwealth Day ?', 'mcq', '["Le 25 décembre","Le deuxième lundi de mars","Le 4 juillet","Le 1er janvier"]'::jsonb, 1, 'Le Commonwealth Day tombe chaque année le deuxième lundi de mars.', 3),
    ('e192c37e-472f-510d-bbca-6414b0c47f05'::uuid, '6b5c0485-5c0c-5a96-97de-4e9301505c6e'::uuid, 'Qu’appelle-t-on le « système de Westminster » ?', 'mcq', '["Un système de défense","Une monnaie commune","Un modèle parlementaire hérité du Royaume-Uni","Une église"]'::jsonb, 2, 'Parlement, Premier ministre issu de la majorité, opposition officielle.', 4),
    ('b3fef7a3-f4c1-528f-bf8e-9e466d667503'::uuid, '6b5c0485-5c0c-5a96-97de-4e9301505c6e'::uuid, 'Quel sport est emblématique du Commonwealth, de l’Inde aux Antilles ?', 'mcq', '["Le cricket","Le baseball","Le hockey sur glace","Le basket-ball"]'::jsonb, 0, 'Un héritage direct de l’Empire.', 5),
    ('ee798fbc-ebe8-57bf-b38e-ca31922b60be'::uuid, '6b5c0485-5c0c-5a96-97de-4e9301505c6e'::uuid, 'Chimamanda Ngozi Adichie a écrit Half of a Yellow Sun sur la guerre du Biafra.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Roman publié en 2006.', 6),
    ('fe2cafe0-c82e-569d-81ca-bc6aeb8dd6f3'::uuid, '6b5c0485-5c0c-5a96-97de-4e9301505c6e'::uuid, 'Que signifie l’expression « the Empire writes back » ?', 'mcq', '["L’Empire publie des journaux","Les rois écrivent leurs mémoires","Les anciens colonisés répondent à l’Empire par la littérature","La Couronne censure les livres"]'::jsonb, 2, 'Elle désigne la littérature postcoloniale.', 7),
    ('881dec06-449a-54eb-a977-73fe0e158411'::uuid, '6b5c0485-5c0c-5a96-97de-4e9301505c6e'::uuid, 'Quelle œuvre est l’autobiographie de Nelson Mandela ?', 'mcq', '["Long Walk to Freedom","The God of Small Things","Half of a Yellow Sun","Things Fall Apart"]'::jsonb, 0, 'Publiée en 1994, l’année de son élection.', 8),
    ('fb7e5f4c-ebb7-5ed3-9525-f25ec9dbbe0b'::uuid, '6b5c0485-5c0c-5a96-97de-4e9301505c6e'::uuid, 'Arundhati Roy a reçu le Booker Prize pour…', 'mcq', '["Midnight’s Children","White Teeth","Wolf Hall","The God of Small Things"]'::jsonb, 3, 'En 1997, pour ce roman situé au Kerala.', 9),
    ('7bd36481-7f44-5b13-b624-784653cb3bca'::uuid, '6b5c0485-5c0c-5a96-97de-4e9301505c6e'::uuid, 'Quel texte de 2013 énonce les valeurs communes du Commonwealth ?', 'mcq', '["La Magna Carta","La Commonwealth Charter","Le Bill of Rights","La Déclaration d’indépendance"]'::jsonb, 1, 'Démocratie, droits humains, État de droit.', 10),
    ('56f2210a-3d13-5b47-b1ac-a76ec688a1b1'::uuid, '6b5c0485-5c0c-5a96-97de-4e9301505c6e'::uuid, '« Ties » dans « economic ties » signifie…', 'mcq', '["Les cravates","Les liens","Les dettes","Les frontières"]'::jsonb, 1, 'Tie = lien (et aussi cravate, selon le contexte).', 11),
    ('58d3a3d5-08af-53fe-b23c-5485ce6aa699'::uuid, '6b5c0485-5c0c-5a96-97de-4e9301505c6e'::uuid, 'Quelle phrase met en avant ce qui unit malgré les différences ?', 'mcq', '["These countries are all identical.","Nothing unites these countries.","These countries are all monarchies.","Despite their differences, these countries share a language."]'::jsonb, 3, 'Despite + nom : malgré leurs différences.', 12),
    ('514c98ca-d291-587e-a878-4ab684a31000'::uuid, 'eb00f5b1-5776-5976-a608-470304ea7ec6'::uuid, 'Quel est le pronom réfléchi de « we » ?', 'mcq', '["ourself","usselves","weselves","ourselves"]'::jsonb, 3, 'Pluriel en -selves, construit sur our.', 1),
    ('a1e45be8-6bc1-5252-82d2-56df1a64368b'::uuid, 'eb00f5b1-5776-5976-a608-470304ea7ec6'::uuid, '« They looked at each other » signifie…', 'mcq', '["Ils se sont regardés dans le miroir","Ils se sont regardés l’un l’autre","Ils ont regardé les autres","Chacun a regardé ailleurs"]'::jsonb, 1, 'Each other marque la réciprocité.', 2),
    ('107b04dd-97d7-54ef-bb67-b979823f709e'::uuid, 'eb00f5b1-5776-5976-a608-470304ea7ec6'::uuid, 'Complète : « She introduced ___ to the class. »', 'mcq', '["her","hers","herself","himself"]'::jsonb, 2, 'Sujet et complément sont la même personne.', 3),
    ('431048df-a2ab-5fc2-92eb-1c6d50fece4c'::uuid, 'eb00f5b1-5776-5976-a608-470304ea7ec6'::uuid, 'Comment traduire « Je me suis levé à sept heures » ?', 'mcq', '["I got up at seven.","I raised myself at seven.","I got myself up at seven.","I stood me at seven."]'::jsonb, 0, 'To get up n’a pas besoin de pronom réfléchi.', 4),
    ('83d80838-2888-5af1-9638-61258d9f7046'::uuid, 'eb00f5b1-5776-5976-a608-470304ea7ec6'::uuid, '« She lives by herself » signifie…', 'mcq', '["Elle vit près de chez elle","Elle vit pour elle-même","Elle vit toute seule","Elle vit avec sa sœur"]'::jsonb, 2, 'By + réfléchi = sans personne.', 5),
    ('cba3abee-f6cc-50e4-8ba3-42986ca30aa5'::uuid, 'eb00f5b1-5776-5976-a608-470304ea7ec6'::uuid, 'Quel est le réfléchi de « they » ?', 'mcq', '["themselves","themself","theirselves","theyselves"]'::jsonb, 0, 'Construit sur them, au pluriel.', 6),
    ('b2b3af1c-7470-5699-a124-5cb6962ba910'::uuid, 'eb00f5b1-5776-5976-a608-470304ea7ec6'::uuid, 'Dans « I did it myself », le pronom réfléchi…', 'mcq', '["Est une faute","Marque la réciprocité","Remplace le sujet","Insiste : moi-même, sans aide"]'::jsonb, 3, 'C’est l’emploi emphatique.', 7),
    ('06658d5e-fbee-5dab-9437-d360dcac027a'::uuid, 'eb00f5b1-5776-5976-a608-470304ea7ec6'::uuid, '« Se souvenir » se traduit par « to remember oneself ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On dit simplement to remember.', 8),
    ('dd39bacb-4794-5b99-aa8f-39f7a469fd1b'::uuid, 'eb00f5b1-5776-5976-a608-470304ea7ec6'::uuid, '« Enjoy yourselves! » s’adresse…', 'mcq', '["À une seule personne","À plusieurs personnes","À soi-même","À un animal"]'::jsonb, 1, 'Yourselves est le pluriel de yourself.', 9),
    ('10cb9adc-7a50-5ad7-9ec7-27bfb8401cfd'::uuid, 'eb00f5b1-5776-5976-a608-470304ea7ec6'::uuid, 'Complète : « The two friends helped ___ with their homework. »', 'mcq', '["themselves","each other","theirselves","them"]'::jsonb, 1, 'Chacun aide l’autre : c’est réciproque.', 10),
    ('195b0163-d243-595c-bacc-c0ada091ec3c'::uuid, 'eb00f5b1-5776-5976-a608-470304ea7ec6'::uuid, 'Comment traduire « s’habiller » ?', 'mcq', '["to dress oneself up","to wear oneself","to clothe","to get dressed"]'::jsonb, 3, 'L’anglais courant dit to get dressed.', 11),
    ('0ddf65ed-f25a-51f0-aed1-f4e0f015044e'::uuid, 'eb00f5b1-5776-5976-a608-470304ea7ec6'::uuid, 'Quel pronom réfléchi correspond à « it » ?', 'mcq', '["itself","itselves","its self","himself"]'::jsonb, 0, 'The door closed by itself.', 12),
    ('65253c1b-3274-54ce-9f8c-14a114d41de7'::uuid, '952ce4f3-b039-53ed-8c8c-1d3ad75a49a4'::uuid, 'Que désigne « a teacup » ?', 'mcq', '["Une tasse de thé","Une tasse à thé","Un sachet de thé","Une théière"]'::jsonb, 1, 'Le nom de droite (cup) est l’objet ; tea le précise.', 1),
    ('faa3c64c-a45a-5cb2-9778-04018833fcd3'::uuid, '952ce4f3-b039-53ed-8c8c-1d3ad75a49a4'::uuid, 'Comment dire « une pause de dix minutes » avec un adjectif composé ?', 'mcq', '["a ten-minutes break","a ten minutes’ break","a ten-minute break","a break ten-minute"]'::jsonb, 2, 'Le nom employé comme adjectif reste au singulier.', 2),
    ('ad1235d5-2edb-5f62-adfd-7b496aa78e88'::uuid, '952ce4f3-b039-53ed-8c8c-1d3ad75a49a4'::uuid, '« A children’s book » signifie…', 'mcq', '["Un livre pour enfants","Le livre des enfants de quelqu’un","Un livre écrit par un enfant précis","Des livres d’enfants"]'::jsonb, 0, 'Génitif de catégorie : un type de livre.', 3),
    ('5495ee90-4b2b-5532-b644-80ec71ed41b1'::uuid, '952ce4f3-b039-53ed-8c8c-1d3ad75a49a4'::uuid, 'Dans « a sports car », quel est le nom principal ?', 'mcq', '["sports","a","car","les deux"]'::jsonb, 2, 'On lit de droite à gauche : c’est une voiture.', 4),
    ('6e2cfe88-af68-5f9b-b35a-dfeb7d445d25'::uuid, '952ce4f3-b039-53ed-8c8c-1d3ad75a49a4'::uuid, 'Laquelle de ces formes est correcte ?', 'mcq', '["a shoe shop","a shoes shop","a shop of shoes","a shoe’s shop"]'::jsonb, 0, 'Le premier nom reste au singulier.', 5),
    ('0caffb73-20b3-5cd9-b14f-5c3ea93938a4'::uuid, '952ce4f3-b039-53ed-8c8c-1d3ad75a49a4'::uuid, '« A black-haired man » est…', 'mcq', '["Un homme noir","Un coiffeur","Un homme chauve","Un homme aux cheveux noirs"]'::jsonb, 3, 'Adjectif + nom + -ed.', 6),
    ('04a8f1dc-f21a-5bbc-b1c8-43c5b31d0fe2'::uuid, '952ce4f3-b039-53ed-8c8c-1d3ad75a49a4'::uuid, 'On écrit « a ten-years-old girl ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On écrit a ten-year-old girl : pas de -s dans l’adjectif composé.', 7),
    ('d2daaa00-29c4-502e-8c5b-e9ceeff43cca'::uuid, '952ce4f3-b039-53ed-8c8c-1d3ad75a49a4'::uuid, 'Quelle structure convient pour une quantité ?', 'mcq', '["a shoes pair","a pair of shoes","a shoes’ pair","a pair-shoes"]'::jsonb, 1, 'Nom of nom pour la quantité ou le contenu.', 8),
    ('d653a268-3489-5f3b-8c89-3d255396335b'::uuid, '952ce4f3-b039-53ed-8c8c-1d3ad75a49a4'::uuid, 'Que signifie « the Home Secretary » ?', 'mcq', '["La secrétaire à domicile","Le ministre de l’Intérieur","Le chef de famille","Le président de l’Assemblée"]'::jsonb, 1, 'Un titre politique britannique.', 9),
    ('8be9be4d-3465-59f3-9268-c42eb40f29e4'::uuid, '952ce4f3-b039-53ed-8c8c-1d3ad75a49a4'::uuid, '« A home-made cake » est…', 'mcq', '["Un gâteau acheté","Un gâteau pour la maison","Un gâteau d’anniversaire","Un gâteau fait maison"]'::jsonb, 3, 'Nom + participe passé.', 10),
    ('cb802bca-aa9c-51c7-8481-d604b02ff9ff'::uuid, '952ce4f3-b039-53ed-8c8c-1d3ad75a49a4'::uuid, 'Comment traduire « une histoire déchirante » ?', 'mcq', '["a heart-breaking story","a heart-broken story","a breaking-heart story","a story heart-breaking"]'::jsonb, 0, 'Participe en -ing : c’est l’histoire qui brise le cœur.', 11),
    ('62ad5061-a3a3-5b0b-9936-a18a8cf03531'::uuid, '952ce4f3-b039-53ed-8c8c-1d3ad75a49a4'::uuid, 'Dans « a well-known singer », « well-known » se place…', 'mcq', '["Après le nom","En fin de phrase","Devant le nom","N’importe où"]'::jsonb, 2, 'Comme tout adjectif épithète anglais.', 12),
    ('c9c77259-3f97-5c45-b5db-b0a860734c96'::uuid, 'c657c283-7cc4-5043-ae4d-3df79ce97da8'::uuid, 'Complète : « ___ people like music. » (en général)', 'mcq', '["Most of","The most","Most","Most of the"]'::jsonb, 2, 'Nom sans déterminant : pas de of.', 1),
    ('4b704989-d789-5623-bbeb-eff59531d00a'::uuid, 'c657c283-7cc4-5043-ae4d-3df79ce97da8'::uuid, 'Laquelle est correcte ?', 'mcq', '["Most of us agree.","Most of we agree.","Most us agree.","The most of us agree."]'::jsonb, 0, 'Après of, le pronom est complément : us.', 2),
    ('5fdfa3a5-5ce8-5801-bb1b-e6f6c56812f3'::uuid, 'c657c283-7cc4-5043-ae4d-3df79ce97da8'::uuid, '« None of them came » signifie…', 'mcq', '["Ils sont tous venus","Certains sont venus","Aucun d’eux n’est venu","Personne ne les a invités"]'::jsonb, 2, 'None contient déjà la négation.', 3),
    ('97f01c90-8932-5510-94bd-1b9b5cf20898'::uuid, 'c657c283-7cc4-5043-ae4d-3df79ce97da8'::uuid, 'On peut écrire « None of them didn’t come » pour dire « aucun n’est venu ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Double négation fautive : None of them came.', 4),
    ('e9ea62e9-fc6a-57fc-bb6d-e2b192c22e75'::uuid, 'c657c283-7cc4-5043-ae4d-3df79ce97da8'::uuid, 'Complète : « Most ___ my friends play video games. »', 'mcq', '["of","the","from","in"]'::jsonb, 0, 'Devant un possessif, on met of.', 5),
    ('c7567d3e-fe54-5831-b0e4-a957b987fbfb'::uuid, 'c657c283-7cc4-5043-ae4d-3df79ce97da8'::uuid, 'Comment dire « les deux » devant un pronom ?', 'mcq', '["both us","the both us","both we","both of us"]'::jsonb, 3, 'Devant un pronom, of est obligatoire.', 6),
    ('57053fc6-96d9-5a0a-9f62-1a0dcff339fe'::uuid, 'c657c283-7cc4-5043-ae4d-3df79ce97da8'::uuid, 'Dans « all the students », « of » est…', 'mcq', '["Obligatoire","Facultatif","Interdit","Placé à la fin"]'::jsonb, 1, 'All (of) the students : les deux se disent.', 7),
    ('068bc7c1-9c55-54d8-8e6a-f7a1c021e333'::uuid, 'c657c283-7cc4-5043-ae4d-3df79ce97da8'::uuid, 'Choisis le bon verbe : « Most of the cake ___ eaten. »', 'mcq', '["were","was","are","have"]'::jsonb, 1, 'Cake ici est indénombrable (le gâteau) : singulier.', 8),
    ('7e5ddd79-ab0e-5fff-9789-6d71e8b235b2'::uuid, 'c657c283-7cc4-5043-ae4d-3df79ce97da8'::uuid, 'Quel mot signifie « la moitié » ?', 'mcq', '["halves","middle","part","half"]'::jsonb, 3, 'Half of us : la moitié d’entre nous.', 9),
    ('0d17b06d-25c4-5843-bc99-1919316617b6'::uuid, 'c657c283-7cc4-5043-ae4d-3df79ce97da8'::uuid, '« Some of them disagree » signifie…', 'mcq', '["Certains d’entre eux ne sont pas d’accord","Ils sont tous d’accord","Aucun n’est d’accord","Ils sont un peu d’accord"]'::jsonb, 0, 'Some of = une partie d’un groupe précis.', 10),
    ('21a59e4c-9bf3-5198-8283-73c71489267a'::uuid, 'c657c283-7cc4-5043-ae4d-3df79ce97da8'::uuid, 'Laquelle parle d’un groupe PRÉCIS ?', 'mcq', '["Most teenagers use phones.","Teenagers use phones.","Most of the teenagers in this school use phones.","Many teenagers use phones."]'::jsonb, 2, 'The + précision : un groupe identifié, donc of.', 11),
    ('12d5bd98-dd2e-5107-aec4-085529b96637'::uuid, 'c657c283-7cc4-5043-ae4d-3df79ce97da8'::uuid, 'Complète : « ___ of my parents work in London. » (les deux)', 'mcq', '["All","Either","Half","Both"]'::jsonb, 3, 'Both = les deux, pour un groupe de deux.', 12),
    ('2e27d63c-84b2-5638-8fca-6f7db74b5231'::uuid, '4c565358-9831-5750-985c-00f71657b35d'::uuid, 'Réponds brièvement et positivement : « Do you like tea? »', 'mcq', '["Yes, I do.","Yes, I like.","Yes, I am.","Yes, I does."]'::jsonb, 0, 'On reprend l’auxiliaire do.', 1),
    ('f01fdb86-cf51-5102-9b61-ef81b93fc04d'::uuid, '4c565358-9831-5750-985c-00f71657b35d'::uuid, '« I love pizza. » Comment dire « Moi aussi » ?', 'mcq', '["So I do.","Neither do I.","So do I.","Me too do."]'::jsonb, 2, 'So + auxiliaire + sujet, dans cet ordre.', 2),
    ('baa776af-37b2-5cf5-9e11-04406aac9743'::uuid, '4c565358-9831-5750-985c-00f71657b35d'::uuid, '« I can’t swim. » Comment dire « Moi non plus » ?', 'mcq', '["Neither can I.","So can I.","Neither I can.","Me neither can."]'::jsonb, 0, 'Neither pour une phrase négative, avec l’auxiliaire can.', 3),
    ('2b55b7f7-2ed4-55f7-817a-984bbc292d22'::uuid, '4c565358-9831-5750-985c-00f71657b35d'::uuid, '« She has been to London. » Complète : « So ___ I. »', 'mcq', '["do","did","am","have"]'::jsonb, 3, 'L’auxiliaire se choisit sur la phrase de départ : has → have.', 4),
    ('fd09706e-b450-5d30-8a42-2f2100d21735'::uuid, '4c565358-9831-5750-985c-00f71657b35d'::uuid, '« He went home early. » Moi aussi :', 'mcq', '["So went I.","So did I.","So do I.","So was I."]'::jsonb, 1, 'Prétérit simple : l’auxiliaire est did.', 5),
    ('40c31385-91f3-55b1-bac2-e707fa4afeed'::uuid, '4c565358-9831-5750-985c-00f71657b35d'::uuid, 'La réponse « Yes, I’m » est correcte.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Pas de contraction dans une réponse courte affirmative : Yes, I am.', 6),
    ('3cf8a79b-ae62-5e1a-9c4f-3e460441794d'::uuid, '4c565358-9831-5750-985c-00f71657b35d'::uuid, 'Comment dire « J’espère que non » ?', 'mcq', '["I don’t hope so.","I hope not.","I hope no.","I not hope."]'::jsonb, 1, 'Hope se construit avec not, pas avec don’t.', 7),
    ('9ddecc49-5595-5eb4-9168-a30ead311561'::uuid, '4c565358-9831-5750-985c-00f71657b35d'::uuid, '« Will they come? » — « Je crois que oui » :', 'mcq', '["I think yes.","I think it.","I believe that yes.","I think so."]'::jsonb, 3, 'So reprend toute la proposition.', 8),
    ('4720fd94-1928-5ecf-be40-a6cc3f4fab7a'::uuid, '4c565358-9831-5750-985c-00f71657b35d'::uuid, '« I can’t swim. — I can. » La seconde réplique exprime…', 'mcq', '["Le désaccord : moi, si","L’accord","Une question","Un ordre"]'::jsonb, 0, 'Sujet devant l’auxiliaire, polarité inversée.', 9),
    ('5f179267-1058-5aa3-84b3-eae78440b89d'::uuid, '4c565358-9831-5750-985c-00f71657b35d'::uuid, '« They won’t come. » Nous non plus :', 'mcq', '["Neither we will.","So won’t we.","Neither will we.","Neither do we."]'::jsonb, 2, 'Will est l’auxiliaire de la phrase de départ.', 10),
    ('92bfecfd-de84-58ee-ae75-59f88efdc3b6'::uuid, '4c565358-9831-5750-985c-00f71657b35d'::uuid, '« I’ve just moved to Leeds. — Have you? » La réponse signifie…', 'mcq', '["Tu as déménagé ?","Où ça ?","Moi aussi.","Ah bon ?"]'::jsonb, 3, 'Une question-réaction qui marque l’intérêt.', 11),
    ('343ded15-53fc-5b38-8f25-f698d96cc8e2'::uuid, '4c565358-9831-5750-985c-00f71657b35d'::uuid, '« Is she French? » Réponse négative :', 'mcq', '["No, she doesn’t.","No, she isn’t.","No, she not.","No, isn’t she."]'::jsonb, 1, 'On reprend l’auxiliaire be.', 12),
    ('6a1eb5d3-ad09-5397-ae13-b964697d8944'::uuid, '1807e7ba-58d6-5682-bb52-16b483809833'::uuid, 'Quel connecteur AJOUTE une idée ?', 'mcq', '["However","Therefore","Moreover","Yet"]'::jsonb, 2, 'Moreover = de plus.', 1),
    ('7d0eca0a-c859-5f96-a83b-d4c431f3c492'::uuid, '1807e7ba-58d6-5682-bb52-16b483809833'::uuid, 'Que signifie « for instance » ?', 'mcq', '["Par exemple","Pour l’instant","Instantanément","Pour conclure"]'::jsonb, 0, 'Synonyme de for example.', 2),
    ('b5a19420-aa4d-5ed2-a2ba-edede754be76'::uuid, '1807e7ba-58d6-5682-bb52-16b483809833'::uuid, 'Quel connecteur introduit une conséquence ?', 'mcq', '["Besides","Such as","However","As a result"]'::jsonb, 3, 'As a result = en conséquence.', 3),
    ('200b150d-8321-5dd7-9f72-e0974b860be7'::uuid, '1807e7ba-58d6-5682-bb52-16b483809833'::uuid, '« At last » peut remplacer « finally » pour annoncer le dernier argument.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'At last exprime le soulagement : « enfin ! ». Pour le dernier point : finally.', 4),
    ('3e46dc89-34b3-53fa-989c-dfb71a692e8b'::uuid, '1807e7ba-58d6-5682-bb52-16b483809833'::uuid, 'Que signifie « actually » ?', 'mcq', '["Actuellement","En fait","Activement","Autrefois"]'::jsonb, 1, 'Faux ami : « actuellement » se dit currently ou nowadays.', 5),
    ('a969ef42-c37b-5adf-adb3-a8b3c3c01a34'::uuid, '1807e7ba-58d6-5682-bb52-16b483809833'::uuid, 'Complète : « It was raining, ___ we stayed at home. »', 'mcq', '["however","so","moreover","such as"]'::jsonb, 1, 'So relie deux propositions pour marquer la conséquence.', 6),
    ('ce46908b-e33e-5627-a321-bfee0c23cbb5'::uuid, '1807e7ba-58d6-5682-bb52-16b483809833'::uuid, 'Comment dire « dans un premier temps » dans un essai ?', 'mcq', '["In a first time","At first time","Firstly time","First of all"]'::jsonb, 3, 'In a first time est un calque fautif.', 7),
    ('1105c4d1-b9b7-5a2e-a5cf-ac6e86f8d809'::uuid, '1807e7ba-58d6-5682-bb52-16b483809833'::uuid, 'Quelle ponctuation suit « However » en tête de phrase ?', 'mcq', '["Une virgule","Aucune","Un point-virgule","Deux-points"]'::jsonb, 0, 'However, the results are good.', 8),
    ('328435b8-7f84-548c-ad94-4161dd638fbc'::uuid, '1807e7ba-58d6-5682-bb52-16b483809833'::uuid, 'Quel connecteur introduit une opposition ?', 'mcq', '["In addition","What is more","On the other hand","Such as"]'::jsonb, 2, 'On the other hand = d’un autre côté.', 9),
    ('28b6719f-31df-5f82-9159-6ea20d38045b'::uuid, '1807e7ba-58d6-5682-bb52-16b483809833'::uuid, 'Quel connecteur sert à conclure ?', 'mcq', '["Besides","For example","Next","To sum up"]'::jsonb, 3, 'To sum up = pour résumer.', 10),
    ('cfa09c78-e423-5dae-b9a9-1f0e5f08ec92'::uuid, '1807e7ba-58d6-5682-bb52-16b483809833'::uuid, 'Dans « sports such as rugby », « such as » sert à…', 'mcq', '["Opposer","Illustrer par un exemple","Conclure","Ajouter un argument"]'::jsonb, 1, 'Such as = comme, tel que.', 11),
    ('971adbd7-87da-55d9-aa1a-93d4071ee362'::uuid, '1807e7ba-58d6-5682-bb52-16b483809833'::uuid, 'Quel connecteur est synonyme de « therefore » ?', 'mcq', '["Although","Besides","Consequently","Meanwhile"]'::jsonb, 2, 'Tous deux signifient « par conséquent ».', 12),
    ('17d69c5f-74e0-5564-ac5c-3dfe52b5f3f4'::uuid, 'c83fb9a7-41b0-5a41-b209-aebd96829d34'::uuid, 'Complète : « She lives ___ London. »', 'mcq', '["in","at","on","to"]'::jsonb, 0, 'Une ville : in.', 1),
    ('2c382679-a4bf-5802-8394-2dfc701cb908'::uuid, 'c83fb9a7-41b0-5a41-b209-aebd96829d34'::uuid, 'Complète : « The picture is ___ the wall. »', 'mcq', '["in","at","into","on"]'::jsonb, 3, 'Une surface : on.', 2),
    ('afeff7b5-f7cf-5c5e-955a-4220af6e453e'::uuid, 'c83fb9a7-41b0-5a41-b209-aebd96829d34'::uuid, 'Complète : « I’ll meet you ___ the station. »', 'mcq', '["in","at","on","to"]'::jsonb, 1, 'Un point de rendez-vous : at.', 3),
    ('4bbfebc0-ff3c-5de1-b3af-7a3bf72236a0'::uuid, 'c83fb9a7-41b0-5a41-b209-aebd96829d34'::uuid, 'Comment dire « au premier plan » ?', 'mcq', '["In the first plan","In the foreground","At the front plan","On the first ground"]'::jsonb, 1, 'In the first plan est un calque fautif.', 4),
    ('79f03b0c-ac57-5a7a-8794-bb55a81c6631'::uuid, 'c83fb9a7-41b0-5a41-b209-aebd96829d34'::uuid, 'Quelle forme est correcte ?', 'mcq', '["We arrived to London.","We arrived at London.","We arrived on London.","We arrived in London."]'::jsonb, 3, 'Arrive in pour une ville, jamais arrive to.', 5),
    ('321a805b-19a1-502e-a626-bc77ed3d567e'::uuid, 'c83fb9a7-41b0-5a41-b209-aebd96829d34'::uuid, 'On dit « on the bus » mais « in a car ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'On se déplace dans un bus ; on est enfermé dans une voiture.', 6),
    ('ff2fe349-6ef6-512c-9d29-dd955b1df696'::uuid, 'c83fb9a7-41b0-5a41-b209-aebd96829d34'::uuid, 'Que signifie « opposite » dans « the bank is opposite the church » ?', 'mcq', '["En face de","À côté de","Derrière","Loin de"]'::jsonb, 0, 'Opposite = en face de.', 7),
    ('98b22dc1-45c9-5ddd-8c47-eb3491595c73'::uuid, 'c83fb9a7-41b0-5a41-b209-aebd96829d34'::uuid, 'Comment dire « tout au bout de la rue » ?', 'mcq', '["in the end street","on the far street","at the far end of the street","at the last of the street"]'::jsonb, 2, 'At the far end of = tout au bout de.', 8),
    ('a77bd27a-6030-5b2e-9578-cdffd0a6be22'::uuid, 'c83fb9a7-41b0-5a41-b209-aebd96829d34'::uuid, 'Complète : « She walked ___ the room. » (elle est entrée)', 'mcq', '["in","at","on","into"]'::jsonb, 3, 'Into marque l’entrée dans un espace.', 9),
    ('e86324c2-5431-52b0-9bf3-fafd5149dd3e'::uuid, 'c83fb9a7-41b0-5a41-b209-aebd96829d34'::uuid, 'Quelle forme est correcte ?', 'mcq', '["I go to home.","I go home.","I go at home.","I go in home."]'::jsonb, 1, 'Home s’emploie sans préposition après un verbe de mouvement.', 10),
    ('365f0d89-70bb-50e9-8b17-12e44adcb68b'::uuid, 'c83fb9a7-41b0-5a41-b209-aebd96829d34'::uuid, 'Comment dire « dans le coin en haut à gauche » ?', 'mcq', '["at the left top corner","on the up left corner","in the top left-hand corner","in the corner of top left"]'::jsonb, 2, 'L’expression figée pour décrire une image.', 11),
    ('e091e7fd-5d9a-5177-8496-ce6625e488a1'::uuid, 'c83fb9a7-41b0-5a41-b209-aebd96829d34'::uuid, 'Complète : « They live ___ 10 Downing Street. »', 'mcq', '["at","in","on","to"]'::jsonb, 0, 'Une adresse précise avec un numéro : at.', 12),
    ('61d6a22b-3d9d-594b-910d-22f7f11abaf0'::uuid, '57d97287-32c0-545b-b459-9848a92f4ed7'::uuid, 'En quelle année ont eu lieu les procès des sorcières de Salem ?', 'mcq', '["1692","1620","1776","1865"]'::jsonb, 0, 'Dix-neuf personnes y sont pendues.', 1),
    ('c77a5b1e-d36b-5081-abf5-6fb03f776a53'::uuid, '57d97287-32c0-545b-b459-9848a92f4ed7'::uuid, 'Quelle pièce d’Arthur Miller utilise Salem pour dénoncer le maccarthysme ?', 'mcq', '["Death of a Salesman","A View from the Bridge","All My Sons","The Crucible"]'::jsonb, 3, 'Créée en 1953, en pleine peur rouge.', 2),
    ('672c4fff-d036-52fd-bf0d-d006e401bb00'::uuid, '57d97287-32c0-545b-b459-9848a92f4ed7'::uuid, 'Qui étaient les « Hollywood Ten » ?', 'mcq', '["Des acteurs oscarisés","Des scénaristes et réalisateurs condamnés en 1947 pour avoir refusé de répondre à la HUAC","Les fondateurs des grands studios","Des sénateurs"]'::jsonb, 1, 'Ils ont été mis sur liste noire.', 3),
    ('f8e7c6fe-10ed-53d2-9e1c-4bc3a272e8c7'::uuid, '57d97287-32c0-545b-b459-9848a92f4ed7'::uuid, 'Quel arrêt de 2022 a renversé Roe v. Wade ?', 'mcq', '["Obergefell","Dobbs","Brown","Plessy"]'::jsonb, 1, 'L’avortement relève désormais de chaque État.', 4),
    ('502ecc9a-41b6-54f0-a4ef-e997ad94a25f'::uuid, '57d97287-32c0-545b-b459-9848a92f4ed7'::uuid, 'Que signifie « privacy » ?', 'mcq', '["La privation","Le secteur privé","La propriété","La vie privée"]'::jsonb, 3, 'Faux ami partiel : privacy n’est pas « privation ».', 5),
    ('3fd697f7-4a57-594e-aadd-eb3e1213dc47'::uuid, '57d97287-32c0-545b-b459-9848a92f4ed7'::uuid, 'Qui est le gouverneur suprême de l’Église d’Angleterre ?', 'mcq', '["Le souverain britannique","L’archevêque de Cantorbéry","Le Premier ministre","Le pape"]'::jsonb, 0, 'Titre fixé sous Élisabeth Ire (1559), après la rupture d’Henri VIII avec Rome.', 6),
    ('584476a4-afdd-5b9f-b338-3b1f708cf1d2'::uuid, '57d97287-32c0-545b-b459-9848a92f4ed7'::uuid, 'Le premier amendement de la Constitution américaine interdit l’établissement d’une religion d’État.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Adopté en 1791 avec la Déclaration des droits.', 7),
    ('ff0debb0-41df-521b-be0d-3ba8250e06a7'::uuid, '57d97287-32c0-545b-b459-9848a92f4ed7'::uuid, 'Qui a écrit The Handmaid’s Tale (1985) ?', 'mcq', '["Toni Morrison","Alice Munro","Margaret Atwood","Sylvia Plath"]'::jsonb, 2, 'Autrice canadienne.', 8),
    ('23664d25-9401-5625-a178-322bb28f2a07'::uuid, '57d97287-32c0-545b-b459-9848a92f4ed7'::uuid, 'En quelle année les Britanniques obtiennent-elles le droit de vote à égalité avec les hommes ?', 'mcq', '["1918","1945","1969","1928"]'::jsonb, 3, 'En 1918, seules les femmes de plus de 30 ans votaient.', 9),
    ('b2009215-e668-5a09-82ec-87ca21ea5a9b'::uuid, '57d97287-32c0-545b-b459-9848a92f4ed7'::uuid, 'Que désigne « a witch hunt » au sens figuré ?', 'mcq', '["Une fête d’Halloween","Une persécution collective sans preuve","Une enquête scientifique","Une chasse traditionnelle"]'::jsonb, 1, 'L’expression vaut pour Salem comme pour le maccarthysme.', 10),
    ('26aefc72-8bf3-5ed7-a8b1-8167f6ca870e'::uuid, '57d97287-32c0-545b-b459-9848a92f4ed7'::uuid, 'Quelle est la devise nationale des États-Unis depuis 1956 ?', 'mcq', '["E pluribus unum","Liberty and Justice","In God We Trust","Land of the Free"]'::jsonb, 2, 'Elle figure sur les billets de banque.', 11),
    ('27f6336b-2895-5a41-9ddd-86060ff1b5bb'::uuid, '57d97287-32c0-545b-b459-9848a92f4ed7'::uuid, 'Que signifie « This is none of the State’s business » ?', 'mcq', '["Cela ne regarde pas l’État","L’État est en faillite","L’État n’a pas d’entreprises","C’est l’affaire de l’État"]'::jsonb, 0, 'Business = ici, ce qui nous regarde.', 12),
    ('0afe2e10-cc5e-530e-989d-5af7c1bf5ade'::uuid, 'd5d8d0c1-37ea-544c-a753-4c88047639f1'::uuid, 'Quelle loi britannique de 1833 abolit l’esclavage dans l’Empire ?', 'mcq', '["Le Slave Trade Act","Le Bill of Rights","Le Reform Act","Le Slavery Abolition Act"]'::jsonb, 3, 'La traite, elle, avait été abolie en 1807.', 1),
    ('df0b808b-b678-58d6-97c0-c8ec4383ec42'::uuid, 'd5d8d0c1-37ea-544c-a753-4c88047639f1'::uuid, 'Que commémore Juneteenth ?', 'mcq', '["L’indépendance américaine","L’annonce de leur liberté aux derniers esclaves du Texas, en 1865","La fin de la guerre de Corée","Le discours de Martin Luther King"]'::jsonb, 1, 'Jour férié fédéral depuis 2021.', 2),
    ('417c3ebb-8964-59e5-b169-428e8e66d04a'::uuid, 'd5d8d0c1-37ea-544c-a753-4c88047639f1'::uuid, 'Quel amendement abolit l’esclavage aux États-Unis en 1865 ?', 'mcq', '["Le 1er","Le 13e","Le 5e","Le 19e"]'::jsonb, 1, 'Adopté à la fin de la guerre de Sécession.', 3),
    ('67f30a7a-0397-5efb-bfad-323a21fd4eb0'::uuid, 'd5d8d0c1-37ea-544c-a753-4c88047639f1'::uuid, 'Quelle fleur porte-t-on pour Remembrance Day ?', 'mcq', '["La rose","La jonquille","Le chardon","Le coquelicot"]'::jsonb, 3, 'Le poppy des champs de bataille de Flandre.', 4),
    ('e04e6676-c491-54e9-9e2b-49bc2af460bc'::uuid, 'd5d8d0c1-37ea-544c-a753-4c88047639f1'::uuid, 'Quel roman de Toni Morrison (1987) évoque l’héritage de l’esclavage ?', 'mcq', '["Beloved","The Color Purple","Roots","Invisible Man"]'::jsonb, 0, 'Prix Pulitzer 1988.', 5),
    ('b9e1eb7e-d251-58fc-8d2c-eacc3652a8d7'::uuid, 'd5d8d0c1-37ea-544c-a753-4c88047639f1'::uuid, 'ANZAC Day commémore la bataille de Gallipoli (1915).', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le 25 avril, en Australie et en Nouvelle-Zélande.', 6),
    ('427f067f-eca2-5d5f-9fda-f3d1635bff82'::uuid, 'd5d8d0c1-37ea-544c-a753-4c88047639f1'::uuid, 'Quel traité de 1840 lie la Couronne britannique à des chefs maoris ?', 'mcq', '["Le traité de Paris","Le traité de Versailles","Le traité de Waitangi","Le traité d’Utrecht"]'::jsonb, 2, 'Texte fondateur de la Nouvelle-Zélande.', 7),
    ('4f532c7e-c5a9-5c02-8391-ccac841f5e1b'::uuid, 'd5d8d0c1-37ea-544c-a753-4c88047639f1'::uuid, 'Dans quelle ville britannique a ouvert l’International Slavery Museum en 2007 ?', 'mcq', '["Londres","Bristol","Glasgow","Liverpool"]'::jsonb, 3, 'Liverpool fut l’un des grands ports de la traite.', 8),
    ('9a881b4d-74be-57a4-853d-4f4884d04f1e'::uuid, 'd5d8d0c1-37ea-544c-a753-4c88047639f1'::uuid, 'Que signifie « to reclaim one’s past » ?', 'mcq', '["Réclamer un remboursement","Se réapproprier son passé","Oublier son passé","Réécrire un contrat"]'::jsonb, 1, 'To reclaim = revendiquer, reprendre possession.', 9),
    ('32f8aba1-c36f-5851-a7dc-afd421edcdfd'::uuid, 'd5d8d0c1-37ea-544c-a753-4c88047639f1'::uuid, 'Pourquoi préfère-t-on souvent « enslaved people » à « slaves » ?', 'mcq', '["Pour raccourcir la phrase","Parce que slave est un mot familier","Pour rappeler que ces personnes ont été réduites en esclavage","Parce que c’est plus ancien"]'::jsonb, 2, 'L’expression met l’accent sur l’acte subi.', 10),
    ('963727f3-6c10-59aa-92e4-9a69c41848d9'::uuid, 'd5d8d0c1-37ea-544c-a753-4c88047639f1'::uuid, 'Quel film de Steve McQueen a reçu l’Oscar du meilleur film en 2014 ?', 'mcq', '["12 Years a Slave","Selma","Django Unchained","The Help"]'::jsonb, 0, 'Sorti en 2013, d’après le récit de Solomon Northup.', 11),
    ('c262b635-4073-5cbe-a0b7-23fadfb82aed'::uuid, 'd5d8d0c1-37ea-544c-a753-4c88047639f1'::uuid, 'En quelle année les premiers Africains réduits en esclavage arrivent-ils en Virginie ?', 'mcq', '["1492","1776","1619","1807"]'::jsonb, 2, 'Une date devenue centrale dans la mémoire américaine.', 12),
    ('58382a20-ab87-5f8e-aa50-276b377f3a35'::uuid, '5e873394-cdea-5376-b8f6-25823fff9d0f'::uuid, 'Qui a écrit Nineteen Eighty-Four (1949) ?', 'mcq', '["Aldous Huxley","George Orwell","Ray Bradbury","H. G. Wells"]'::jsonb, 1, 'Big Brother is watching you.', 1),
    ('c0523a5c-ec4d-5ae2-8385-bd171476ef07'::uuid, '5e873394-cdea-5376-b8f6-25823fff9d0f'::uuid, 'Que brûle-t-on dans Fahrenheit 451 ?', 'mcq', '["Des drapeaux","Des livres","Des forêts","Des maisons"]'::jsonb, 1, '451 °F serait la température à laquelle le papier s’enflamme.', 2),
