    ('4a864abe-5f55-5893-9019-b1a92323b6d2'::uuid, '1ce71406-4792-5ad8-9e02-39861ce91d16'::uuid, 'Quelle fraction vaut 12,5 % ?', 'mcq', '["1/12","1/5","1/4","1/8"]'::jsonb, 3, '12,5 % = 0,125 = 1/8.', 12),
