    ('c3f24b70-e068-5ce6-a07b-27a3fac036e4'::uuid, 'b38e8d52-168a-53bd-a6ac-58339b4103ff'::uuid, 'Un article à 80 euros augmente de 15 %. Quel est son nouveau prix ?', 'mcq', '["95 euros","81,20 euros","68 euros","92 euros"]'::jsonb, 3, '80 × 1,15 = 92.', 2),
    ('a0fd285a-b5cb-5205-88e1-f91559bfd277'::uuid, 'b38e8d52-168a-53bd-a6ac-58339b4103ff'::uuid, 'Après une baisse de 20 %, un prix vaut 64 euros. Quel était le prix initial ?', 'mcq', '["76,80 euros","84 euros","80 euros","51,20 euros"]'::jsonb, 2, 'On divise par le coefficient : 64 / 0,8 = 80.', 3),
    ('848e02d6-c0ac-5eac-a34e-3ebc6917a3c9'::uuid, 'b38e8d52-168a-53bd-a6ac-58339b4103ff'::uuid, 'Un prix passe de 80 à 92 euros. Quel est le taux d’évolution ?', 'mcq', '["+12 %","+15 %","+13 %","+20 %"]'::jsonb, 1, '(92 − 80) / 80 = 12 / 80 = 0,15.', 4),
    ('847c2b53-29b1-51f3-b3ae-2a477e4459e9'::uuid, 'b38e8d52-168a-53bd-a6ac-58339b4103ff'::uuid, 'Une hausse de 10 % suivie d’une hausse de 10 % équivaut à…', 'mcq', '["+20 %","+11 %","+100 %","+21 %"]'::jsonb, 3, '1,1 × 1,1 = 1,21.', 5),
    ('476cacbf-aba8-5b9c-bdc8-3bbbb17cbb9a'::uuid, 'b38e8d52-168a-53bd-a6ac-58339b4103ff'::uuid, 'Une hausse de 50 % suivie d’une baisse de 50 % ramène au prix de départ.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '1,5 × 0,5 = 0,75 : c’est une baisse de 25 %.', 6),
    ('4b085b42-716c-5ea6-96e6-5549adc6766d'::uuid, 'b38e8d52-168a-53bd-a6ac-58339b4103ff'::uuid, 'Quelle évolution annule une hausse de 25 % ?', 'mcq', '["−25 %","−75 %","−20 %","−15 %"]'::jsonb, 2, 'Le coefficient réciproque vaut 1 / 1,25 = 0,8.', 7),
    ('8e57ba81-8bc7-531b-a5d9-b29acf3a6183'::uuid, 'b38e8d52-168a-53bd-a6ac-58339b4103ff'::uuid, 'Après une baisse de 50 %, quelle hausse ramène à la valeur de départ ?', 'mcq', '["+100 %","+50 %","+150 %","+200 %"]'::jsonb, 0, 'Coefficient réciproque : 1 / 0,5 = 2.', 8),
    ('14191627-5cca-5413-b639-533e50fbfa1f'::uuid, 'b38e8d52-168a-53bd-a6ac-58339b4103ff'::uuid, 'Une hausse de 20 % puis une baisse de 20 % donnent…', 'mcq', '["aucune évolution","une hausse de 4 %","une baisse de 40 %","une baisse de 4 %"]'::jsonb, 3, '1,2 × 0,8 = 0,96.', 9),
    ('045c3969-c63f-57fc-bc27-c842a252995c'::uuid, 'b38e8d52-168a-53bd-a6ac-58339b4103ff'::uuid, 'Un effectif passe de 50 à 40. Quel est le taux d’évolution ?', 'mcq', '["−10 %","−20 %","−25 %","+20 %"]'::jsonb, 1, '(40 − 50) / 50 = −0,2.', 10),
    ('ae70c017-cb2a-5d8f-8df0-daaf2109284c'::uuid, 'b38e8d52-168a-53bd-a6ac-58339b4103ff'::uuid, 'Un taux passe de 10 % à 12 %. De combien a-t-il augmenté ?', 'mcq', '["De 2 %","De 12 %","De 2 points, soit 20 %","De 20 points"]'::jsonb, 2, 'L’écart est de 2 points ; rapporté à 10, il représente une hausse de 20 %.', 11),
