    ('255c11c5-4453-5f03-94be-8b44f79ec763'::uuid, '81fef847-d713-541f-9651-db60626406cf'::uuid, 'Combien vaut (2/3) / (4/9) ?', 'mcq', '["8/27","2/3","6/12","3/2"]'::jsonb, 3, 'Diviser, c’est multiplier par l’inverse : 2/3 × 9/4 = 18/12 = 3/2.', 2),
    ('50ec9fe2-c2d9-509a-8b14-f2ada22b25c0'::uuid, '81fef847-d713-541f-9651-db60626406cf'::uuid, 'Combien vaut 10³ × 10 puissance (−5) ?', 'mcq', '["10 puissance (−15)","10 puissance 8","10 puissance (−2)","10 puissance 2"]'::jsonb, 2, 'On additionne les exposants : 3 + (−5) = −2.', 3),
    ('ea528b51-cf47-5f0e-93bf-21f944cde0af'::uuid, '81fef847-d713-541f-9651-db60626406cf'::uuid, 'Quel est le développement de (x − 3)² ?', 'mcq', '["x² − 9","x² − 6x + 9","x² + 9","x² − 3x + 9"]'::jsonb, 1, 'Identité (a − b)² = a² − 2ab + b².', 4),
    ('d052ee3d-3d40-53c4-92f5-afee0144c284'::uuid, '81fef847-d713-541f-9651-db60626406cf'::uuid, 'Quelle est la factorisation de x² − 25 ?', 'mcq', '["(x − 5)²","(x − 25)(x + 1)","x (x − 25)","(x − 5)(x + 5)"]'::jsonb, 3, 'Identité a² − b² = (a − b)(a + b).', 5),
