    ('8b616c85-4049-5bf1-b950-0552293e38f3'::uuid, '81fef847-d713-541f-9651-db60626406cf'::uuid, 'Quelle est la solution de 3 / x = 6 ?', 'mcq', '["x = 2","x = 18","x = 1/2","x = 3"]'::jsonb, 2, 'x = 3 / 6 = 1/2.', 7),
    ('dddeeb7f-1f39-5744-b4b2-5cbab1b06e9c'::uuid, '81fef847-d713-541f-9651-db60626406cf'::uuid, 'Quelles sont les solutions de (2x − 1)(x + 3) = 0 ?', 'mcq', '["1/2 et −3","−1/2 et 3","1 et 3","2 et −3"]'::jsonb, 0, 'Un produit est nul si l’un de ses facteurs est nul.', 8),
