    ('e21a6eb6-23fb-5c0c-9dd7-d74c1edd0902'::uuid, '81fef847-d713-541f-9651-db60626406cf'::uuid, '−(a − b) est égal à b − a.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le signe moins change le signe de chaque terme : −a + b.', 11),
    ('c33fbc82-c2b0-5298-a0cf-c027d1e9c364'::uuid, '81fef847-d713-541f-9651-db60626406cf'::uuid, 'Quelle est la factorisation de 3x² + 6x ?', 'mcq', '["3 (x² + 6x)","x (3x + 2)","3x (x + 6)","3x (x + 2)"]'::jsonb, 3, 'Le facteur commun est 3x ; on vérifie en redéveloppant.', 12),
    ('5ffec39d-796c-50ba-b754-30fa06076325'::uuid, 'a8bc1fff-dcc3-5cf3-b5e9-e51b65da88ad'::uuid, 'Le point A(2 ; 5) appartient-il à la droite d’équation y = 3x − 1 ?', 'mcq', '["Oui","Non","On ne peut pas savoir","Seulement si x = 5"]'::jsonb, 0, '3 × 2 − 1 = 5 : les coordonnées vérifient l’équation.', 1),
    ('7369b593-bf83-522a-93d2-0be3623a04c5'::uuid, 'a8bc1fff-dcc3-5cf3-b5e9-e51b65da88ad'::uuid, 'Quel est le coefficient directeur de la droite passant par A(1 ; 2) et B(3 ; 8) ?', 'mcq', '["2","6","1/3","3"]'::jsonb, 3, 'm = (8 − 2) / (3 − 1) = 6 / 2 = 3.', 2),
    ('a4b369c0-e51e-5372-9167-d8dddcd16809'::uuid, 'a8bc1fff-dcc3-5cf3-b5e9-e51b65da88ad'::uuid, 'Quelle est l’équation de la droite passant par A(1 ; 2) et B(3 ; 8) ?', 'mcq', '["y = 3x + 2","y = 2x + 1","y = 3x − 1","y = 6x − 4"]'::jsonb, 2, 'm = 3, puis p = 2 − 3 × 1 = −1.', 3),
    ('9ce2a9ea-0416-5848-a1b4-e75700df0350'::uuid, 'a8bc1fff-dcc3-5cf3-b5e9-e51b65da88ad'::uuid, 'La fonction f(x) = −2x + 4 est…', 'mcq', '["linéaire et croissante","affine et décroissante","affine et croissante","constante"]'::jsonb, 1, 'Son coefficient directeur −2 est négatif.', 4),
    ('6f9a8581-5aae-5316-a9be-9fbea07c5fc9'::uuid, 'a8bc1fff-dcc3-5cf3-b5e9-e51b65da88ad'::uuid, 'La courbe d’une fonction linéaire passe toujours par l’origine du repère.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'f(0) = m × 0 = 0.', 5),
    ('df46235f-4eb4-5c13-8d7a-3f60a9f00d60'::uuid, 'a8bc1fff-dcc3-5cf3-b5e9-e51b65da88ad'::uuid, 'Si f(3) = 7, alors…', 'mcq', '["7 est l’image de 3","3 est l’image de 7","7 est un antécédent de 3","f(7) = 3"]'::jsonb, 0, 'L’image se lit en ordonnée, à partir de l’abscisse 3.', 6),
    ('e4366931-bcc0-564b-9c22-e344dfea06ba'::uuid, 'a8bc1fff-dcc3-5cf3-b5e9-e51b65da88ad'::uuid, 'Un nombre peut avoir plusieurs antécédents par une fonction.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Une droite horizontale peut couper la courbe en plusieurs points ; en revanche, chaque nombre a une seule image.', 7),
    ('793fc4ac-f119-53a7-b96e-3ec91ed1c708'::uuid, 'a8bc1fff-dcc3-5cf3-b5e9-e51b65da88ad'::uuid, 'Quelle est l’ordonnée à l’origine de la droite y = −x + 2 ?', 'mcq', '["2","−1","−2","1"]'::jsonb, 0, 'C’est p, la valeur de y pour x = 0.', 8),
    ('d9437d94-1619-56c3-a0e8-a71e85d22c4d'::uuid, 'a8bc1fff-dcc3-5cf3-b5e9-e51b65da88ad'::uuid, 'Pour quelle valeur de x la fonction 2x − 6 s’annule-t-elle ?', 'mcq', '["x = −3","x = 6","x = 2","x = 3"]'::jsonb, 3, '2x − 6 = 0 donne x = 3.', 9),
    ('8a6a521d-bea1-5bb2-aff0-13578980061c'::uuid, 'a8bc1fff-dcc3-5cf3-b5e9-e51b65da88ad'::uuid, 'Pour quelles valeurs de x l’expression −2x + 4 est-elle positive ?', 'mcq', '["x > 2","x < 2","x < −2","x > 4"]'::jsonb, 1, 'Elle s’annule en 2 et, avec un coefficient négatif, elle est positive à gauche.', 10),
    ('1ad12f89-d4c2-545a-9fc8-aeef92297c24'::uuid, 'a8bc1fff-dcc3-5cf3-b5e9-e51b65da88ad'::uuid, 'Sur un graphique, comment résout-on f(x) > k ?', 'mcq', '["On lit les ordonnées des points au-dessus de l’axe","On calcule f(k)","On cherche les abscisses des points de la courbe au-dessus de la droite y = k","On cherche où la courbe coupe l’axe des ordonnées"]'::jsonb, 2, 'La réponse est un ensemble d’ABSCISSES, souvent un intervalle.', 11),
    ('e95c8360-c988-5dd3-a47f-ef49bff502c3'::uuid, 'a8bc1fff-dcc3-5cf3-b5e9-e51b65da88ad'::uuid, 'Pour tracer y = 3x − 1, on peut placer le point (0 ; −1) puis…', 'mcq', '["avancer de 3 et monter de 1","avancer de 1 et descendre de 3","monter de 1","avancer de 1 et monter de 3"]'::jsonb, 3, 'Le coefficient directeur 3 dit de combien on monte pour une unité en abscisse.', 12),
    ('bafb6ab0-1f9f-53ba-a1b3-49e3e8c16c37'::uuid, '1b9817ac-e8ed-5d28-ba1b-8d375306cdfa'::uuid, 'Quelle est la médiane de la série 3 ; 5 ; 7 ; 8 ; 10 ; 12 ; 15 ?', 'mcq', '["8","7","8,6","10"]'::jsonb, 0, 'Avec 7 valeurs rangées, la médiane est la 4e.', 1),
    ('480b60e4-a651-5975-ade6-e7b2fdcbfe05'::uuid, '1b9817ac-e8ed-5d28-ba1b-8d375306cdfa'::uuid, 'Quel est le premier quartile de cette série ?', 'mcq', '["3","6","7","5"]'::jsonb, 3, '7 / 4 = 1,75 : on prend la valeur de rang 2.', 2),
    ('b02fc43f-542d-52b4-b218-12cbeb97e0fa'::uuid, '1b9817ac-e8ed-5d28-ba1b-8d375306cdfa'::uuid, 'Une note de 12 coefficient 2 et une note de 15 coefficient 1 donnent une moyenne de…', 'mcq', '["13,5","14","13","12,5"]'::jsonb, 2, '(12 × 2 + 15) / 3 = 39 / 3 = 13.', 3),
    ('37e1f7ea-346b-50e7-9e63-4b8c009220b6'::uuid, '1b9817ac-e8ed-5d28-ba1b-8d375306cdfa'::uuid, 'Quel est l’écart interquartile d’une série de Q1 = 5 et Q3 = 12 ?', 'mcq', '["17","7","8,5","12"]'::jsonb, 1, 'Écart interquartile = Q3 − Q1.', 4),
    ('c87b66e5-fb8b-5a85-ad93-f155bd293175'::uuid, '1b9817ac-e8ed-5d28-ba1b-8d375306cdfa'::uuid, 'Remplacer la plus grande valeur d’une série par une valeur bien plus grande change sa médiane.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La médiane dépend du rang des valeurs, pas de leur grandeur : elle résiste aux extrêmes.', 5),
    ('2f3fe713-0d35-5bf3-8cc5-4ec3837ea8d8'::uuid, '1b9817ac-e8ed-5d28-ba1b-8d375306cdfa'::uuid, 'Dans un diagramme circulaire, quel angle représente une part de 25 % ?', 'mcq', '["90°","25°","45°","180°"]'::jsonb, 0, '0,25 × 360° = 90°.', 6),
    ('a79b6426-ceb8-58e6-97d7-8c920ee45f3c'::uuid, '1b9817ac-e8ed-5d28-ba1b-8d375306cdfa'::uuid, 'Quel graphique est le plus adapté pour comparer la dispersion de deux séries ?', 'mcq', '["Le diagramme circulaire","Le diagramme en barres","La boîte à moustaches","Le nuage de points"]'::jsonb, 2, 'Deux boîtes côte à côte montrent médianes, quartiles et étendues.', 7),
    ('f8688237-d257-59e0-888b-14e6c75d414d'::uuid, '1b9817ac-e8ed-5d28-ba1b-8d375306cdfa'::uuid, 'Si P(A) = 0,3, que vaut P(non A) ?', 'mcq', '["0,7","0,3","1,3","0"]'::jsonb, 0, 'P(non A) = 1 − P(A).', 8),
    ('c3912151-1585-5cef-befc-8930ef43bffb'::uuid, '1b9817ac-e8ed-5d28-ba1b-8d375306cdfa'::uuid, 'Avec un dé équilibré, quelle est la probabilité d’obtenir un nombre pair ?', 'mcq', '["1/3","1/6","2/3","1/2"]'::jsonb, 3, 'Trois issues favorables (2, 4, 6) sur six.', 9),
    ('e4cb7b3b-da47-587c-a6a4-cd18139202b3'::uuid, '1b9817ac-e8ed-5d28-ba1b-8d375306cdfa'::uuid, 'Dans le tableau croisé du cours, que vaut P(F inter L) ?', 'mcq', '["0,375","0,225","0,75","0,3"]'::jsonb, 1, 'Filles latinistes parmi TOUS les élèves : 45 / 200.', 10),
    ('f9b7c0c8-db95-5627-9ccf-0676475347c7'::uuid, '1b9817ac-e8ed-5d28-ba1b-8d375306cdfa'::uuid, 'Dans le même tableau, que vaut la probabilité qu’un élève soit latiniste sachant que c’est une fille ?', 'mcq', '["45 / 200","45 / 60","45 / 120","60 / 200"]'::jsonb, 2, 'On se restreint aux 120 filles.', 11),
    ('368a12e9-8235-5814-a9d7-2db74c915de6'::uuid, '1b9817ac-e8ed-5d28-ba1b-8d375306cdfa'::uuid, 'Dans le même tableau, que vaut la probabilité qu’un élève soit une fille sachant qu’il est latiniste ?', 'mcq', '["0,375","0,6","0,225","0,75"]'::jsonb, 3, 'On se restreint aux 60 latinistes : 45 / 60.', 12),
    ('ea5f39b9-ac23-50a4-85ad-f553f0d9b650'::uuid, '8d1447e8-4d72-510d-b8b3-0c6d79c5a0ed'::uuid, 'Combien de temps dure l’épreuve anticipée de mathématiques ?', 'mcq', '["2 heures","1 heure","3 heures","4 heures"]'::jsonb, 0, 'Deux heures pour les deux parties.', 1),
    ('e0b800fd-c75d-578a-b46b-ba2ae90fc9da'::uuid, '8d1447e8-4d72-510d-b8b3-0c6d79c5a0ed'::uuid, 'La calculatrice est autorisée pendant la partie exercices.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est interdite pendant TOUTE l’épreuve.', 2),
    ('bcea08d8-0096-5e79-8c7b-dc3338a66435'::uuid, '8d1447e8-4d72-510d-b8b3-0c6d79c5a0ed'::uuid, 'Sur combien de points est notée la partie automatismes ?', 'mcq', '["4","10","6","14"]'::jsonb, 2, 'Automatismes 6 points, exercices 14 points.', 3),
    ('c626db8a-2d68-5e15-b9fa-e052864f8829'::uuid, '8d1447e8-4d72-510d-b8b3-0c6d79c5a0ed'::uuid, 'Sur combien de points est notée la partie exercices ?', 'mcq', '["6","14","10","20"]'::jsonb, 1, 'Deux ou trois exercices indépendants pour 14 points.', 4),
    ('a2122684-9a95-5869-b3f4-46b4d2447505'::uuid, '8d1447e8-4d72-510d-b8b3-0c6d79c5a0ed'::uuid, 'Quel est le coefficient de l’épreuve anticipée de mathématiques au baccalauréat ?', 'mcq', '["1","5","16","2"]'::jsonb, 3, 'Elle est notée sur 20 avec un coefficient 2.', 5),
    ('f2322971-82dc-5dac-b670-6618840b9d01'::uuid, '8d1447e8-4d72-510d-b8b3-0c6d79c5a0ed'::uuid, 'Qui passe l’épreuve anticipée de mathématiques ?', 'mcq', '["Tous les élèves de Première des voies générale et technologique","Seulement les élèves de spécialité mathématiques","Seulement la voie technologique","Seulement les volontaires"]'::jsonb, 0, 'Tous les élèves de Première, avec un sujet adapté à leur parcours.', 6),
    ('3467f126-b0ee-5662-b688-51fe8abf83a9'::uuid, '8d1447e8-4d72-510d-b8b3-0c6d79c5a0ed'::uuid, 'Tous les élèves reçoivent exactement le même sujet.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le sujet dépend du parcours : spécialité, enseignement de mathématiques sans spécialité, ou voie technologique.', 7),
    ('ebe94598-7f6d-5e9a-8f2c-5c20095bb3d4'::uuid, '8d1447e8-4d72-510d-b8b3-0c6d79c5a0ed'::uuid, 'Les automatismes peuvent porter sur des notions de Seconde.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La liste officielle en comprend : statistiques, proportions, évolutions.', 8),
    ('b299692e-8609-58ab-ad3b-b3dc5861bec0'::uuid, '8d1447e8-4d72-510d-b8b3-0c6d79c5a0ed'::uuid, 'Que faire quand une question d’exercice résiste ?', 'mcq', '["Abandonner l’exercice","Recommencer tout l’exercice","Passer à la partie automatismes","Admettre son résultat et continuer"]'::jsonb, 3, 'Les résultats intermédiaires sont souvent donnés : on s’en sert pour la suite.', 9),
    ('cc40b6ea-b19f-57e7-a4d7-32a37f803748'::uuid, '8d1447e8-4d72-510d-b8b3-0c6d79c5a0ed'::uuid, 'Un prix après une baisse est calculé plus élevé qu’avant. Que faire ?', 'mcq', '["Le garder","Vérifier le calcul : le résultat n’est pas vraisemblable","L’arrondir","Changer d’unité"]'::jsonb, 1, 'Le contrôle de vraisemblance attrape les erreurs de coefficient.', 10),
    ('66a6b786-62fa-5080-b339-0241edd8030a'::uuid, '8d1447e8-4d72-510d-b8b3-0c6d79c5a0ed'::uuid, 'Combien d’exercices compte la seconde partie ?', 'mcq', '["Un seul","Cinq","Deux ou trois","Dix"]'::jsonb, 2, 'Deux ou trois exercices indépendants.', 11),
    ('4e518fec-7d64-5a8d-98e2-52531e2e2190'::uuid, '8d1447e8-4d72-510d-b8b3-0c6d79c5a0ed'::uuid, 'Quelle préparation est la plus efficace pour les automatismes ?', 'mcq', '["Une révision intensive la veille","Apprendre les corrigés par cœur","S’entraîner uniquement avec la calculatrice","Un entraînement court et régulier, sans calculatrice"]'::jsonb, 3, 'Ce sont des réflexes : ils s’installent par la répétition, jour après jour.', 12),
    ('fe444e51-2a02-5bed-aada-2229657a4fbf'::uuid, 'a073ffc8-64af-5f5c-8395-00308f6187c4'::uuid, 'ABC est rectangle en A. Quelle égalité est vraie ?', 'mcq', '["AB² = AC² + BC²","AC² = AB² + BC²","BC² = AB² + AC²","BC = AB + AC"]'::jsonb, 2, 'Le côté opposé à l’angle droit, ici [BC], est l’hypoténuse : c’est son carré qui vaut la somme des deux autres.', 1),
    ('a24d1eba-dd63-59af-9821-af71cb53291d'::uuid, 'a073ffc8-64af-5f5c-8395-00308f6187c4'::uuid, 'ABC est rectangle en A avec AB = 6 cm et AC = 8 cm. Combien mesure BC ?', 'mcq', '["14 cm","10 cm","48 cm","√14 cm"]'::jsonb, 1, 'BC² = 36 + 64 = 100, donc BC = √100 = 10 cm.', 2),
    ('590a25d7-4058-5549-a47d-9eb13499368f'::uuid, 'a073ffc8-64af-5f5c-8395-00308f6187c4'::uuid, 'Dans un triangle rectangle, l’hypoténuse mesure 13 cm et un côté 5 cm. Combien mesure le troisième côté ?', 'mcq', '["8 cm","√194 cm","12 cm","18 cm"]'::jsonb, 2, 'Pour un côté de l’angle droit, on soustrait : 169 − 25 = 144, et √144 = 12.', 3),
    ('d67d757c-99c6-559a-83ea-d301ed03c708'::uuid, 'a073ffc8-64af-5f5c-8395-00308f6187c4'::uuid, 'À quoi sert la réciproque du théorème de Pythagore ?', 'mcq', '["À calculer une longueur","À calculer un angle","À prouver que deux droites sont parallèles","À prouver qu’un triangle est rectangle"]'::jsonb, 3, 'Si le carré du plus long côté égale la somme des carrés des deux autres, le triangle est rectangle.', 4),
    ('89ccf1e3-71a7-5f87-b596-a5cf35e88f02'::uuid, 'a073ffc8-64af-5f5c-8395-00308f6187c4'::uuid, 'Un triangle a pour côtés 7,5 cm, 10 cm et 12,5 cm. Est-il rectangle ?', 'mcq', '["Non, car 7,5 + 10 est différent de 12,5","Oui, car 12,5² = 7,5² + 10² = 156,25","Oui, car tous ses côtés sont des décimaux","On ne peut pas le savoir sans rapporteur"]'::jsonb, 1, 'On compare 12,5² = 156,25 et 56,25 + 100 = 156,25 : l’égalité est vérifiée.', 5),
    ('76bf5129-8e71-52f4-9650-1a7403a54923'::uuid, 'a073ffc8-64af-5f5c-8395-00308f6187c4'::uuid, 'Un triangle a pour côtés 5, 6 et 8 : 8² = 64 mais 5² + 6² = 61. Quelle propriété permet de conclure qu’il n’est pas rectangle ?', 'mcq', '["La réciproque de Pythagore","La contraposée de Pythagore","Le théorème de Thalès","La trigonométrie"]'::jsonb, 1, 'Quand l’égalité n’est pas vérifiée, c’est la contraposée qui prouve que le triangle n’est pas rectangle.', 6),
    ('c0a6670b-cb6f-5bc5-b9bb-b9783b954323'::uuid, 'a073ffc8-64af-5f5c-8395-00308f6187c4'::uuid, 'Pour tester si un triangle est rectangle, on compare le carré du plus long côté à la somme des carrés des deux autres.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Seul le plus long côté peut être l’hypoténuse : c’est lui qu’on isole.', 7),
    ('16a28a81-7113-55a2-a370-374fb7a448c4'::uuid, 'a073ffc8-64af-5f5c-8395-00308f6187c4'::uuid, 'Un pavé droit mesure 3 cm × 4 cm × 12 cm. Combien mesure sa grande diagonale ?', 'mcq', '["19 cm","12 cm","13 cm","15 cm"]'::jsonb, 2, 'La diagonale de la base vaut 5 cm (3, 4, 5), puis 5² + 12² = 169, soit 13 cm.', 8),
    ('8a9012a6-8f0a-50a7-9494-c744c657fda2'::uuid, 'a073ffc8-64af-5f5c-8395-00308f6187c4'::uuid, 'Quelle est la longueur de la diagonale d’un carré de côté 5 cm ?', 'mcq', '["10 cm","25 cm","6,5 cm environ","7,07 cm environ"]'::jsonb, 3, 'd² = 5² + 5² = 50, donc d = √50 ≈ 7,07 cm.', 9),
    ('2d7cf4f4-6d3c-5802-970b-f93e52db1ceb'::uuid, 'a073ffc8-64af-5f5c-8395-00308f6187c4'::uuid, 'Une échelle de 5 m est posée contre un mur vertical, son pied à 1,4 m du mur. À quelle hauteur touche-t-elle le mur ?', 'mcq', '["4,8 m","3,6 m","5,2 m","6,4 m"]'::jsonb, 0, 'L’échelle est l’hypoténuse : h² = 25 − 1,96 = 23,04, donc h = 4,8 m.', 10),
    ('1ff9f730-5ca9-5c8f-9c11-03f7a5943df1'::uuid, 'a073ffc8-64af-5f5c-8395-00308f6187c4'::uuid, 'Le théorème de Pythagore s’applique à tous les triangles.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il exige un triangle rectangle : c’est l’hypothèse à écrire avant tout calcul.', 11),
    ('394873a9-a193-50af-8ca9-64066e141e20'::uuid, 'a073ffc8-64af-5f5c-8395-00308f6187c4'::uuid, 'Lequel de ces triplets correspond aux côtés d’un triangle rectangle ?', 'mcq', '["6, 8, 11","4, 5, 6","5, 11, 13","8, 15, 17"]'::jsonb, 3, '8² + 15² = 64 + 225 = 289 = 17².', 12),
    ('d28c7eba-9259-517e-8988-86b5da8bd572'::uuid, 'cec35aab-871a-517e-ac14-531bf3617dd8'::uuid, 'Quelle transformation fait glisser une figure sans la tourner ni la retourner ?', 'mcq', '["La symétrie axiale","La translation","La rotation de 90°","La symétrie centrale"]'::jsonb, 1, 'La translation est un glissement : direction, sens et longueur fixés.', 1),
    ('b98b65c6-8e3a-533e-a9f9-c3ed89a9bbed'::uuid, 'cec35aab-871a-517e-ac14-531bf3617dd8'::uuid, 'À quelle transformation correspond une rotation de 180° ?', 'mcq', '["Une symétrie axiale","Une translation","Une symétrie centrale","Une homothétie de rapport 2"]'::jsonb, 2, 'Un demi-tour autour de O : c’est la symétrie de centre O.', 2),
    ('fabdc222-8cac-56c1-85d6-068cc224342c'::uuid, 'cec35aab-871a-517e-ac14-531bf3617dd8'::uuid, 'Laquelle de ces transformations retourne la figure, comme un miroir ?', 'mcq', '["La symétrie axiale","La translation","La rotation","La symétrie centrale"]'::jsonb, 0, 'Seule la symétrie axiale inverse l’orientation de la figure.', 3),
    ('a68db8e0-626c-5b98-9197-74d35ec6a01e'::uuid, 'cec35aab-871a-517e-ac14-531bf3617dd8'::uuid, 'M′ est l’image de M par la symétrie de centre O. Que peut-on dire de O ?', 'mcq', '["O est sur la médiatrice de [MM′] seulement","O est le milieu de [MM′]","O est confondu avec M","OM′ = 2 × OM"]'::jsonb, 1, 'Dans une symétrie centrale, le centre est le milieu du segment qui joint un point à son image.', 4),
    ('93f24b8e-038d-5429-9ff2-b84757439660'::uuid, 'cec35aab-871a-517e-ac14-531bf3617dd8'::uuid, 'La translation qui transforme A en B transforme C en D. Quelle figure est un parallélogramme ?', 'mcq', '["ABCD","ACBD","ABDC","ADBC"]'::jsonb, 2, 'Les segments [AB] et [CD] sont parallèles, de même longueur et de même sens : ABDC est un parallélogramme.', 5),
    ('937a9668-adf4-58c1-82cf-970ec2bd3262'::uuid, 'cec35aab-871a-517e-ac14-531bf3617dd8'::uuid, 'Qu’est-ce qu’une rotation ne conserve PAS en général ?', 'mcq', '["Les longueurs","Les angles","Les aires","La direction des droites"]'::jsonb, 3, 'Une rotation fait tourner les droites : leur direction change, sauf pour un angle de 180°.', 6),
    ('492112b9-040c-5608-95c3-99d7a26c8d13'::uuid, 'cec35aab-871a-517e-ac14-531bf3617dd8'::uuid, 'Comment obtient-on une frise ?', 'mcq', '["En répétant un motif par translation dans une seule direction","En agrandissant un motif","En faisant tourner un motif autour d’un point","En coloriant un pavage"]'::jsonb, 0, 'Une frise est une bande : le motif se répète par translation dans une direction.', 7),
    ('0d31aded-3192-512b-b0e1-546131a94662'::uuid, 'cec35aab-871a-517e-ac14-531bf3617dd8'::uuid, 'Quel est le plus petit angle de rotation qui laisse un hexagone régulier invariant autour de son centre ?', 'mcq', '["30°","45°","60°","120°"]'::jsonb, 2, '360° ÷ 6 = 60° : chaque sommet vient sur le suivant.', 8),
    ('e6e30df0-ab5a-57c5-9081-baf4da3c0fd0'::uuid, 'cec35aab-871a-517e-ac14-531bf3617dd8'::uuid, 'M′ est l’image de M par une symétrie axiale. Qu’est l’axe pour le segment [MM′] ?', 'mcq', '["Sa médiane","Sa médiatrice","Une droite parallèle","Sa diagonale"]'::jsonb, 1, 'L’axe coupe [MM′] en son milieu, perpendiculairement : c’est sa médiatrice.', 9),
    ('468f4f61-f883-54c8-b934-09bfb6aa6443'::uuid, 'cec35aab-871a-517e-ac14-531bf3617dd8'::uuid, 'Une symétrie, une translation ou une rotation conserve les aires.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ce sont des isométries : la figure image est superposable, donc de même aire.', 10),
    ('e12e6f86-3b65-5821-8f22-aadd0fc090b0'::uuid, 'cec35aab-871a-517e-ac14-531bf3617dd8'::uuid, 'M′ est l’image de M par la rotation de centre O et d’angle 90°. Que sait-on ?', 'mcq', '["OM′ = 2 × OM","M, O et M′ sont alignés","O est le milieu de [MM′]","OM′ = OM et l’angle MOM′ mesure 90°"]'::jsonb, 3, 'Une rotation conserve la distance au centre et fait tourner de l’angle donné.', 11),
    ('f645a489-0e7c-5ecb-a5f1-1ce77bc28836'::uuid, 'cec35aab-871a-517e-ac14-531bf3617dd8'::uuid, 'Une homothétie de rapport 2 conserve les longueurs.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle les multiplie par 2 : ce n’est pas une isométrie.', 12),
    ('90bfa701-3914-581f-91df-aabfd66875a5'::uuid, '39fd5245-b833-52c7-88f5-d58db207e762'::uuid, 'Quel script trace un carré de côté 50 ?', 'mcq', '["Répéter 4 fois : avancer de 50, tourner de 90°","Répéter 4 fois : avancer de 50, tourner de 45°","Répéter 2 fois : avancer de 50, tourner de 90°","Avancer de 200, tourner de 90°"]'::jsonb, 0, 'Quatre côtés, et un quart de tour après chacun.', 1),
    ('79676647-30e6-5b2c-98c1-c299daef7cbd'::uuid, '39fd5245-b833-52c7-88f5-d58db207e762'::uuid, 'Pour tracer un triangle équilatéral, de combien le lutin doit-il tourner après chaque côté ?', 'mcq', '["60°","120°","180°","90°"]'::jsonb, 1, 'Il tourne de l’angle extérieur : 180° − 60° = 120°, soit 360° ÷ 3.', 2),
    ('6c487398-3318-5424-b332-5dc7087736a6'::uuid, '39fd5245-b833-52c7-88f5-d58db207e762'::uuid, 'Pour tracer un hexagone régulier, de combien le lutin tourne-t-il à chaque sommet ?', 'mcq', '["120°","30°","90°","60°"]'::jsonb, 3, '360° ÷ 6 = 60°.', 3),
    ('f4d67b09-fe17-575c-99e9-1ca3d4981b0f'::uuid, '39fd5245-b833-52c7-88f5-d58db207e762'::uuid, 'On met x à 3, puis on répète 4 fois « ajouter 2 à x ». Que vaut x à la fin ?', 'mcq', '["9","11","12","8"]'::jsonb, 1, '3 + 4 × 2 = 11 : un tableau tour par tour évite l’erreur.', 4),
    ('5286eaa0-24ec-5427-ae4b-8782190aac6d'::uuid, '39fd5245-b833-52c7-88f5-d58db207e762'::uuid, 'Qu’est-ce qu’une variable en programmation ?', 'mcq', '["Un bloc qui fait bouger le lutin","Une boucle infinie","Une case mémoire nommée dont la valeur peut changer","Un message envoyé à un autre lutin"]'::jsonb, 2, 'On la crée, on lui donne une valeur, puis on la modifie au fil du programme.', 5),
    ('e5d6140f-d12b-5e64-affa-69120ee070eb'::uuid, '39fd5245-b833-52c7-88f5-d58db207e762'::uuid, 'Comment s’appelle le bloc « si … alors … sinon » ?', 'mcq', '["Une boucle","Une instruction conditionnelle","Un événement","Une variable"]'::jsonb, 1, 'Il teste une condition et choisit entre deux suites d’instructions.', 6),
    ('ea5e467e-8039-535b-b08a-ec7c6697d1be'::uuid, '39fd5245-b833-52c7-88f5-d58db207e762'::uuid, 'Quel est l’intérêt d’un bloc personnalisé ?', 'mcq', '["Réutiliser une suite d’instructions, avec des paramètres","Accélérer l’ordinateur","Changer le costume du lutin","Effacer la scène"]'::jsonb, 0, 'On écrit « carré » une fois, on l’appelle partout : le script est plus court et plus lisible.', 7),
    ('bfdf5ca5-040c-5002-8f8f-c4d81c3a37c6'::uuid, '39fd5245-b833-52c7-88f5-d58db207e762'::uuid, 'Dans Scratch, vers où pointe un lutin orienté à 90 ?', 'mcq', '["Vers le haut","Vers le bas","Vers la gauche","Vers la droite"]'::jsonb, 3, 'L’orientation 0 est vers le haut, 90 vers la droite.', 8),
    ('e40af81c-eca3-5e0f-bef9-aaea6b129152'::uuid, '39fd5245-b833-52c7-88f5-d58db207e762'::uuid, 'Quelles sont les coordonnées du centre de la scène de Scratch ?', 'mcq', '["(240 ; 180)","(0 ; 0)","(−240 ; −180)","(100 ; 100)"]'::jsonb, 1, 'Les abscisses vont de −240 à 240, les ordonnées de −180 à 180 : le centre est l’origine.', 9),
    ('79b8a427-4923-58e9-af8e-c9f612611d2c'::uuid, '39fd5245-b833-52c7-88f5-d58db207e762'::uuid, 'Quand la boucle « répéter jusqu’à » s’arrête-t-elle ?', 'mcq', '["Après 10 tours","Quand sa condition devient fausse","Quand sa condition devient vraie","Jamais"]'::jsonb, 2, 'Elle répète TANT QUE la condition n’est pas remplie, et s’arrête dès qu’elle l’est.', 10),
    ('fda5bc77-c9c9-5b5c-9c0c-2c231a67e48e'::uuid, '39fd5245-b833-52c7-88f5-d58db207e762'::uuid, 'On met n à 5 ; si n > 3 alors le lutin dit « grand », sinon « petit ». Que dit-il ?', 'mcq', '["Petit","Rien","5","Grand"]'::jsonb, 3, 'Le test 5 > 3 est vrai : c’est la branche « alors » qui s’exécute.', 11),
    ('487d56ee-14fa-53e6-a801-f1a15b4621bf'::uuid, '39fd5245-b833-52c7-88f5-d58db207e762'::uuid, 'Un bloc placé juste APRÈS une boucle « répéter 10 fois » est exécuté 10 fois.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Seuls les blocs placés À L’INTÉRIEUR de la boucle sont répétés.', 12),
    ('1861e8cd-8acf-5f57-bb0f-6cd87d886539'::uuid, 'e51b1110-69b1-57f6-867c-77e0e368e8f3'::uuid, 'Combien vaut 30 % de 250 ?', 'mcq', '["83,3","7,5","75","220"]'::jsonb, 2, '250 × 0,3 = 75.', 1),
    ('af95f487-d87a-57d3-ba64-1e86eefd24a7'::uuid, 'e51b1110-69b1-57f6-867c-77e0e368e8f3'::uuid, 'Une classe compte 18 filles sur 24 élèves. Quel pourcentage de filles ?', 'mcq', '["18 %","75 %","66 %","133 %"]'::jsonb, 1, '18 ÷ 24 = 0,75, soit 75 %.', 2),
    ('a2adf40c-d320-5b6b-82e9-628309703df2'::uuid, 'e51b1110-69b1-57f6-867c-77e0e368e8f3'::uuid, 'Un jean à 80 € est soldé à −25 %. Quel est son nouveau prix ?', 'mcq', '["55 €","60 €","64 €","100 €"]'::jsonb, 1, '80 × 0,75 = 60 €.', 3),
    ('0853b05a-5e13-5294-aab9-164c311753da'::uuid, 'e51b1110-69b1-57f6-867c-77e0e368e8f3'::uuid, 'Par quel coefficient multiplie-t-on pour une baisse de 8 % ?', 'mcq', '["0,08","1,08","0,8","0,92"]'::jsonb, 3, '1 − 0,08 = 0,92.', 4),
    ('6900d7f1-77b7-5380-847b-d16a92fba541'::uuid, 'e51b1110-69b1-57f6-867c-77e0e368e8f3'::uuid, 'Une population passe de 1 200 à 1 500 habitants. Quel est le taux d’évolution ?', 'mcq', '["+25 %","+20 %","+300 %","+30 %"]'::jsonb, 0, '(1 500 − 1 200) ÷ 1 200 = 0,25.', 5),
    ('6ddd502a-9bd0-5909-beb4-5de15903cea4'::uuid, 'e51b1110-69b1-57f6-867c-77e0e368e8f3'::uuid, 'Après une hausse de 20 %, un prix vaut 96 €. Quel était le prix de départ ?', 'mcq', '["76,80 €","76 €","115,20 €","80 €"]'::jsonb, 3, 'On divise par le coefficient : 96 ÷ 1,2 = 80 €.', 6),
    ('de4de5e8-f2df-5439-aca4-3dcbd228e4ef'::uuid, 'e51b1110-69b1-57f6-867c-77e0e368e8f3'::uuid, 'Un prix augmente de 25 %. Quelle baisse le ramène à sa valeur de départ ?', 'mcq', '["−25 %","−20 %","−30 %","−12,5 %"]'::jsonb, 1, 'Il faut multiplier par 1 ÷ 1,25 = 0,8, soit une baisse de 20 %.', 7),
    ('f794429d-e67a-5cd8-9ea7-eda73b152e5c'::uuid, 'e51b1110-69b1-57f6-867c-77e0e368e8f3'::uuid, 'Un prix passe de 50 € à 40 €. Quel est le pourcentage de baisse ?', 'mcq', '["25 %","10 %","20 %","40 %"]'::jsonb, 2, 'On divise par la valeur de départ : 10 ÷ 50 = 0,2.', 8),
    ('e170771a-a4b7-5afc-941b-4d7ab1df489e'::uuid, 'e51b1110-69b1-57f6-867c-77e0e368e8f3'::uuid, 'Une hausse de 50 % suivie d’une baisse de 50 % ramène au prix de départ.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '1,5 × 0,5 = 0,75 : le prix a baissé de 25 %.', 9),
    ('570e360d-57e2-5cea-8d7a-2a416ea7f3a3'::uuid, 'e51b1110-69b1-57f6-867c-77e0e368e8f3'::uuid, 'Comment calcule-t-on un taux d’évolution ?', 'mcq', '["(arrivée − départ) ÷ départ","(arrivée − départ) ÷ arrivée","arrivée ÷ départ","départ − arrivée"]'::jsonb, 0, 'La référence est toujours la valeur de départ.', 10),
    ('a5c3c021-111c-595c-ba99-94fbb2a6c241'::uuid, 'e51b1110-69b1-57f6-867c-77e0e368e8f3'::uuid, '60 % des élèves sont demi-pensionnaires, et 25 % d’entre eux mangent végétarien. Quelle part des élèves du collège mange végétarien ?', 'mcq', '["35 %","85 %","15 %","25 %"]'::jsonb, 2, 'Un pourcentage de pourcentage se multiplie : 0,6 × 0,25 = 0,15.', 11),
    ('841fdaac-c254-5a16-9714-ba4caf9dcfb3'::uuid, 'e51b1110-69b1-57f6-867c-77e0e368e8f3'::uuid, 'Un article coûte 120 € TTC avec une TVA de 20 %. Quel est son prix hors taxes ?', 'mcq', '["96 €","144 €","24 €","100 €"]'::jsonb, 3, 'TTC = HT × 1,2, donc HT = 120 ÷ 1,2 = 100 €.', 12),
    ('f11ee0e0-8de0-5632-a8c0-f4a7fd856366'::uuid, '1d78c0fb-1f49-5cf4-a2ac-7a8cdebf0154'::uuid, 'Une voiture parcourt 150 km en 1 h 15 min. Quelle est sa vitesse moyenne ?', 'mcq', '["130,4 km/h environ","120 km/h","115 km/h","187,5 km/h"]'::jsonb, 1, '1 h 15 = 1,25 h, et 150 ÷ 1,25 = 120 km/h.', 1),
    ('a62ea40c-ba72-53b9-91a9-ec2667472a13'::uuid, '1d78c0fb-1f49-5cf4-a2ac-7a8cdebf0154'::uuid, 'Combien vaut 72 km/h en m/s ?', 'mcq', '["20 m/s","72 000 m/s","7,2 m/s","259,2 m/s"]'::jsonb, 0, 'On divise par 3,6 : 72 ÷ 3,6 = 20.', 2),
    ('55581928-f8c6-53ae-92cd-a53c824eab1e'::uuid, '1d78c0fb-1f49-5cf4-a2ac-7a8cdebf0154'::uuid, 'Comment écrit-on 1 h 30 min en heures décimales ?', 'mcq', '["1,3 h","1,03 h","1,5 h","1,75 h"]'::jsonb, 2, '30 min = 30 ÷ 60 = 0,5 h.', 3),
    ('f6641130-a1e4-549d-bc09-235bbf2737bb'::uuid, '1d78c0fb-1f49-5cf4-a2ac-7a8cdebf0154'::uuid, 'Un scooter roule à 90 km/h pendant 40 min. Quelle distance parcourt-il ?', 'mcq', '["36 km","50 km","60 km","360 km"]'::jsonb, 2, '40 min = 2/3 h, et 90 × 2/3 = 60 km.', 4),
    ('61e482e3-34ca-5f3d-a523-6bb1544579a1'::uuid, '1d78c0fb-1f49-5cf4-a2ac-7a8cdebf0154'::uuid, 'Le fer a une masse volumique d’environ 7,8 g/cm³. Quelle est la masse d’un bloc de fer de 100 cm³ ?', 'mcq', '["78 g","780 g","7,8 g","12,8 g"]'::jsonb, 1, 'm = ρ × V = 7,8 × 100 = 780 g.', 5),
    ('1cf21949-2776-558c-9da0-c648e917254a'::uuid, '1d78c0fb-1f49-5cf4-a2ac-7a8cdebf0154'::uuid, 'Un robinet débite 12 L/min. Combien de temps faut-il pour remplir 300 L ?', 'mcq', '["36 min","3 600 min","20 min","25 min"]'::jsonb, 3, 'Durée = volume ÷ débit = 300 ÷ 12 = 25 min.', 6),
    ('efd6f43d-21a7-5de3-80e1-fae11a142bb7'::uuid, '1d78c0fb-1f49-5cf4-a2ac-7a8cdebf0154'::uuid, 'Combien de litres contient 1 m³ ?', 'mcq', '["10 L","100 L","1 000 L","1 000 000 L"]'::jsonb, 2, '1 m³ = 1 000 dm³ et 1 dm³ = 1 L.', 7),
    ('25279f5a-58ae-508a-93a3-8d57d1c1ddd8'::uuid, '1d78c0fb-1f49-5cf4-a2ac-7a8cdebf0154'::uuid, 'Un radiateur de 2 000 W fonctionne pendant 3 h. Quelle énergie consomme-t-il ?', 'mcq', '["6 kWh","6 000 kWh","667 Wh","2,003 kWh"]'::jsonb, 0, '2 kW × 3 h = 6 kWh : l’énergie est une grandeur produit.', 8),
    ('b3e671e3-a0f4-56af-9a62-59f174db1038'::uuid, '1d78c0fb-1f49-5cf4-a2ac-7a8cdebf0154'::uuid, 'Laquelle de ces grandeurs est une grandeur quotient ?', 'mcq', '["Une aire en m²","Une énergie en kWh","Une longueur en m","Une vitesse en km/h"]'::jsonb, 3, 'Une vitesse est une distance divisée par une durée.', 9),
    ('c5dedcc2-3346-5035-9c94-5176997094f3'::uuid, '1d78c0fb-1f49-5cf4-a2ac-7a8cdebf0154'::uuid, '1 g/cm³ correspond à combien de kg/m³ ?', 'mcq', '["1 kg/m³","1 000 kg/m³","100 kg/m³","0,001 kg/m³"]'::jsonb, 1, '1 m³ = 1 000 000 cm³ ; 1 000 000 g = 1 000 kg.', 10),
    ('130ebf64-4853-5e15-9a10-01bf868e68a2'::uuid, '1d78c0fb-1f49-5cf4-a2ac-7a8cdebf0154'::uuid, '0,3 h correspond à 30 minutes.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '0,3 × 60 = 18 minutes.', 11),
    ('4a193f39-65ba-5481-bb11-49191d1045ef'::uuid, '1d78c0fb-1f49-5cf4-a2ac-7a8cdebf0154'::uuid, 'Une commune de 15 km² compte 6 000 habitants. Quelle est sa densité de population ?', 'mcq', '["90 000 hab/km²","0,0025 hab/km²","400 hab/km²","600 hab/km²"]'::jsonb, 2, 'Densité = habitants ÷ superficie = 6 000 ÷ 15 = 400.', 12),
    ('ccb5f04e-0e8a-59d9-956a-2a32bb3c2464'::uuid, '46d6ffe3-66f7-545b-a2ac-2676a0fd062a'::uuid, 'Dans le point de coordonnées (−3 ; 5), que représente −3 ?', 'mcq', '["L’ordonnée","L’abscisse","L’altitude","La distance à l’origine"]'::jsonb, 1, 'La première coordonnée est toujours l’abscisse.', 1),
    ('10aadd23-0ede-5ea1-b30a-9b15524f3a13'::uuid, '46d6ffe3-66f7-545b-a2ac-2676a0fd062a'::uuid, 'Où se trouve le point de coordonnées (2 ; −4) ?', 'mcq', '["À gauche de l’axe des ordonnées, au-dessus de l’axe des abscisses","Sur l’axe des ordonnées","À droite de l’axe des ordonnées, en dessous de l’axe des abscisses","À l’origine"]'::jsonb, 2, 'Abscisse positive : à droite ; ordonnée négative : en dessous.', 2),
    ('4e1d73be-ccdb-5005-adf5-5ee3942f0e88'::uuid, '46d6ffe3-66f7-545b-a2ac-2676a0fd062a'::uuid, 'Quel est le symétrique de M(3 ; −2) par rapport à l’origine ?', 'mcq', '["(3 ; 2)","(−3 ; −2)","(−2 ; 3)","(−3 ; 2)"]'::jsonb, 3, 'La symétrie centrale de centre O change le signe des deux coordonnées.', 3),
    ('a767a888-b6d2-5ec4-8eb5-6d1f8ae85119'::uuid, '46d6ffe3-66f7-545b-a2ac-2676a0fd062a'::uuid, 'Quel est le symétrique de M(3 ; −2) par rapport à l’axe des ordonnées ?', 'mcq', '["(−3 ; −2)","(3 ; 2)","(−3 ; 2)","(2 ; −3)"]'::jsonb, 0, 'L’axe des ordonnées est vertical : seule l’abscisse change de signe.', 4),
    ('a68d17a6-2be3-5878-891f-7a69dc0d4ac8'::uuid, '46d6ffe3-66f7-545b-a2ac-2676a0fd062a'::uuid, 'Combien de coordonnées faut-il pour repérer un point dans l’espace ?', 'mcq', '["Une","Deux","Trois","Quatre"]'::jsonb, 2, 'Abscisse, ordonnée et altitude.', 5),
    ('f2ed261d-ceb4-580b-9aed-c4a07af341b6'::uuid, '46d6ffe3-66f7-545b-a2ac-2676a0fd062a'::uuid, 'Comment s’appelle la troisième coordonnée d’un point dans l’espace ?', 'mcq', '["L’altitude","La latitude","La longitude","La diagonale"]'::jsonb, 0, 'On dit aussi la cote : elle indique la hauteur.', 6),
    ('607d9c74-33da-5b40-91e6-c5839089dbc6'::uuid, '46d6ffe3-66f7-545b-a2ac-2676a0fd062a'::uuid, 'Dans un pavé ABCDEFGH, A est l’origine, B(4 ; 0 ; 0), D(0 ; 3 ; 0) et E(0 ; 0 ; 2). Quelles sont les coordonnées de G, opposé à A ?', 'mcq', '["(4 ; 0 ; 2)","(4 ; 3 ; 0)","(3 ; 4 ; 2)","(4 ; 3 ; 2)"]'::jsonb, 3, 'G cumule les trois longueurs : 4 en abscisse, 3 en ordonnée, 2 en altitude.', 7),
    ('90be0c71-1c87-59ef-9c04-d8ced884b41b'::uuid, '46d6ffe3-66f7-545b-a2ac-2676a0fd062a'::uuid, 'À partir de quoi mesure-t-on la latitude ?', 'mcq', '["Du méridien de Greenwich","De l’équateur","Du pôle Sud","De Paris"]'::jsonb, 1, 'La latitude va de 0° à l’équateur à 90° aux pôles.', 8),
    ('167f6f7b-be8c-53de-9ef9-055f9b6fc732'::uuid, '46d6ffe3-66f7-545b-a2ac-2676a0fd062a'::uuid, 'Quelle est la référence de la longitude ?', 'mcq', '["L’équateur","Le tropique du Cancer","Le méridien de Greenwich","Le pôle Nord"]'::jsonb, 2, 'La longitude se mesure vers l’Est ou l’Ouest depuis ce méridien, jusqu’à 180°.', 9),
    ('717bfedf-6d40-52c0-adc5-67e394989d96'::uuid, '46d6ffe3-66f7-545b-a2ac-2676a0fd062a'::uuid, 'Quelle est la latitude maximale possible ?', 'mcq', '["360°","180°","45°","90°"]'::jsonb, 3, 'Elle vaut 90° Nord au pôle Nord et 90° Sud au pôle Sud.', 10),
    ('13038757-bf27-57cf-bf46-924c9476faae'::uuid, '46d6ffe3-66f7-545b-a2ac-2676a0fd062a'::uuid, 'Tous les points de l’équateur ont une latitude de 0°.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’équateur est le parallèle de référence.', 11),
    ('b1d333ef-3949-5f90-b696-4d38bef166fe'::uuid, '46d6ffe3-66f7-545b-a2ac-2676a0fd062a'::uuid, 'Un point est situé sur l’axe des ordonnées. Que peut-on dire de ses coordonnées ?', 'mcq', '["Son ordonnée est nulle","Son abscisse est nulle","Ses deux coordonnées sont égales","Ses deux coordonnées sont positives"]'::jsonb, 1, 'Il n’a pas bougé de gauche à droite : son abscisse vaut 0.', 12),
    ('f2cae249-dcca-5b4f-a5b4-b9df8213ad0c'::uuid, '9de1454c-1e07-56a3-981f-063d9a00828c'::uuid, 'Quel est le développement de (x + 5)² ?', 'mcq', '["x² + 25","x² + 10x + 25","x² + 5x + 25","2x + 10"]'::jsonb, 1, 'Il ne faut pas oublier le double produit : 2 × x × 5 = 10x.', 1),
    ('227b6fd1-64fb-5ac7-b58b-e15f038f01ad'::uuid, '9de1454c-1e07-56a3-981f-063d9a00828c'::uuid, 'Quel est le développement de (2x − 3)² ?', 'mcq', '["4x² − 9","2x² − 12x + 9","4x² − 12x + 9","4x² − 6x + 9"]'::jsonb, 2, '(2x)² = 4x², double produit 2 × 2x × 3 = 12x, et (−3)² = 9.', 2),
    ('dc830a07-fe8a-57db-8e83-73abc0276998'::uuid, '9de1454c-1e07-56a3-981f-063d9a00828c'::uuid, 'Quel est le développement de (3x + 1)(3x − 1) ?', 'mcq', '["9x² − 1","9x² + 1","3x² − 1","9x² − 6x − 1"]'::jsonb, 0, 'C’est (a + b)(a − b) = a² − b², avec a = 3x et b = 1.', 3),
    ('476fb1cb-5ed0-5a56-8ce3-73642ddae624'::uuid, '9de1454c-1e07-56a3-981f-063d9a00828c'::uuid, 'Quelle est la forme factorisée de 25x² − 16 ?', 'mcq', '["(25x − 16)(25x + 16)","(5x − 4)²","(5x − 16)(5x + 1)","(5x − 4)(5x + 4)"]'::jsonb, 3, '25x² = (5x)² et 16 = 4² : c’est une différence de deux carrés.', 4),
    ('5577dc90-28bd-516f-aa79-04b39e6842bf'::uuid, '9de1454c-1e07-56a3-981f-063d9a00828c'::uuid, 'Quelle est la forme factorisée de x² + 6x + 9 ?', 'mcq', '["(x + 9)(x + 1)","(x + 3)²","x(x + 6) + 9","(x − 3)²"]'::jsonb, 1, 'On reconnaît a² + 2ab + b² avec a = x et b = 3.', 5),
    ('bf56159c-a50a-5310-ab99-a6ecd3c19e99'::uuid, '9de1454c-1e07-56a3-981f-063d9a00828c'::uuid, 'Quel calcul mental permet de trouver 49 × 51 ?', 'mcq', '["(50 − 1)(50 + 1) = 2 500 − 1 = 2 499","50 × 50 = 2 500","49 × 50 + 1 = 2 451","(50 + 1)² = 2 601"]'::jsonb, 0, 'C’est l’identité (a − b)(a + b) = a² − b².', 6),
    ('33c588d4-4833-5105-b4f9-8ee50335eb81'::uuid, '9de1454c-1e07-56a3-981f-063d9a00828c'::uuid, 'Combien vaut 101² ?', 'mcq', '["10 101","10 001","10 201","1 021"]'::jsonb, 2, '(100 + 1)² = 10 000 + 200 + 1 = 10 201.', 7),
    ('ce6c695b-d05a-5503-a5d7-8bfa92de0354'::uuid, '9de1454c-1e07-56a3-981f-063d9a00828c'::uuid, 'Quelle est la forme factorisée de (x + 2)(3x − 1) + (x + 2)(x + 4) ?', 'mcq', '["(x + 2)(4x + 3)","(x + 2)(2x − 5)","(x + 2)²(4x + 3)","(4x + 3)(3x − 1)"]'::jsonb, 0, 'On met (x + 2) en facteur : (3x − 1) + (x + 4) = 4x + 3.', 8),
    ('b1355fce-5065-5fc6-bd3f-a93656177247'::uuid, '9de1454c-1e07-56a3-981f-063d9a00828c'::uuid, 'Programme : ajouter 1 au nombre x, élever au carré, soustraire x². Que donne-t-il toujours ?', 'mcq', '["1","x²","2x","2x + 1"]'::jsonb, 3, '(x + 1)² − x² = x² + 2x + 1 − x² = 2x + 1.', 9),
    ('aa8c2702-41dc-573c-939c-9e9bb33698d4'::uuid, '9de1454c-1e07-56a3-981f-063d9a00828c'::uuid, 'Pour tous nombres a et b, (a + b)² = a² + b².', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Contre-exemple : (1 + 2)² = 9, alors que 1² + 2² = 5. Il manque 2ab.', 10),
    ('d7cec641-2d09-5494-b1b6-86c4f2f0c783'::uuid, '9de1454c-1e07-56a3-981f-063d9a00828c'::uuid, 'Que suffit-il de trouver pour prouver qu’une affirmation générale est fausse ?', 'mcq', '["Trois exemples","Un calcul avec une lettre","Un seul contre-exemple","Une figure"]'::jsonb, 2, 'Un seul cas où l’affirmation échoue suffit à la réfuter.', 11),
    ('70040abc-d4fc-5edb-ba25-85f9e6d1e3be'::uuid, '9de1454c-1e07-56a3-981f-063d9a00828c'::uuid, 'Quel est le développement de −(x − 3)² ?', 'mcq', '["−x² − 6x − 9","−x² + 6x − 9","x² − 6x + 9","−x² + 9"]'::jsonb, 1, 'On développe d’abord (x − 3)² = x² − 6x + 9, puis on change tous les signes.', 12),
    ('6d4a18df-3504-5854-9a87-32d8e3effea6'::uuid, 'cdf0c719-2ade-5fef-a7b2-d5446550b4e9'::uuid, 'Quelles sont les solutions de (2x + 1)(x − 3) = 0 ?', 'mcq', '["0,5 et −3","−0,5 et 3","−1 et 3","2 et 3"]'::jsonb, 1, '2x + 1 = 0 donne x = −0,5 ; x − 3 = 0 donne x = 3.', 1),
    ('fdf52815-aca6-55aa-9283-31671e271fa8'::uuid, 'cdf0c719-2ade-5fef-a7b2-d5446550b4e9'::uuid, 'Quelles sont les solutions de x² − 4x = 0 ?', 'mcq', '["4 seulement","−4 et 4","0 et 4","0 et −4"]'::jsonb, 2, 'On factorise : x(x − 4) = 0, donc x = 0 ou x = 4.', 2),
    ('d30c638b-7ba9-50a2-819e-bdb29e1c808f'::uuid, 'cdf0c719-2ade-5fef-a7b2-d5446550b4e9'::uuid, 'Quel est le premier réflexe pour résoudre x² − 4x = 0 ?', 'mcq', '["Diviser par x","Prendre la racine carrée","Ajouter 4x des deux côtés puis diviser par x","Factoriser"]'::jsonb, 3, 'La factorisation ramène à un produit nul ; diviser par x ferait perdre la solution 0.', 3),
    ('1b02488b-fc19-558d-a932-d84c32c6231e'::uuid, 'cdf0c719-2ade-5fef-a7b2-d5446550b4e9'::uuid, 'Quelle est la solution de l’inéquation 3x − 5 < 7 ?', 'mcq', '["x < 4","x > 4","x < 2/3","x < 12"]'::jsonb, 0, '3x < 12, puis on divise par 3, un nombre positif : le sens ne change pas.', 4),
    ('60ff8f94-93c2-5882-8602-6f7388c26b68'::uuid, 'cdf0c719-2ade-5fef-a7b2-d5446550b4e9'::uuid, 'Quelle est la solution de −2x + 1 ≥ 9 ?', 'mcq', '["x ≥ −4","x ≤ 4","x ≤ −4","x ≥ 4"]'::jsonb, 2, '−2x ≥ 8 ; en divisant par −2, négatif, on retourne l’inégalité : x ≤ −4.', 5),
    ('42de5b4f-dabe-58ec-9b52-ef10ab365057'::uuid, 'cdf0c719-2ade-5fef-a7b2-d5446550b4e9'::uuid, 'Que se passe-t-il quand on multiplie les deux membres d’une inéquation par un nombre négatif ?', 'mcq', '["Rien ne change","Le sens de l’inégalité s’inverse","L’inéquation devient une équation","On doit ajouter 1"]'::jsonb, 1, 'Exemple : 2 < 3, mais −2 > −3.', 6),
    ('33a41dfc-18ba-53a3-ae35-a2b047fc621b'::uuid, 'cdf0c719-2ade-5fef-a7b2-d5446550b4e9'::uuid, 'Le nombre 2 est-il solution de 5x − 3 > 8 ?', 'mcq', '["Oui, car 7 > 3","On ne peut pas savoir sans résoudre","Oui, car 2 est positif","Non, car 5 × 2 − 3 = 7 et 7 n’est pas supérieur à 8"]'::jsonb, 3, 'On teste une valeur en la remplaçant dans l’inéquation.', 7),
    ('d9a2115f-fecf-5ab1-b8d4-add679720cbe'::uuid, 'cdf0c719-2ade-5fef-a7b2-d5446550b4e9'::uuid, 'Trois entiers consécutifs ont pour somme 72. Quel est le plus petit ?', 'mcq', '["23","24","22","25"]'::jsonb, 0, 'x + (x + 1) + (x + 2) = 72, donc 3x = 69 et x = 23.', 8),
    ('5bf09628-da5d-51db-a091-8da770659ccb'::uuid, 'cdf0c719-2ade-5fef-a7b2-d5446550b4e9'::uuid, 'Les solutions de (x − 5)(x + 2) = 0 sont 5 et 2.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'x + 2 = 0 donne x = −2 : les solutions sont 5 et −2.', 9),
    ('3c5f8ad7-3c96-5e88-ab5f-40c0aa5360b4'::uuid, 'cdf0c719-2ade-5fef-a7b2-d5446550b4e9'::uuid, 'Comment représente-t-on les solutions de x ≥ 3 sur une droite graduée ?', 'mcq', '["Un trait de 3 vers la gauche","Un point en 3 seulement","Un trait de 3 vers la droite, 3 inclus","Un trait de 3 vers la droite, 3 exclu"]'::jsonb, 2, '« Supérieur ou égal » inclut 3, et les solutions sont les nombres plus grands.', 10),
    ('5b0db4e7-4af8-5f5d-8e12-eda32a51aeb5'::uuid, 'cdf0c719-2ade-5fef-a7b2-d5446550b4e9'::uuid, 'Quelles sont les solutions de x(x + 7) = 0 ?', 'mcq', '["0 et −7","0 et 7","−7 seulement","7 seulement"]'::jsonb, 0, 'x = 0 ou x + 7 = 0, c’est-à-dire x = −7.', 11),
    ('a1b066a2-d847-5693-bc70-b453c2ab84ad'::uuid, 'cdf0c719-2ade-5fef-a7b2-d5446550b4e9'::uuid, 'Léa a trois fois l’âge de son frère ; à eux deux, ils ont 48 ans. Avec x l’âge du frère, quelle équation traduit l’énoncé ?', 'mcq', '["3x = 48","x + 3 = 48","3(x + 48) = 0","x + 3x = 48"]'::jsonb, 3, 'L’âge du frère plus celui de Léa, 3x, font 48 : 4x = 48, soit x = 12.', 12),
    ('ad2cf206-3b32-57ed-a8e1-822c4d4aac35'::uuid, '11e44cbd-5960-55b2-b8c0-1609fd9e6f21'::uuid, 'Combien vaut √81 ?', 'mcq', '["−9","40,5","9","8,1"]'::jsonb, 2, '9² = 81 et 9 est positif.', 1),
    ('9e5b3c30-d291-509f-b149-b2d4b821662f'::uuid, '11e44cbd-5960-55b2-b8c0-1609fd9e6f21'::uuid, 'Entre quels entiers consécutifs se trouve √50 ?', 'mcq', '["7 et 8","6 et 7","24 et 25","5 et 6"]'::jsonb, 0, '49 < 50 < 64, donc 7 < √50 < 8.', 2),
    ('bb992f47-8fff-5981-93d5-1907dd3a8af2'::uuid, '11e44cbd-5960-55b2-b8c0-1609fd9e6f21'::uuid, 'Quelles sont les solutions de l’équation x² = 49 ?', 'mcq', '["7 seulement","24,5 et −24,5","−7 seulement","7 et −7"]'::jsonb, 3, '7² = 49 et (−7)² = 49 : deux solutions.', 3),
    ('7d1b8cb0-1dd2-53b6-8908-1ac24a5acd70'::uuid, '11e44cbd-5960-55b2-b8c0-1609fd9e6f21'::uuid, 'Combien de solutions a l’équation x² = −4 ?', 'mcq', '["Deux : 2 et −2","Aucune","Une : −2","Une : 2"]'::jsonb, 1, 'Un carré n’est jamais négatif.', 4),
    ('68ae28fa-f85b-500a-80fa-efe716ce5d23'::uuid, '11e44cbd-5960-55b2-b8c0-1609fd9e6f21'::uuid, 'Que vaut √(−9) ?', 'mcq', '["−3","3","Cela n’existe pas","−81"]'::jsonb, 2, 'La racine carrée n’est définie que pour un nombre positif ou nul.', 5),
    ('3c4e3524-f802-5566-9dbd-7015f0021537'::uuid, '11e44cbd-5960-55b2-b8c0-1609fd9e6f21'::uuid, 'Combien vaut (√7)² ?', 'mcq', '["49","7","√49","14"]'::jsonb, 1, 'Par définition, le carré de √7 vaut 7.', 6),
    ('a4e21c8c-23d1-52fe-a0aa-433b5c8d11b4'::uuid, '11e44cbd-5960-55b2-b8c0-1609fd9e6f21'::uuid, '√9 + √16 = √25.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '√9 + √16 = 3 + 4 = 7, alors que √25 = 5.', 7),
    ('e8a3c626-fb44-58b5-a965-f55f65ba4efe'::uuid, '11e44cbd-5960-55b2-b8c0-1609fd9e6f21'::uuid, 'Lequel de ces nombres est un carré parfait ?', 'mcq', '["140","150","160","144"]'::jsonb, 3, '144 = 12².', 8),
    ('0008ee10-5dae-53a4-a4ba-c1f882fc0636'::uuid, '11e44cbd-5960-55b2-b8c0-1609fd9e6f21'::uuid, 'Quelle est une valeur approchée de √2 ?', 'mcq', '["1,414","1,5","2,828","0,707"]'::jsonb, 0, '1,414² ≈ 1,999 : c’est √2 au millième près.', 9),
    ('a3ce3c7d-8a0e-57ff-a92a-7eed53d009b4'::uuid, '11e44cbd-5960-55b2-b8c0-1609fd9e6f21'::uuid, 'Un carré a une aire de 36 cm². Combien mesure son côté ?', 'mcq', '["9 cm","18 cm","6 cm","12 cm"]'::jsonb, 2, '√36 = 6 ; une longueur est positive, on garde une seule valeur.', 10),
    ('2f3b490a-7218-59b3-aa15-b51044a2c7bc'::uuid, '11e44cbd-5960-55b2-b8c0-1609fd9e6f21'::uuid, 'Quelles sont les solutions de x² = 10 ?', 'mcq', '["√10 et −√10","5 et −5","√10 seulement","100 et −100"]'::jsonb, 0, 'Comme 10 > 0, il y a deux solutions opposées.', 11),
    ('d465110c-dd42-581f-91f0-2ce71c2aeec2'::uuid, '11e44cbd-5960-55b2-b8c0-1609fd9e6f21'::uuid, 'La racine carrée d’un nombre positif est toujours positive ou nulle.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est la définition : √a est LE nombre positif dont le carré vaut a.', 12),
    ('55f36a1c-b4d0-5a6f-8f81-583f39f30aeb'::uuid, '0537e171-c6c1-5a7d-bec0-920f90c21ff9'::uuid, 'Quels sont le quotient et le reste de la division euclidienne de 187 par 12 ?', 'mcq', '["Quotient 15, reste 7","Quotient 15, reste 17","Quotient 16, reste 5","Quotient 14, reste 19"]'::jsonb, 0, '12 × 15 = 180 et 187 − 180 = 7, qui est bien inférieur à 12.', 1),
    ('e38135ac-1e46-5e9a-a9e1-0297c6b9e445'::uuid, '0537e171-c6c1-5a7d-bec0-920f90c21ff9'::uuid, 'Dans a = b × q + r, quelle condition doit vérifier le reste r ?', 'mcq', '["r < q","0 ≤ r < b","r > b","r est pair"]'::jsonb, 1, 'Le reste est positif ou nul et strictement inférieur au diviseur.', 2),
    ('027fcc2d-1691-5a21-8055-43af470b04e2'::uuid, '0537e171-c6c1-5a7d-bec0-920f90c21ff9'::uuid, 'Combien le nombre 36 a-t-il de diviseurs ?', 'mcq', '["6","8","9","12"]'::jsonb, 2, '1, 2, 3, 4, 6, 9, 12, 18, 36 : neuf diviseurs (6 × 6 ne compte qu’une fois).', 3),
    ('83beba6e-66c1-585e-b58a-dc82538a66d1'::uuid, '0537e171-c6c1-5a7d-bec0-920f90c21ff9'::uuid, 'Quel est le plus grand diviseur commun de 84 et 60 ?', 'mcq', '["6","4","24","12"]'::jsonb, 3, '84 = 2² × 3 × 7 et 60 = 2² × 3 × 5 : on garde 2² × 3 = 12.', 4),
    ('6c2c3336-5f51-550a-87c6-783af3ee54c2'::uuid, '0537e171-c6c1-5a7d-bec0-920f90c21ff9'::uuid, 'Avec 84 roses et 60 tulipes, on fait 12 bouquets identiques. Combien de roses par bouquet ?', 'mcq', '["5","7","12","14"]'::jsonb, 1, '84 ÷ 12 = 7 roses (et 60 ÷ 12 = 5 tulipes).', 5),
    ('1d4a11b4-ecdf-5413-a06f-749fd709c9c5'::uuid, '0537e171-c6c1-5a7d-bec0-920f90c21ff9'::uuid, 'Lequel de ces couples est formé de nombres premiers entre eux ?', 'mcq', '["12 et 18","14 et 21","15 et 28","9 et 33"]'::jsonb, 2, '15 = 3 × 5 et 28 = 2² × 7 n’ont aucun facteur premier commun.', 6),
    ('c512f4c7-e06f-50c0-b9af-7576c02f8729'::uuid, '0537e171-c6c1-5a7d-bec0-920f90c21ff9'::uuid, 'Deux bus partent ensemble à 8 h, l’un toutes les 6 min, l’autre toutes les 8 min. Quand repartent-ils ensemble ?', 'mcq', '["8 h 48","8 h 14","8 h 12","8 h 24"]'::jsonb, 3, '24 est le plus petit multiple commun de 6 et de 8.', 7),
    ('8bf6fc94-1c71-53ed-a25b-edfd9ca543e2'::uuid, '0537e171-c6c1-5a7d-bec0-920f90c21ff9'::uuid, '7 est un diviseur de 91.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '91 = 7 × 13 : le reste est nul.', 8),
    ('15e72bdd-2dce-558b-97d0-38088d590d64'::uuid, '0537e171-c6c1-5a7d-bec0-920f90c21ff9'::uuid, 'On range 250 œufs dans des boîtes de 12. Combien de boîtes sont pleines ?', 'mcq', '["21","20","22","10"]'::jsonb, 1, '250 = 12 × 20 + 10 : 20 boîtes pleines, et 10 œufs dans une 21e boîte.', 9),
    ('91acc4dc-bef2-5a06-bb20-dfe135275329'::uuid, '0537e171-c6c1-5a7d-bec0-920f90c21ff9'::uuid, 'Quel est le reste de la division euclidienne de 100 par 7 ?', 'mcq', '["2","3","4","14"]'::jsonb, 0, '7 × 14 = 98 et 100 − 98 = 2.', 10),
    ('715ad5c6-7e0a-5cc5-951e-7e2f9005be01'::uuid, '0537e171-c6c1-5a7d-bec0-920f90c21ff9'::uuid, 'Si le numérateur et le dénominateur d’une fraction sont premiers entre eux, la fraction est…', 'mcq', '["décimale","supérieure à 1","égale à 1","irréductible"]'::jsonb, 3, 'Aucun diviseur commun autre que 1 : on ne peut plus simplifier.', 11),
    ('caac69a5-c700-5f82-b527-51bc060ec7a7'::uuid, '0537e171-c6c1-5a7d-bec0-920f90c21ff9'::uuid, 'Si le reste de la division euclidienne de a par b est nul, alors b est un diviseur de a.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'a = b × q exactement : b divise a.', 12),
    ('dfabc02e-dd18-5884-bd13-7f15f0e714c5'::uuid, 'c008898c-8aa9-5ad8-8cca-41ff925d35f2'::uuid, 'Dans un diagramme circulaire, quel angle représente 25 % de l’effectif ?', 'mcq', '["25°","90°","45°","180°"]'::jsonb, 1, '0,25 × 360° = 90°, un quart de tour.', 1),
    ('82463f51-7c86-5d3b-bad6-119c8bcaa89d'::uuid, 'c008898c-8aa9-5ad8-8cca-41ff925d35f2'::uuid, 'Dans un diagramme circulaire, quel angle correspond à une fréquence de 0,15 ?', 'mcq', '["15°","36°","54°","150°"]'::jsonb, 2, '0,15 × 360 = 54°.', 2),
    ('0a14a649-86d7-5d83-a2b8-07603585c516'::uuid, 'c008898c-8aa9-5ad8-8cca-41ff925d35f2'::uuid, 'Par quel signe commence toujours une formule de tableur ?', 'mcq', '["=","+","#","*"]'::jsonb, 0, 'Sans le signe =, le tableur affiche le texte tel quel.', 3),
    ('793c57cd-2bbc-561e-8f31-baee2ddc0c32'::uuid, 'c008898c-8aa9-5ad8-8cca-41ff925d35f2'::uuid, 'Que calcule la formule =SOMME(B2:B5) ?', 'mcq', '["B2 + B5 seulement","La moyenne de B2 à B5","Le produit de B2 par B5","B2 + B3 + B4 + B5"]'::jsonb, 3, 'Les deux-points désignent toute la plage, de B2 à B5.', 4),
    ('41edf625-126d-5bef-bfc4-713f9b98f30d'::uuid, 'c008898c-8aa9-5ad8-8cca-41ff925d35f2'::uuid, 'La formule =3*A2+1, écrite en B2, est recopiée vers le bas. Que devient-elle en B3 ?', 'mcq', '["=3*A2+1","=3*B3+1","=3*A3+1","=4*A2+1"]'::jsonb, 2, 'La recopie décale la référence d’une ligne.', 5),
    ('cfa7def5-1296-535c-8c6f-66c5fbfe5b5c'::uuid, 'c008898c-8aa9-5ad8-8cca-41ff925d35f2'::uuid, 'La cellule A2 contient 4. Qu’affiche une cellule contenant =3*A2+1 ?', 'mcq', '["13","34","7","12"]'::jsonb, 0, '3 × 4 + 1 = 13.', 6),
    ('3dcc7d3e-c260-526c-bc48-5bf6d3ed0524'::uuid, 'c008898c-8aa9-5ad8-8cca-41ff925d35f2'::uuid, 'Quelle est la première chose à vérifier avant de lire un graphique ?', 'mcq', '["La couleur de la courbe","Ce que représentent les axes et leurs graduations","Le titre de l’exercice","Le nombre de points tracés"]'::jsonb, 1, 'Sans l’unité et la valeur d’un carreau, toute lecture est fausse.', 7),
    ('a90321a6-d23c-5372-99f3-70a2852d63dc'::uuid, 'c008898c-8aa9-5ad8-8cca-41ff925d35f2'::uuid, 'Deux courbes se croisent en un point. Que signifie ce point ?', 'mcq', '["Les deux grandeurs sont nulles","Les deux courbes sont parallèles","Une erreur de tracé","Les deux grandeurs ont la même valeur à cet instant"]'::jsonb, 3, 'Au point d’intersection, les deux courbes ont la même ordonnée.', 8),
    ('b6b8b39c-9a26-589f-8d92-915490237cb6'::uuid, 'c008898c-8aa9-5ad8-8cca-41ff925d35f2'::uuid, 'Sur un intervalle où la courbe descend de gauche à droite, la grandeur en ordonnée…', 'mcq', '["augmente","diminue","reste constante","devient négative"]'::jsonb, 1, 'Descendre quand l’abscisse augmente, c’est diminuer.', 9),
    ('50f7ce54-7754-54ca-86f9-b3d3fb7140e0'::uuid, 'c008898c-8aa9-5ad8-8cca-41ff925d35f2'::uuid, 'Combien de cellules compte la plage C2:C11 ?', 'mcq', '["9","11","10","2"]'::jsonb, 2, 'De la ligne 2 à la ligne 11 incluses : 11 − 2 + 1 = 10.', 10),
    ('d588fdda-8a96-5c24-a8a9-020eb3d4370f'::uuid, 'c008898c-8aa9-5ad8-8cca-41ff925d35f2'::uuid, 'Sur un graphique dont l’axe des ordonnées commence à 900, une petite hausse peut paraître énorme.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Un axe tronqué grossit les écarts : il faut lire les nombres, pas la forme.', 11),
    ('e14fe342-4f7b-52d2-80c7-6f48c10f06a0'::uuid, 'c008898c-8aa9-5ad8-8cca-41ff925d35f2'::uuid, 'Dans un diagramme en bâtons, qu’est-ce qui est proportionnel à l’effectif ?', 'mcq', '["La largeur des bâtons","La hauteur des bâtons","L’écart entre les bâtons","La couleur des bâtons"]'::jsonb, 1, 'Tous les bâtons ont la même largeur ; seule leur hauteur porte l’information.', 12),
    ('5ed75037-9b69-5763-ba9d-664034052d79'::uuid, '66a2d51f-876b-5008-8036-4cee206caa2d'::uuid, 'Quelle est l’aire d’un triangle de base 8 cm et de hauteur 5 cm ?', 'mcq', '["40 cm²","13 cm²","20 cm²","26 cm²"]'::jsonb, 2, 'base × hauteur ÷ 2 = 8 × 5 ÷ 2 = 20 cm².', 1),
    ('622a833e-5df0-5b87-a6fa-f82f80947a77'::uuid, '66a2d51f-876b-5008-8036-4cee206caa2d'::uuid, 'Quelle est l’aire d’un disque de rayon 3 cm ?', 'mcq', '["6π cm², environ 18,8 cm²","9π cm², environ 28,3 cm²","3π cm², environ 9,4 cm²","36π cm², environ 113 cm²"]'::jsonb, 1, 'π × r² = π × 9. Le périmètre, lui, vaudrait 6π cm.', 2),
    ('0f3b3276-86cf-5cb9-9c44-3cadc625e973'::uuid, '66a2d51f-876b-5008-8036-4cee206caa2d'::uuid, 'Comment calcule-t-on le volume d’un prisme droit ?', 'mcq', '["Aire de la base × hauteur ÷ 3","Périmètre de la base × hauteur","Aire de la base × hauteur","Longueur × largeur"]'::jsonb, 2, 'Tous les solides « droits » suivent la même formule.', 3),
    ('e237b649-7e89-5998-b062-98a12cefe2e5'::uuid, '66a2d51f-876b-5008-8036-4cee206caa2d'::uuid, 'Quelle est la contenance d’un aquarium de 60 cm × 30 cm × 40 cm ?', 'mcq', '["7,2 L","720 L","72 000 L","72 L"]'::jsonb, 3, '72 000 cm³ = 72 dm³ = 72 L.', 4),
    ('8fb91cb4-8800-5ee3-b02a-87b9a98351f0'::uuid, '66a2d51f-876b-5008-8036-4cee206caa2d'::uuid, 'Combien de cm² y a-t-il dans 1 m² ?', 'mcq', '["100","1 000","10 000","1 000 000"]'::jsonb, 2, '1 m² = 100 cm × 100 cm = 10 000 cm².', 5),
    ('c4956a39-6c4e-50eb-bc2f-d8051c2f330d'::uuid, '66a2d51f-876b-5008-8036-4cee206caa2d'::uuid, 'Combien de litres représentent 2,5 m³ ?', 'mcq', '["2 500 L","250 L","25 L","25 000 L"]'::jsonb, 0, '1 m³ = 1 000 L.', 6),
    ('265d21fc-8e6b-57d7-a279-9c3df5700d28'::uuid, '66a2d51f-876b-5008-8036-4cee206caa2d'::uuid, 'Quel est le volume d’un cône de rayon 3 cm et de hauteur 10 cm ?', 'mcq', '["90π cm³","30π cm³","10π cm³","60π cm³"]'::jsonb, 1, 'π × 9 × 10 ÷ 3 = 30π ≈ 94,2 cm³ : il ne faut pas oublier le tiers.', 7),
    ('40a05259-a04d-573e-89fb-2408195d00b2'::uuid, '66a2d51f-876b-5008-8036-4cee206caa2d'::uuid, 'Quel est le volume d’un cylindre de rayon 2 cm et de hauteur 5 cm ?', 'mcq', '["10π cm³","20π cm³","40π cm³","100π cm³"]'::jsonb, 1, 'π × 2² × 5 = 20π ≈ 62,8 cm³.', 8),
    ('bd79d73a-ea26-520e-bb43-d61a98ddbb19'::uuid, '66a2d51f-876b-5008-8036-4cee206caa2d'::uuid, 'Combien de m² y a-t-il dans un hectare ?', 'mcq', '["100 m²","1 000 m²","100 000 m²","10 000 m²"]'::jsonb, 3, 'Un hectare est un carré de 100 m de côté.', 9),
    ('44bf8d4e-9aa6-555d-a794-1d91c4a001e4'::uuid, '66a2d51f-876b-5008-8036-4cee206caa2d'::uuid, '1 dm³ correspond à 1 litre.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est l’équivalence de base entre volumes et contenances.', 10),
    ('5fc222c4-29d8-5ad4-ac3a-24c9702171af'::uuid, '66a2d51f-876b-5008-8036-4cee206caa2d'::uuid, 'Quel est le périmètre d’un cercle de rayon 5 cm ?', 'mcq', '["10π cm, environ 31,4 cm","25π cm, environ 78,5 cm","5π cm, environ 15,7 cm","100π cm"]'::jsonb, 0, 'Périmètre = 2 × π × r = 10π.', 11),
    ('a2a3798b-9046-5d10-bece-674c9f4f8b0a'::uuid, '66a2d51f-876b-5008-8036-4cee206caa2d'::uuid, 'Quelle est l’aire d’un trapèze de bases 10 cm et 6 cm, et de hauteur 4 cm ?', 'mcq', '["64 cm²","240 cm²","20 cm²","32 cm²"]'::jsonb, 3, '(10 + 6) × 4 ÷ 2 = 32 cm².', 12),
    ('3d7fe366-e691-5665-aad8-840c40aadbf4'::uuid, '5bbdfb79-4c47-5cae-9cab-99c6692ca57a'::uuid, 'Une figure est agrandie avec k = 3. Par combien son aire est-elle multipliée ?', 'mcq', '["3","6","27","9"]'::jsonb, 3, 'Les aires sont multipliées par k² = 9.', 1),
    ('cb014f4c-9cb2-51af-ad80-e712729c3440'::uuid, '5bbdfb79-4c47-5cae-9cab-99c6692ca57a'::uuid, 'Un solide est réduit avec k = 0,5. Par combien son volume est-il multiplié ?', 'mcq', '["0,5","0,125","0,25","1,5"]'::jsonb, 1, 'k³ = 0,5 × 0,5 × 0,5 = 0,125 : le volume est divisé par 8.', 2),
    ('8a89291f-d2c0-58ce-9d22-254a65408e30'::uuid, '5bbdfb79-4c47-5cae-9cab-99c6692ca57a'::uuid, 'Sur une carte au 1/25 000, deux villages sont à 4 cm. Quelle est la distance réelle ?', 'mcq', '["1 km","100 m","10 km","4 km"]'::jsonb, 0, '4 × 25 000 = 100 000 cm = 1 000 m = 1 km.', 3),
    ('c6d12860-3f18-5bac-b5da-845febe80592'::uuid, '5bbdfb79-4c47-5cae-9cab-99c6692ca57a'::uuid, 'Une voiture de 4,3 m est reproduite en maquette au 1/43. Quelle est la longueur de la maquette ?', 'mcq', '["43 cm","1 cm","10 cm","4,3 cm"]'::jsonb, 2, '430 cm ÷ 43 = 10 cm.', 4),
    ('a1cb0e32-5632-5b6c-a294-ee767bc317c5'::uuid, '5bbdfb79-4c47-5cae-9cab-99c6692ca57a'::uuid, 'Les aires d’une figure ont été multipliées par 16. Par combien ses longueurs l’ont-elles été ?', 'mcq', '["16","8","256","4"]'::jsonb, 3, 'k² = 16, donc k = 4.', 5),
    ('c3ff7dc8-ef21-581b-801e-ef62d884694b'::uuid, '5bbdfb79-4c47-5cae-9cab-99c6692ca57a'::uuid, 'Les volumes d’un solide sont divisés par 8. Quel est le coefficient de réduction ?', 'mcq', '["1/8","1/2","1/4","2"]'::jsonb, 1, 'k³ = 1/8, donc k = 1/2.', 6),
    ('17f8f5e3-d451-5ab6-8aa6-e9f9ac1709ba'::uuid, '5bbdfb79-4c47-5cae-9cab-99c6692ca57a'::uuid, 'Une pyramide de volume 240 cm³ est coupée au milieu de sa hauteur, parallèlement à la base. Quel est le volume de la petite pyramide ?', 'mcq', '["30 cm³","120 cm³","60 cm³","80 cm³"]'::jsonb, 0, 'k = 1/2, donc V = 240 × 1/8 = 30 cm³.', 7),
    ('d25dd210-2a4a-53ba-94d1-532fcda5e84f'::uuid, '5bbdfb79-4c47-5cae-9cab-99c6692ca57a'::uuid, 'Un rectangle de 6 cm × 4 cm est agrandi avec k = 1,5. Quelle est l’aire de l’image ?', 'mcq', '["36 cm²","54 cm²","24 cm²","60 cm²"]'::jsonb, 1, '24 × 1,5² = 24 × 2,25 = 54 cm², soit 9 × 6.', 8),
    ('7553cfcc-2a7f-5d9f-bf0b-39132e33df26'::uuid, '5bbdfb79-4c47-5cae-9cab-99c6692ca57a'::uuid, 'Un agrandissement ou une réduction conserve les angles.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La forme est conservée : seules les dimensions changent.', 9),
    ('37809909-f828-5221-a19e-75ba9722694d'::uuid, '5bbdfb79-4c47-5cae-9cab-99c6692ca57a'::uuid, 'Un segment de 5 cm devient un segment de 2 cm. Quel est le coefficient ?', 'mcq', '["2,5","0,4","3","−3"]'::jsonb, 1, 'k = longueur de l’image ÷ longueur de départ = 2 ÷ 5 = 0,4.', 10),
    ('e12820a4-0c10-503d-bbd9-0ba0f55b8a89'::uuid, '5bbdfb79-4c47-5cae-9cab-99c6692ca57a'::uuid, 'Si l’on double toutes les dimensions d’une boîte, on peut y mettre deux fois plus de sable.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le volume est multiplié par 2³ = 8.', 11),
    ('27e65f8d-a7d8-550b-9fd4-4a14178dc7db'::uuid, '5bbdfb79-4c47-5cae-9cab-99c6692ca57a'::uuid, 'Sur un plan au 1/100, quelle surface occupe une pièce de 12 m² ?', 'mcq', '["1 200 cm²","120 cm²","0,12 cm²","12 cm²"]'::jsonb, 3, 'Les aires sont divisées par 100² = 10 000 : 120 000 cm² ÷ 10 000 = 12 cm².', 12),
    ('79e5d809-88f1-532a-ba19-5e5155fa4982'::uuid, '350d1104-08ce-5b51-802f-9cf483ae3e2d'::uuid, 'Combien de temps dure la partie automatismes de l’épreuve de maths du brevet ?', 'mcq', '["10 min","20 min","30 min","1 h"]'::jsonb, 1, 'Elle dure 20 minutes et elle est ramassée à la fin de ce temps.', 1),
    ('a2b58dcc-07bc-543e-acae-a964cf0f16e1'::uuid, '350d1104-08ce-5b51-802f-9cf483ae3e2d'::uuid, 'La calculatrice est-elle autorisée dans la partie automatismes ?', 'mcq', '["Oui, en mode examen","Oui, sans restriction","Seulement pour les fractions","Non, elle est interdite"]'::jsonb, 3, 'Les automatismes se font sans calculatrice ; elle est autorisée dans la partie 2.', 2),
    ('7a17f741-f373-554d-8133-a4332793cc1f'::uuid, '350d1104-08ce-5b51-802f-9cf483ae3e2d'::uuid, 'Sur combien de points est notée la partie automatismes ?', 'mcq', '["6 points sur 20","14 points sur 20","2 points sur 20","10 points sur 20"]'::jsonb, 0, 'Automatismes : 6 points ; raisonnement et résolution de problèmes : 14 points.', 3),
    ('8428afb4-6569-597e-bd77-fc15eed35a49'::uuid, '350d1104-08ce-5b51-802f-9cf483ae3e2d'::uuid, 'Que faire face à une question d’automatisme qui bloque ?', 'mcq', '["Rester dessus jusqu’à trouver","La passer et y revenir à la fin","Rendre la copie","Répondre au hasard sans relire"]'::jsonb, 1, 'Toutes les questions rapportent à peu près autant : ne pas y laisser son temps.', 4),
    ('6c7d2c1b-f749-595e-858d-cad384c8b287'::uuid, '350d1104-08ce-5b51-802f-9cf483ae3e2d'::uuid, 'Que faut-il écrire avant d’appliquer le théorème de Pythagore ?', 'mcq', '["La valeur de π","Que les droites sont parallèles","Que le triangle est rectangle, et en quel sommet","La formule du cosinus"]'::jsonb, 2, 'C’est l’hypothèse du théorème : sans elle, le raisonnement est incomplet.', 5),
    ('ef960a93-6357-59db-b2c5-105733f78665'::uuid, '350d1104-08ce-5b51-802f-9cf483ae3e2d'::uuid, 'Dans la partie 2, une recherche incomplète mais bien présentée peut rapporter des points.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les correcteurs valorisent les démarches entamées : on n’efface pas un calcul commencé.', 6),
    ('35bbd364-c435-5fe6-91da-b2655b04f5f6'::uuid, '350d1104-08ce-5b51-802f-9cf483ae3e2d'::uuid, 'Combien de points la partie 2 réserve-t-elle à la rédaction et à la clarté du raisonnement ?', 'mcq', '["6 points","1 point","2 points","4 points"]'::jsonb, 2, 'La partie 2 compte 12 points d’exercices et 2 points de rédaction.', 7),
    ('73f46b38-8342-5e54-9541-3d8d67ac5a98'::uuid, '350d1104-08ce-5b51-802f-9cf483ae3e2d'::uuid, 'Comment présenter un résultat numérique dans la partie 2 ?', 'mcq', '["Avec l’arrondi demandé, l’unité et une phrase de conclusion","Avec le plus de décimales possible","Sans unité, pour gagner du temps","En écriture scientifique obligatoirement"]'::jsonb, 0, 'L’arrondi et l’unité font partie de la réponse attendue.', 8),
    ('8bbc3090-8a88-5fd1-bad0-a890dd7db8d8'::uuid, '350d1104-08ce-5b51-802f-9cf483ae3e2d'::uuid, 'Automatisme : combien valent les 3/4 de 20 ?', 'mcq', '["12","15","16","5"]'::jsonb, 1, '20 ÷ 4 = 5, puis 5 × 3 = 15.', 9),
    ('1692fb5a-a7db-593f-a47d-4c9a769bc8a0'::uuid, '350d1104-08ce-5b51-802f-9cf483ae3e2d'::uuid, 'Automatisme : combien vaut 10 % de 350 ?', 'mcq', '["3,5","350","35","36"]'::jsonb, 2, 'Prendre 10 %, c’est diviser par 10.', 10),
    ('6ff60a78-1723-5b0f-9a3b-3e5b0fe69be9'::uuid, '350d1104-08ce-5b51-802f-9cf483ae3e2d'::uuid, 'Automatisme : quelle est la solution de 2x + 3 = 11 ?', 'mcq', '["x = 7","x = 5,5","x = 8","x = 4"]'::jsonb, 3, '2x = 8, donc x = 4.', 11),
    ('a0b71c9f-9028-58b2-9d0a-0b7f955c624d'::uuid, '350d1104-08ce-5b51-802f-9cf483ae3e2d'::uuid, 'Dans la partie 2, on peut donner un résultat sans justification quand on est sûr de soi.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Toute réponse doit être justifiée, sauf indication contraire de l’énoncé.', 12)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('allemand', 'anglais', 'anglais', 'anglais', 'francais', 'maths', 'maths');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('allemand', 'anglais', 'anglais', 'anglais', 'francais', 'maths', 'maths')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 385 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 385 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
